    align-items: flex-start;
  }

  .help-hero h1 {
    font-size: 32px;
  }

  .help-hero-icon {
    width: 60px;
    height: 60px;
  }

  .help-side {
    display: flex;
  }

  .faq-section {
    padding: 18px;
  }

  .faq-question {
