/* =========================================================
   PRIMARY ACTION EMPHASIS
========================================================= */

.home-primary-action,
.landing-primary-action,
.contact-primary-button,
.sms-modal-done,
.token-new-booking-action,
.app-button:not(.secondary):not(.success):not(.warning):not(.danger) {
  position: relative;

  overflow: hidden;
}

.home-primary-action::after,
.landing-primary-action::after,
.contact-primary-button::after,
.sms-modal-done::after,
.token-new-booking-action::after,
.app-button:not(.secondary):not(.success):not(.warning):not(.danger)::after {
  content: "";

  position: absolute;

  top: 0;
  bottom: 0;
  left: -40%;

  width: 28%;

  transform: skewX(-18deg);

  background:
    rgba(255, 255, 255, 0.09);

  transition:
    left 420ms ease;

  pointer-events: none;
}

.home-primary-action:hover::after,
.landing-primary-action:hover::after,
.contact-primary-button:hover::after,
.sms-modal-done:hover::after,
.token-new-booking-action:hover::after,
