  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-view-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  color: var(--primary);

  font-size: 8px;
  font-weight: 800;
}


/* STATUS LIST */

.admin-status-list {
  padding-top: 5px;
}

.admin-status-row {
  min-height: 61px;

  display: flex;
  align-items: center;

  gap: 10px;

  border-bottom: 1px solid var(--border);
}

.admin-status-row:last-child {
  border-bottom: 0;
}

.admin-status-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);
}

.admin-status-row > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.admin-status-row > div:nth-child(2) strong,
.admin-status-row > div:nth-child(2) span {
  display: block;
}

.admin-status-row > div:nth-child(2) strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.admin-status-row > div:nth-child(2) span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.admin-status-count {
  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 18px;
}


/* ACTIONS */

.admin-action-grid {
  padding-top: 13px;

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 8px;
}

.admin-action-button {
  min-height: 91px;

  padding: 11px;

  display: flex;

  flex-direction: column;

  align-items: flex-start;

  justify-content: space-between;

  border: 1px solid var(--border);

  border-radius: 12px;

  color: var(--text-body);

  background: var(--surface-soft);
}

.admin-action-button:hover {
  color: var(--primary);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 22%,
      var(--border)
    );

  background: var(--surface-hover);

  transform: translateY(-2px);
}

.admin-action-button > div {
  width: 31px;
  height: 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);
}

.admin-action-button > span {
  color: var(--text-strong);

  font-size: 9px;
  font-weight: 800;
}

.admin-action-button > svg {
  align-self: flex-end;

  color: var(--text-faint);
}


/* RECENT TABLE */

.admin-recent-card {
  overflow: hidden;
}

.admin-booking-table {
  margin-top: 4px;
}

.admin-table-head,
.admin-table-row {
  display: grid;

  grid-template-columns:
    0.5fr
    1fr
    1.25fr
    0.75fr
    0.8fr;

  align-items: center;

  gap: 10px;
}

.admin-table-head {
  min-height: 39px;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.admin-table-row {
  min-height: 53px;

  border-top: 1px solid var(--border);

  color: var(--text-body);

  font-size: 8px;
}

.admin-table-row:hover {
  color: var(--primary);

  background: var(--surface-hover);
}

.admin-table-row strong {
  color: var(--primary);

  font-size: 10px;
}

.admin-table-row span {
  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.admin-empty {
  padding: 35px 0;

  color: var(--text-muted);

  font-size: 11px;

  text-align: center;
}


/* ADMIN RESPONSIVE */

@media (max-width: 1100px) {
  .admin-stat-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 800px) {
  .admin-dashboard-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .admin-center-selector {
    width: 100%;
  }

  .admin-dashboard-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 650px) {
  .admin-dashboard-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .admin-stat-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-queue-card,
  .admin-actions-card,
  .admin-recent-card {
    padding: 17px;
  }

  .admin-table-head {
    display: none;
  }

  .admin-table-row {
    grid-template-columns:
      0.5fr
      1fr
      0.8fr;

    padding: 11px 0;
  }

  .admin-table-row span:nth-child(3) {
    display: none;
  }
}

@media (max-width: 430px) {
  .admin-stat-grid {
    grid-template-columns: 1fr;
  }

  .admin-action-grid {
    grid-template-columns: 1fr;
  }
}
