.payment-farmer strong,
.payment-farmer span {
  display: flex;

  align-items: center;

  gap: 4px;
}

.payment-farmer strong {
  color: var(--text-strong);

  font-size: 11px;
}

.payment-farmer span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 8px;
}

.payment-summary {
  margin-top: 18px;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;
}

.payment-summary > div {
  min-height: 67px;

  padding: 10px;

  border: 1px solid var(--border);

  border-radius: 11px;

  background: var(--surface-soft);
}

.payment-summary span,
.payment-summary strong {
  display: block;
}

.payment-summary span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;
}

.payment-summary strong {
  margin-top: 7px;

  color: var(--text-strong);

  font-size: 10px;
}

.payment-amount-card {
  margin-top: 14px;

  padding: 17px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 18%,
      var(--border)
    );

  border-radius: 14px;

  background:
    color-mix(
      in srgb,
      var(--success) 5%,
      var(--surface)
    );
}

.payment-amount-card span {
  display: block;

  color: var(--success);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;
}

.payment-amount-card strong {
  display: block;

  margin-top: 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 28px;
}

.payment-amount-icon {
  width: 46px;
  height: 46px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  color: var(--success);

  background: var(--success-soft);
}


/* METHOD */

.payment-method-section,
.payment-reference-section {
  margin-top: 21px;
}

.payment-method-section label,
.payment-reference-section label {
  display: block;

  margin-bottom: 8px;

  color: var(--text-strong);

  font-size: 9px;

  font-weight: 800;
}

.payment-methods {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 7px;
}

.payment-methods button {
  min-height: 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 5px;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 8px;

  font-weight: 800;
}

.payment-methods button:hover {
  background: var(--surface-hover);
}

.payment-methods button.active {
  color: var(--primary);

  border-color: var(--primary);

  background: var(--primary-soft);
}

.payment-reference-section input {
  width: 100%;

  height: 48px;

  padding: 0 11px;

  border: 1px solid var(--border);

  border-radius: 10px;

  outline: 0;

  color: var(--text-strong);

  background: var(--surface-soft);

  font-size: 10px;
}

.payment-reference-section input:focus {
  border-color: var(--primary);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--primary) 9%,
        transparent
      );
}

.payment-reference-section small {
  display: block;

  margin-top: 5px;

  color: var(--text-muted);

  font-size: 7px;
}

.payment-release-button {
  width: 100%;

  min-height: 48px;

  margin-top: 17px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  color: var(--text-on-primary);

  background: var(--primary);

  font-size: 9px;

  font-weight: 800;
}

.payment-release-button:hover {
  background: var(--primary-strong);

  transform: translateY(-1px);
}


/* SUCCESS */

.payment-success {
  margin-top: 18px;

  padding: 13px;

  display: flex;

  align-items: center;

  gap: 9px;

  border-radius: 11px;

  color: var(--success);

  background: var(--success-soft);
}

.payment-success-icon {
  width: 31px;
  height: 31px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--success);

  background: var(--surface);
}

.payment-success strong,
.payment-success span {
  display: block;
}

.payment-success strong {
  font-size: 9px;
}

.payment-success span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.payment-notice {
  margin-top: 15px;

  padding-top: 13px;

  display: flex;

  align-items: flex-start;

  gap: 6px;

  border-top: 1px solid var(--border);

  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.5;
}

.payment-notice svg {
  flex: 0 0 auto;

  color: var(--primary);
}


/* RESPONSIVE */

@media (max-width: 850px) {
  .payment-layout {
    grid-template-columns: 1fr;
  }

  .payment-list-card {
    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .payment-list-heading {
    grid-column: 1 / -1;
  }
}

@media (max-width: 600px) {
  .admin-payments-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .payment-list-card {
    display: block;
  }

  .payment-main-card {
    padding: 18px;
  }

  .payment-summary,
  .payment-methods {
    grid-template-columns: 1fr;
  }

  .payment-amount-card strong {
    font-size: 24px;
  }
}
