  min-width: 0;

  display: flex;

  align-items: center;

  gap: 10px;
}


.register-select-icon {
  width: 35px;
  height: 35px;

  flex: 0 0 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #287eae;

  background: #e6f3f9;
