  color: #29485b;

  font-size: 11px;

  font-weight: 800;

  white-space: nowrap;

  text-overflow: ellipsis;
}


.register-select-main span {
  overflow: hidden;

  color: #8698a2;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


