========================================================= */

@media (max-width: 1000px) {

  .register-layout {
    grid-template-columns: 1fr;

    gap: 45px;
  }


  .register-intro {
    max-width: 760px;

    padding-top: 0;
  }


  .register-form-card {
    max-width: 650px;
  }

}


@media (max-width: 620px) {

  .register-container {
    padding:
      24px
      16px
      55px;
  }


  .register-intro h1 {
    font-size: 43px;
  }


  .register-intro > p {
    font-size: 14px;
  }


  .register-form-card {
    padding: 23px 19px;

    border-radius: 20px;
  }


  .register-two-column {
    grid-template-columns: 1fr;

    gap: 0;
  }


  .language-options {
    grid-template-columns: 1fr;
  }


  .register-submit-area {
    align-items: stretch;

    flex-direction: column;
  }


  .register-submit-area .button {
    width: 100%;
  }


  .register-terms {
    text-align: left;
  }

}
/* =========================================================
   FARMER BOOKING PAGE
========================================================= */

.farmer-book-page {
  min-height: 100vh;
  color: #193b50;
  background:
    radial-gradient(
      circle at 4% 8%,
      rgba(33, 139, 82, 0.07),
      transparent 24%
    ),
    radial-gradient(
      circle at 96% 20%,
      rgba(242, 186, 66, 0.09),
      transparent 25%
    ),
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f7faf8 100%
    );
}

.booking-container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 38px 28px 75px;
}


/* =========================================================
   TOP
========================================================= */

.booking-top-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 38px;
}

.booking-top-row .page-eyebrow {
  display: inline-block;
  margin-top: 12px;
}

.booking-top-row h1 {
  margin: 7px 0 10px;
  color: #193b50;
  font-family: var(--font-heading);
  font-size: clamp(39px, 4.4vw, 56px);
  line-height: 1.02;
  letter-spacing: -0.035em;
}

.booking-top-row p {
  max-width: 680px;
  margin: 0;
  color: #6f8590;
  font-size: 15px;
  line-height: 1.7;
}


/* =========================================================
   STEP INDICATOR
========================================================= */

.booking-step-indicator {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  padding-bottom: 5px;
}

.booking-step {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #9aaab3;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.booking-step span {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce5e9;
  border-radius: 50%;
  color: #8c9da7;
  background: #ffffff;
  font-size: 10px;
  font-weight: 900;
}

.booking-step.active {
  color: #218b52;
}

.booking-step.active span {
  border-color: #8fc3a1;
  color: #ffffff;
  background: #218b52;
}

.booking-step-line {
  width: 32px;
  height: 1px;
  margin: 0 10px;
  background: #dce5e9;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.booking-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 22px;
  align-items: start;
}

.booking-form-column {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.booking-panel {
  padding: 27px;
  border: 1px solid #dce7eb;
  border-radius: 23px;
  background: #ffffff;
  box-shadow:
    0 16px 42px rgba(30, 63, 77, 0.06);
}


/* =========================================================
   PANEL HEADINGS
========================================================= */

.booking-panel-heading {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-bottom: 25px;
}

.panel-icon {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  color: #218b52;
  background: #e7f5eb;
}

.booking-panel-heading h2 {
  margin: 1px 0 5px;
  color: #28475a;
  font-family: var(--font-heading);
  font-size: 22px;
}

.booking-panel-heading p {
  margin: 0;
  color: #81929d;
  font-size: 10px;
  line-height: 1.55;
}


/* =========================================================
   FORM
========================================================= */

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.booking-form-field {
  position: relative;
}

.booking-form-field label {
  display: block;
  margin-bottom: 8px;
  color: #2d4a5b;
  font-size: 11px;
  font-weight: 900;
}

.booking-form-field input {
  color: #29485b;
}

.quantity-input {
  height: 52px;

  display: flex;
  align-items: center;
  gap: 9px;

  padding: 0 13px;

  border: 1px solid #d7e2e7;
  border-radius: 12px;

  color: #718692;
  background: #f9fbfc;
}

.quantity-input:focus-within {
  border-color: #218b52;
  background: #ffffff;
  box-shadow:
    0 0 0 4px rgba(33, 139, 82, 0.08);
}

.quantity-input input {
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 13px;
}

.quantity-input span {
  color: #718795;
  font-size: 11px;
  font-weight: 900;
}

.booking-input-error {
  border-color: #df7a70;
  background: #fff7f5;
}

.quantity-note {
  display: flex;
  align-items: center;
  gap: 9px;

  margin-top: 13px;

  color: #81929c;

  font-size: 9px;
  line-height: 1.5;
}

.quantity-note span {
  padding: 4px 7px;
  border-radius: 6px;
  color: #a36e18;
  background: #fff1d0;
  font-size: 8px;
  font-weight: 900;
}


/* =========================================================
   CUSTOM SELECT
========================================================= */

.custom-select {
  position: relative;
}

.select-control {
  width: 100%;
  min-height: 55px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  padding: 9px 13px;

  border: 1px solid #d7e2e7;
  border-radius: 12px;

  color: #718692;
  background: #f9fbfc;

  cursor: pointer;
  text-align: left;
}

.select-control:hover {
  border-color: #b8d0da;
  background: #ffffff;
}

.select-main {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.select-main > span {
  color: #29485b;
  font-size: 11px;
  font-weight: 800;
}

.crop-visual {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.crop-visual.wheat {
  color: #c48a1c;
  background: #fff1d0;
}

.crop-visual.rice {
  color: #4d9c62;
  background: #e7f5e9;
}

.crop-visual.cotton {
  color: #8d68ad;
  background: #f0eafa;
}

.crop-visual-maize,
.crop-visual.maize {
  color: #d98b27;
  background: #fff0d5;
}

.crop-visual-large {
  width: 58px;
  height: 58px;
  border-radius: 16px;
}

.crop-visual-small {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
}

.select-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% + 7px);
  left: 0;
  right: 0;

  max-height: 240px;
  overflow-y: auto;

  padding: 6px;

  border: 1px solid #d9e5e9;
  border-radius: 13px;

  background: #ffffff;

  box-shadow:
    0 18px 45px rgba(29, 61, 76, 0.15);
}

.select-option,
.center-option {
  width: 100%;

  display: flex;
  align-items: center;
  gap: 10px;

  padding: 10px;

  border: 0;
  border-radius: 9px;

  color: #315367;
  background: transparent;

  cursor: pointer;
  text-align: left;
}

.select-option:hover,
.center-option:hover {
  background: #f4f8fa;
}

.select-option.selected,
.center-option.selected {
  background: #edf8f0;
}

.select-option > span,
.center-option > div:nth-child(2) {
  min-width: 0;
}

.center-select-icon {
  width: 36px;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex: 0 0 36px;

  border-radius: 10px;

  color: #277eaa;
  background: #e6f3f8;
}

.center-select-text {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.center-select-text strong,
.center-option strong {
  color: #2d4a5b;
  font-size: 11px;
}

.center-select-text span,
.center-option span {
  overflow: hidden;
  color: #8798a2;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.center-option-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #277eaa;
  background: #e6f3f8;
}

.select-option > svg:last-child,
.center-option > svg:last-child {
  margin-left: auto;
  color: #218b52;
}


/* =========================================================
   DATE OPTIONS
========================================================= */

.date-field {
  margin-top: 22px;
}

.date-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.date-option {
  position: relative;

  min-height: 88px;

  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;

  padding: 13px;

  border: 1px solid #dce6eb;
  border-radius: 13px;

  color: #708591;
  background: #fafcfd;

  cursor: pointer;
  text-align: left;
}

.date-option:hover {
  border-color: #b9d3dd;
  background: #ffffff;
}

.date-option.selected {
  border-color: #9ac8a8;
  color: #218b52;
  background: #eef8f0;
}

.date-option span {
  font-size: 9px;
  font-weight: 800;
}

.date-option strong {
  margin-top: 3px;
  color: #29485b;
  font-family: var(--font-heading);
  font-size: 27px;
}

.date-option small {
  margin-top: 1px;
  color: #8597a1;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.date-check {
  position: absolute;

  top: 9px;
  right: 9px;

  width: 22px;
  height: 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;
  background: #218b52;
}


/* =========================================================
   BUTTON
========================================================= */

.booking-error {
  margin: 18px 0;

  padding: 12px 14px;

  border: 1px solid #f0d2cd;
  border-radius: 10px;

  color: #b34c43;
  background: #fff3f0;

  font-size: 10px;
  font-weight: 700;
  line-height: 1.5;
}


/* =========================================================
   SUMMARY CARD
========================================================= */

.booking-summary-column {
  position: sticky;
  top: 100px;
}

.booking-summary-card {
  padding: 23px;

  border: 1px solid #dce7eb;
  border-radius: 22px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f8fbf9
    );

  box-shadow:
    0 18px 46px rgba(30, 63, 77, 0.08);
}

.summary-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding-bottom: 16px;

  border-bottom: 1px solid #e9eef1;

  color: #547182;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.summary-header svg {
  color: #218b52;
}

.summary-crop {
  display: flex;
  align-items: center;
  gap: 12px;

  padding: 18px 0;
}

.summary-crop > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-crop span {
  color: #83949d;
  font-size: 8px;
  font-weight: 900;
}

.summary-crop strong {
  color: #29495b;
  font-size: 14px;
}

.summary-list {
  display: flex;
  flex-direction: column;

  border-top: 1px solid #edf1f3;
  border-bottom: 1px solid #edf1f3;
}

.summary-list > div {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;

  padding: 14px 0;

  border-bottom: 1px solid #edf1f3;
}

.summary-list > div:last-child {
  border-bottom: 0;
}

.summary-list span {
  color: #80919a;
  font-size: 9px;
}

.summary-list strong {
  max-width: 55%;

  color: #315064;

  font-size: 10px;
  font-weight: 900;

  text-align: right;
}

.summary-available {
  display: flex;
  align-items: center;
  gap: 10px;

  margin-top: 16px;
  padding: 12px;

  border-radius: 12px;

  background: #edf8f0;
}

.summary-available-icon {
  width: 30px;
  height: 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex: 0 0 30px;

  border-radius: 9px;

  color: #ffffff;
  background: #218b52;
}

.summary-available > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.summary-available strong {
  color: #2c6143;
  font-size: 10px;
}

.summary-available span {
  color: #789184;
  font-size: 8px;
}


/* =========================================================
   AVAILABILITY
========================================================= */

.availability-section {
  margin-top: 24px;
  padding: 32px;

  border: 1px solid #dce7eb;
  border-radius: 24px;

  background: #ffffff;

  box-shadow:
    0 18px 48px rgba(30, 63, 77, 0.06);
}

.availability-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 24px;
}

.availability-heading .page-eyebrow {
  display: inline-block;
  margin-bottom: 6px;
}

.availability-heading h2 {
  margin: 0;

  color: #26465a;

  font-family: var(--font-heading);
  font-size: 30px;
}

.availability-heading p {
  margin: 8px 0 0;

  color: #788d98;

  font-size: 11px;
}

.availability-heading p strong {
  color: #356177;
}

.capacity-note {
  min-width: 120px;

  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;

  padding: 12px 14px;

  border-radius: 12px;

  background: #f4f8fa;
}

.capacity-note span {
  color: #83959f;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.capacity-note strong {
  color: #277caf;

  font-family: var(--font-heading);
  font-size: 23px;
}

.slot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);

  gap: 14px;

  margin-top: 28px;
}

.slot-card {
  position: relative;

  min-height: 195px;

  display: flex;
  flex-direction: column;
  align-items: flex-start;

  padding: 18px;

  border: 1px solid #dce6eb;
  border-radius: 17px;

  color: inherit;
  background: #fbfcfd;

  cursor: pointer;
  text-align: left;

  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.slot-card:hover:not(:disabled) {
  transform: translateY(-3px);

  border-color: #b6d2dd;

  background: #ffffff;

  box-shadow:
    0 12px 26px rgba(28, 61, 75, 0.07);
}

.slot-card.selected {
  border-color: #84bf97;

  background: #eef8f0;

  box-shadow:
    0 0 0 3px rgba(33, 139, 82, 0.07);
}

.slot-card.slot-full {
  opacity: 0.55;
  cursor: not-allowed;
}

.slot-top {
  width: 100%;

  display: flex;
  align-items: center;
  justify-content: space-between;
}

.slot-icon {
  width: 41px;
  height: 41px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #277caf;
  background: #e5f2f8;
}

.slot-check {
  width: 24px;
  height: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;
  background: #218b52;
}

.slot-time {
  margin-top: 18px;

  color: #2a495c;

  font-size: 14px;
  font-weight: 900;
}

.slot-load {
  margin-top: 10px;

  padding: 5px 8px;

  border-radius: 999px;

  font-size: 8px;
  font-weight: 900;
}

.slot-load.normal {
  color: #218b52;
  background: #e5f4e9;
}

.slot-load.limited {
  color: #bc811c;
  background: #fff1d0;
}

.slot-load.busy {
  color: #c45a40;
  background: #ffebe5;
}

.slot-bottom {
  width: 100%;

  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: auto;
  padding-top: 20px;

  color: #81929b;

  font-size: 9px;
}

.slot-bottom svg {
  color: #819aa6;
}

.availability-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;

  margin-top: 25px;
  padding-top: 22px;

  border-top: 1px solid #edf1f3;
}

.availability-info {
  display: flex;
  align-items: flex-start;
  gap: 8px;

  max-width: 520px;
}

.info-dot {
  width: 7px;
  height: 7px;

  margin-top: 5px;

  flex: 0 0 7px;

  border-radius: 50%;

  background: #218b52;
}

.availability-info p {
  margin: 0;

  color: #7d909a;

  font-size: 9px;
  line-height: 1.6;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.booking-trust-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 12px;

  margin-top: 22px;
}

.booking-trust-strip > div {
  display: flex;
  align-items: center;
  gap: 9px;

  padding: 14px 15px;

  border: 1px solid #e0e8ec;
  border-radius: 13px;

  background: rgba(
    255,
    255,
    255,
    0.82
  );
}

.booking-trust-strip svg {
  flex: 0 0 auto;
  color: #218b52;
}

.booking-trust-strip span {
  color: #738792;

  font-size: 9px;
  font-weight: 700;
  line-height: 1.45;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .booking-layout {
    grid-template-columns: 1fr;
  }

  .booking-summary-column {
    position: static;
  }

  .booking-summary-card {
    max-width: none;
  }

  .slot-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}


@media (max-width: 800px) {

  .booking-top-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .booking-step-indicator {
    width: 100%;
  }

  .booking-step-line {
    flex: 1;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .booking-trust-strip {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 600px) {

  .booking-container {
    padding: 25px 16px 55px;
  }

  .booking-panel,
  .availability-section {
    padding: 21px;
    border-radius: 19px;
  }

  .booking-top-row h1 {
    font-size: 39px;
  }

  .booking-top-row p {
    font-size: 13px;
  }

  .booking-step {
    font-size: 8px;
  }

  .booking-step span {
    width: 24px;
    height: 24px;
  }

  .booking-step-line {
    margin: 0 6px;
  }

  .date-options {
    grid-template-columns: 1fr;
  }

  .date-option {
    min-height: 67px;
  }

  .slot-grid {
    grid-template-columns: 1fr;
  }

  .availability-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .capacity-note {
    width: 100%;
    align-items: flex-start;
  }

  .availability-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .availability-footer .button {
    width: 100%;
  }

}
/* =========================================================
   KRISHISETU — FARMER BOOKING EXPERIENCE
========================================================= */

.farmer-book-page {
  min-height: 100vh;

  color: #193b50;

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(33, 139, 82, 0.07),
      transparent 25%
    ),
    radial-gradient(
      circle at 100% 14%,
      rgba(242, 186, 66, 0.09),
      transparent 24%
    ),
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f7faf8 100%
    );
}

.booking-container {
  width: 100%;
  max-width: 1280px;

  margin: 0 auto;

  padding: 38px 28px 85px;
}


/* =========================================================
   TOP INTRO
========================================================= */

.booking-top-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 40px;

  margin-bottom: 30px;
}

.booking-title-area {
  max-width: 760px;
}

.booking-title-area .back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  margin-bottom: 24px;
}

.booking-eyebrow-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;

  gap: 9px;
}

.booking-title-area .page-eyebrow {
  display: inline-block;
}

.booking-live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  padding: 5px 9px;

  border: 1px solid #cee7d5;
  border-radius: 999px;

  color: #218b52;
  background: #eff9f1;

  font-size: 8px;
  font-weight: 900;

  letter-spacing: 0.07em;
}

.booking-live-pill > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px rgba(
      33,
      139,
      82,
      0.10
    );
}

.booking-title-area h1 {
  margin: 9px 0 12px;

  color: #183b50;

  font-family: var(--font-heading);

  font-size: clamp(
    42px,
    4.6vw,
    61px
  );

  line-height: 1.01;

  letter-spacing: -0.04em;
}

.booking-title-area > p {
  max-width: 690px;

  margin: 0;

  color: #6f8591;

  font-size: 16px;

  line-height: 1.75;
}


/* =========================================================
   MINI PROGRESS
========================================================= */

.booking-process-mini {
  min-width: 320px;

  display: flex;
  align-items: center;
  justify-content: flex-end;

  padding-bottom: 5px;
}

.mini-step {
  display: flex;
  align-items: center;
  gap: 7px;

  color: #9aaab3;

  font-size: 9px;
  font-weight: 800;

  white-space: nowrap;
}

.mini-step span {
  width: 27px;
  height: 27px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #dce5e9;
  border-radius: 50%;

  color: #8c9da7;
  background: #ffffff;

  font-size: 9px;
  font-weight: 900;
}

.mini-step.active {
  color: #218b52;
}

.mini-step.active span {
  border-color: #94c6a3;

  color: #ffffff;
  background: #218b52;
}

.mini-step-line {
  width: 26px;
  height: 1px;

  margin: 0 8px;

  background: #dce5e9;
}


/* =========================================================
   INFORMATION BAR
========================================================= */

.booking-info-bar {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 12px;

  margin-bottom: 23px;
}

.booking-info-bar > div {
  display: flex;
  align-items: center;

  gap: 11px;

  padding: 14px 15px;

  border: 1px solid #e0e9ed;
  border-radius: 15px;

  background: rgba(
    255,
    255,
    255,
    0.86
  );
}

.booking-info-bar > div > div:last-child {
  display: flex;
  flex-direction: column;

  gap: 3px;
}

.booking-info-bar strong {
  color: #315165;

  font-size: 10px;
  font-weight: 900;
}

.booking-info-bar span {
  color: #8697a0;

  font-size: 8px;

  line-height: 1.45;
}

.booking-info-icon {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;
}

.booking-info-icon.green {
  color: #218b52;
  background: #e5f4e9;
}

.booking-info-icon.blue {
  color: #287eae;
  background: #e4f2f8;
}

.booking-info-icon.gold {
  color: #c5881d;
  background: #fff0ce;
}


/* =========================================================
   MAIN GRID
========================================================= */

.booking-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    350px;

  gap: 23px;

  align-items: start;
}

.booking-form-column {
  display: flex;
  flex-direction: column;

  gap: 20px;
}


/* =========================================================
   PANELS
========================================================= */

.booking-panel {
  position: relative;

  padding: 30px;

  overflow: visible;

  border: 1px solid #dce7eb;
  border-radius: 24px;

  background: #ffffff;

  box-shadow:
    0 16px 45px
    rgba(
      31,
      62,
      76,
      0.06
    );
}

.booking-panel-number {
  position: absolute;

  top: 25px;
  right: 28px;

  color: #d6dfe3;

  font-size: 10px;
  font-weight: 900;

  letter-spacing: 0.13em;
}

.booking-panel-heading {
  display: flex;
  align-items: flex-start;

  gap: 13px;

  padding-right: 45px;

  margin-bottom: 26px;
}

.booking-panel-heading .panel-icon {
  width: 48px;
  height: 48px;

  flex: 0 0 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;
}

.panel-icon.green {
  color: #218b52;
  background: #e6f5ea;
}

.panel-icon.blue {
  color: #277cac;
  background: #e3f1f8;
}

.panel-step-label {
  display: block;

  margin-bottom: 4px;

  color: #d08b21;

  font-size: 8px;
  font-weight: 900;

  letter-spacing: 0.13em;
}

.booking-panel-heading h2 {
  margin: 0;

  color: #28475a;

  font-family: var(--font-heading);

  font-size: 24px;

  line-height: 1.12;
}

.booking-panel-heading p {
  max-width: 620px;

  margin: 7px 0 0;

  color: #84959f;

  font-size: 10px;

  line-height: 1.6;
}


/* =========================================================
   FORM
========================================================= */

.form-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 16px;
}

.booking-form-field {
  position: relative;
}

.booking-form-field > label {
  display: block;

  margin-bottom: 8px;

  color: #2d4b5c;

  font-size: 10px;

  font-weight: 900;
}

.field-help {
  display: block;

  margin-top: 7px;

  color: #8a9aa3;

  font-size: 8px;

  line-height: 1.5;
}


/* =========================================================
   INPUT
========================================================= */

.quantity-input {
  width: 100%;
  height: 55px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding: 0 14px;

  border: 1px solid #d6e2e8;
  border-radius: 12px;

  color: #738793;

  background: #f9fbfc;

  transition:
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.quantity-input:focus-within {
  border-color: #218b52;

  background: #ffffff;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      0.08
    );
}

.quantity-input input {
  width: 100%;
  height: 100%;

  min-width: 0;

  padding: 0;

  outline: 0;
  border: 0;

  color: #29485b;

  background: transparent;

  font-size: 15px;
  font-weight: 700;
}

.quantity-input input::placeholder {
  color: #b3bec4;
}

.quantity-input > strong {
  color: #667f8c;

  font-size: 10px;
}

.booking-input-error {
  border-color: #de7d72;

  background: #fff8f6;
}


/* =========================================================
   CROP SELECT
========================================================= */

.custom-select {
  position: relative;
}

.select-control {
  width: 100%;
  min-height: 59px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 13px;

  padding: 10px 14px;

  border: 1px solid #d6e2e8;
  border-radius: 12px;

  color: #718793;
  background: #f9fbfc;

  cursor: pointer;

  text-align: left;

  transition:
    border-color 150ms ease,
    background 150ms ease;
}

.select-control:hover {
  border-color: #b9d1db;
  background: #ffffff;
}

.select-main {
  min-width: 0;

  display: flex;
  align-items: center;

  gap: 11px;
}

.selected-value-stack {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.selected-value-stack strong {
  overflow: hidden;

  color: #29485b;

  font-size: 11px;
  font-weight: 900;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.selected-value-stack span {
  overflow: hidden;

  color: #8798a1;

  font-size: 8px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.crop-visual {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;
}

.crop-visual-large {
  width: 61px;
  height: 61px;

  flex: 0 0 61px;

  border-radius: 17px;
}

.crop-visual-small {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  border-radius: 9px;
}

.crop-wheat {
  color: #c48b1c;
  background: #fff1d0;
}

.crop-paddy,
.crop-rice {
  color: #4b9e61;
  background: #e6f5e9;
}

.crop-maize {
  color: #db8d25;
  background: #fff0d5;
}

.crop-cotton {
  color: #8864ad;
  background: #f0eafa;
}


/* =========================================================
   DROPDOWNS
========================================================= */

.select-menu {
  position: absolute;

  z-index: 40;

  top: calc(100% + 8px);

  left: 0;
  right: 0;

  max-height: 280px;

  overflow-y: auto;

  padding: 7px;

  border: 1px solid #d9e5e9;
  border-radius: 14px;

  background: #ffffff;

  box-shadow:
    0 22px 48px
    rgba(
      28,
      59,
      74,
      0.16
    );
}

.select-option,
.center-option {
  width: 100%;

  display: flex;
  align-items: center;

  gap: 10px;

  padding: 10px;

  border: 0;
  border-radius: 10px;

  color: #315467;

  background: transparent;

  cursor: pointer;

  text-align: left;
}

.select-option:hover,
.center-option:hover {
  background: #f4f8fa;
}

.select-option.selected,
.center-option.selected {
  background: #eef8f1;
}

.select-option > div:nth-child(2),
.center-option > div:nth-child(2) {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.select-option strong,
.center-option strong {
  color: #2b4a5d;

  font-size: 10px;
  font-weight: 900;
}

.select-option span,
.center-option span,
.center-option small {
  overflow: hidden;

  color: #899aa4;

  font-size: 8px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.center-option small {
  margin-top: 1px;
}

.select-option > svg:last-child,
.center-option > svg:last-child {
  flex: 0 0 auto;

  color: #218b52;
}

.center-select-icon {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #277cac;
  background: #e5f2f8;
}

.center-select-icon.large {
  width: 44px;
  height: 44px;

  flex-basis: 44px;

  border-radius: 12px;
}

.center-option-icon {
  width: 37px;
  height: 37px;

  flex: 0 0 37px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #277cac;
  background: #e5f2f8;
}

.booking-menu-empty {
  padding: 22px;

  color: #7e909a;

  font-size: 10px;

  line-height: 1.6;

  text-align: center;
}


/* =========================================================
   TIP
========================================================= */

.booking-tip-card {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 17px;

  padding: 13px 14px;

  border: 1px solid #f0e1b9;

  border-radius: 12px;

  background: #fff9e9;
}

.booking-tip-card > div {
  width: 29px;
  height: 29px;

  flex: 0 0 29px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #bd811a;
  background: #ffefc5;
}

.booking-tip-card p {
  margin: 0;

  color: #806f4d;

  font-size: 9px;

  line-height: 1.6;
}


/* =========================================================
   CENTER DETAILS
========================================================= */

.center-detail-card {
  margin-top: 14px;

  padding: 15px;

  border: 1px solid #dce9ef;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #f4f9fb,
      #eef6f9
    );
}

.center-detail-top {
  display: flex;

  align-items: center;

  gap: 10px;
}

.center-detail-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #277cac;
  background: #dcecf5;
}

.center-detail-top > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.center-detail-top strong {
  overflow: hidden;

  color: #2d4d60;

  font-size: 11px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.center-detail-top span {
  overflow: hidden;

  color: #81939e;

  font-size: 8px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.center-detail-meta {
  display: flex;
  flex-wrap: wrap;

  gap: 8px;

  margin-top: 12px;
}

.center-detail-meta span {
  display: inline-flex;

  align-items: center;

  gap: 4px;

  padding: 5px 7px;

  border-radius: 7px;

  color: #657f8d;
  background: #ffffff;

  font-size: 7px;
  font-weight: 800;
}


/* =========================================================
   DATE
========================================================= */

.booking-date-field {
  margin-top: 25px;
}

.field-heading-row {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 15px;

  margin-bottom: 8px;
}

.field-heading-row label {
  margin-bottom: 0;
}

.field-heading-row > span {
  color: #92a0a8;

  font-size: 8px;
}

.date-options {
  display: grid;

  grid-template-columns:
    repeat(5, minmax(0, 1fr));

  gap: 9px;
}

.date-option {
  position: relative;

  min-height: 92px;

  display: flex;

  flex-direction: column;
  align-items: flex-start;
  justify-content: center;

  padding: 12px;

  border: 1px solid #dce6eb;
  border-radius: 13px;

  color: #728792;

  background: #fafcfd;

  cursor: pointer;

  text-align: left;

  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease;
}

.date-option:hover {
  transform: translateY(-2px);

  border-color: #b7ced8;

  background: #ffffff;
}

.date-option.selected {
  border-color: #92c5a1;

  color: #218b52;

  background: #edf8f0;

  box-shadow:
    inset 0 0 0 1px
    rgba(
      33,
      139,
      82,
      0.05
    );
}

.date-weekday {
  font-size: 8px;

  font-weight: 900;

  text-transform: uppercase;
}

.date-option strong {
  margin-top: 4px;

  color: #2a495d;

  font-family: var(--font-heading);

  font-size: 28px;

  line-height: 1;
}

.date-option small {
  margin-top: 4px;

  color: #82939d;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: 0.1em;
}

.date-check {
  position: absolute;

  top: 8px;
  right: 8px;

  width: 22px;
  height: 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;
  background: #218b52;
}


/* =========================================================
   CHECK AVAILABILITY
========================================================= */

.booking-check-card {
  display: grid;

  grid-template-columns:
    auto minmax(0, 1fr)
    185px;

  align-items: center;

  gap: 16px;

  padding: 19px;

  border: 1px solid #d9e9df;

  border-radius: 19px;

  background:
    linear-gradient(
      135deg,
      #f1f9f3,
      #f9fbf7
    );
}

.booking-check-icon {
  width: 51px;
  height: 51px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  color: #218b52;

  background: #ddefe2;
}

.booking-check-copy {
  min-width: 0;
}

.booking-check-copy > span {
  color: #218b52;

  font-size: 8px;

  font-weight: 900;

  letter-spacing: 0.12em;
}

.booking-check-copy h3 {
  margin: 5px 0 4px;

  color: #2c4e60;

  font-family: var(--font-heading);

  font-size: 17px;
}

.booking-check-copy p {
  max-width: 550px;

  margin: 0;

  color: #768b95;

  font-size: 9px;

  line-height: 1.55;
}

.booking-check-action {
  width: 100%;
}

.booking-check-action .button {
  width: 100%;
}


/* =========================================================
   ERRORS
========================================================= */

.booking-error.prominent {
  display: flex;

  align-items: center;

  gap: 9px;

  padding: 13px 14px;

  border: 1px solid #efd1cc;

  border-radius: 12px;

  color: #b24c43;

  background: #fff4f1;

  font-size: 9px;

  line-height: 1.5;
}


/* =========================================================
   SUMMARY CARD
========================================================= */

.booking-summary-column {
  position: sticky;

  top: 103px;

  display: flex;
  flex-direction: column;

  gap: 15px;
}

.booking-summary-card {
  padding: 24px;

  border: 1px solid #dce7eb;

  border-radius: 22px;

  background:
    linear-gradient(
      155deg,
      #ffffff,
      #f8fbf9
    );

  box-shadow:
    0 19px 50px
    rgba(
      30,
      63,
      77,
      0.08
    );
}

.summary-header {
  display: flex;

  align-items: center;
  justify-content: space-between;

  padding-bottom: 17px;

  border-bottom: 1px solid #e9eef1;
}

.summary-header > div:first-child {
  display: flex;
  flex-direction: column;

  gap: 4px;
}

.summary-header span {
  color: #c98720;

  font-size: 8px;
  font-weight: 900;

  letter-spacing: 0.13em;
}

.summary-header h2 {
  margin: 0;

  color: #29485b;

  font-family: var(--font-heading);

  font-size: 21px;
}

.summary-header-icon {
  width: 41px;
  height: 41px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #218b52;
  background: #e5f4e9;
}

.summary-crop {
  display: flex;
  align-items: center;

  gap: 12px;

  padding: 19px 0;
}

.summary-crop > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.summary-crop span {
  color: #8898a0;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: 0.08em;
}

.summary-crop strong {
  color: #29495d;

  font-size: 14px;
}

.summary-crop small {
  color: #80919a;

  font-size: 8px;
}


/* =========================================================
   SUMMARY ROWS
========================================================= */

.summary-list {
  display: flex;
  flex-direction: column;

  border-top: 1px solid #edf1f3;
}

.summary-row {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 10px;

  padding: 13px 0;

  border-bottom: 1px solid #edf1f3;
}

.summary-row-label {
  display: flex;

  align-items: center;

  gap: 8px;

  min-width: 0;
}

.summary-row-icon {
  width: 28px;
  height: 28px;

  flex: 0 0 28px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #5b7b8b;

  background: #edf3f5;
}

.summary-row-label span {
  color: #82939c;

  font-size: 8px;
}

.summary-row > strong {
  max-width: 53%;

  color: #315165;

  font-size: 9px;

  line-height: 1.4;

  text-align: right;
}

.summary-total-row {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 12px;

  margin-top: 2px;

  padding: 16px 0 5px;
}

.summary-total-row span {
  color: #8999a2;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: 0.1em;
}

.summary-total-row strong {
  color: #218b52;

  font-size: 9px;

  text-align: right;
}

.summary-security {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  margin-top: 14px;

  padding: 10px 11px;

  border-radius: 10px;

  color: #708a7a;

  background: #f1f8f3;

  font-size: 7px;

  line-height: 1.55;
}

.summary-security svg {
  flex: 0 0 auto;

  color: #218b52;
}


/* =========================================================
   HELP CARD
========================================================= */

.booking-help-card {
  display: flex;

  align-items: flex-start;

  gap: 11px;

  padding: 17px;

  border: 1px solid #f0e2c3;

  border-radius: 17px;

  background: #fffaf0;
}

.booking-help-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #c8891c;
  background: #ffefc9;
}

.booking-help-card > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 5px;
}

.booking-help-card strong {
  color: #665334;

  font-size: 10px;
}

.booking-help-card p {
  margin: 0;

  color: #887b63;

  font-size: 8px;

  line-height: 1.55;
}

.booking-help-card a {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  margin-top: 3px;

  color: #b67917;

  font-size: 8px;

  font-weight: 900;

  text-decoration: none;
}


/* =========================================================
   AVAILABILITY SECTION
========================================================= */

.booking-availability-section {
  margin-top: 24px;

  padding: 31px;

  border: 1px solid #dce7eb;

  border-radius: 24px;

  background:
    linear-gradient(
      180deg,
      #ffffff,
      #fbfdfc
    );

  box-shadow:
    0 18px 48px
    rgba(
      30,
      63,
      77,
      0.06
    );
}

.availability-section-top {
  display: flex;

  align-items: flex-end;
  justify-content: space-between;

  gap: 25px;
}

.availability-title-row {
  display: flex;

  align-items: center;

  gap: 9px;

  flex-wrap: wrap;
}

.availability-title-row .page-eyebrow {
  display: inline-block;
}

.availability-found-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding: 5px 8px;

  border-radius: 999px;

  color: #218b52;
  background: #e9f7ed;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: 0.07em;
}

.availability-section-top h2 {
  margin: 8px 0 7px;

  color: #26465a;

  font-family: var(--font-heading);

  font-size: 31px;

  line-height: 1.08;
}

.availability-section-top p {
  max-width: 660px;

  margin: 0;

  color: #7b8e98;

  font-size: 10px;

  line-height: 1.6;
}

.availability-date-card {
  min-width: 175px;

  display: flex;

  align-items: center;

  gap: 10px;

  padding: 12px 14px;

  border: 1px solid #dce7eb;

  border-radius: 13px;

  background: #f8fbfc;
}

.availability-date-card > svg {
  color: #277cac;
}

.availability-date-card > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.availability-date-card span {
  color: #8b9aa2;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: 0.1em;
}

.availability-date-card strong {
  color: #315267;

  font-size: 10px;
}


/* =========================================================
   AVAILABILITY OVERVIEW
========================================================= */

.availability-overview {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 12px;

  margin-top: 24px;

  padding: 14px;

  border-radius: 15px;

  background: #f6f9fa;
}

.availability-overview-item {
  display: flex;

  align-items: center;

  gap: 10px;

  padding: 8px;

  border-radius: 11px;

  background: #ffffff;
}

.availability-overview-icon {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;
}

.availability-overview-icon.blue {
  color: #277cac;
  background: #e3f1f8;
}

.availability-overview-icon.green {
  color: #218b52;
  background: #e3f4e8;
}

.availability-overview-icon.gold {
  color: #c6881e;
  background: #fff0ca;
}

.availability-overview-item > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.availability-overview-item span {
  color: #8697a0;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: 0.08em;
}

.availability-overview-item strong {
  overflow: hidden;

  color: #315469;

  font-size: 14px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.availability-overview-item small {
  color: #86969e;

  font-size: 7px;
}


/* =========================================================
   SLOT INSTRUCTION
========================================================= */

.slot-instruction {
  display: flex;

  align-items: center;

  gap: 9px;

  margin-top: 18px;

  padding: 11px 13px;

  border: 1px solid #dfe9ec;

  border-radius: 11px;

  color: #718690;

  background: #f9fbfc;
}

.slot-instruction-icon {
  width: 27px;
  height: 27px;

  flex: 0 0 27px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #277cac;
  background: #e7f2f8;
}

.slot-instruction p {
  margin: 0;

  font-size: 8px;

  line-height: 1.55;
}


/* =========================================================
   SLOT GRID
========================================================= */

.slot-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 13px;

  margin-top: 20px;
}

.slot-card {
  position: relative;

  min-height: 190px;

  display: flex;

  flex-direction: column;

  padding: 17px;

  border: 1px solid #dce6eb;

  border-radius: 16px;

  color: inherit;

  background: #fbfcfd;

  cursor: pointer;

  text-align: left;

  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.slot-card:hover:not(:disabled) {
  transform: translateY(-4px);

  border-color: #aec9d4;

  background: #ffffff;

  box-shadow:
    0 15px 32px
    rgba(
      30,
      63,
      77,
      0.09
    );
}

.slot-card.selected {
  border-color: #8ec49f;

  background: #eef8f1;

  box-shadow:
    0 0 0 3px
    rgba(
      33,
      139,
      82,
      0.07
    );
}

.slot-card.slot-full {
  opacity: 0.57;

  cursor: not-allowed;
}

.slot-card-header {
  display: flex;

  align-items: center;

  justify-content: space-between;
}

.slot-card-clock {
  width: 40px;
  height: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #277cac;
  background: #e5f2f8;
}

.slot-card.selected
.slot-card-clock {
  color: #218b52;
  background: #dff1e4;
}

.slot-card-selected {
  width: 24px;
  height: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;
  background: #218b52;
}

.slot-card-time {
  margin-top: 17px;
}

.slot-card-time strong {
  color: #2c4b5d;

  font-size: 13px;

  line-height: 1.35;
}

.slot-capacity-label {
  margin-top: 8px;
}

.slot-capacity-label span {
  display: inline-flex;

  padding: 5px 7px;

  border-radius: 999px;

  font-size: 7px;

  font-weight: 900;
}

.slot-normal-label {
  color: #218b52;
  background: #e4f5e8;
}

.slot-limited-label {
  color: #b9811c;
  background: #fff1ce;
}

.slot-busy-label {
  color: #c15d48;
  background: #ffebe6;
}

.slot-full-label {
  color: #8a7070;
  background: #eee9e9;
}

.slot-capacity-bar {
  height: 5px;

  overflow: hidden;

  margin-top: 17px;

  border-radius: 999px;

  background: #e8edef;
}

.slot-capacity-bar > div {
  height: 100%;

  border-radius: inherit;

  background: #7fb891;
}

.slot-card-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 8px;

  margin-top: auto;

  padding-top: 17px;
}

.slot-card-footer span {
  color: #81939d;

  font-size: 8px;
}

.slot-card-footer svg {
  color: #788f9b;
}


/* =========================================================
   SELECTED SLOT
========================================================= */

.selected-slot-banner {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-top: 17px;

  padding: 13px;

  border: 1px solid #9ccaaa;

  border-radius: 13px;

  background: #edf8f0;
}

.selected-slot-check {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #ffffff;
  background: #218b52;
}

.selected-slot-banner > div:nth-child(2) {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.selected-slot-banner span {
  color: #6d9079;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: 0.09em;
}

.selected-slot-banner strong {
  color: #2c5f42;

  font-size: 11px;
}

.selected-slot-banner > button {
  padding: 6px 8px;

  border: 0;

  border-radius: 7px;

  color: #26734a;

  background: #dcefe2;

  cursor: pointer;

  font-size: 8px;
  font-weight: 900;
}


/* =========================================================
   FINAL CONFIRM
========================================================= */

.booking-confirm-section {
  margin-top: 24px;

  padding: 31px;

  border: 1px solid #dce7eb;

  border-radius: 24px;

  background:
    linear-gradient(
      140deg,
      #ffffff,
      #fafcfb
    );

  box-shadow:
    0 18px 48px
    rgba(
      30,
      63,
      77,
      0.06
    );
}

.confirm-section-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 25px;
}

.confirm-section-heading .page-eyebrow {
  display: inline-block;
}

.confirm-section-heading h2 {
  margin: 8px 0 7px;

  color: #29475a;

  font-family: var(--font-heading);

  font-size: 29px;

  line-height: 1.08;
}

.confirm-section-heading p {
  margin: 0;

  color: #7d909a;

  font-size: 10px;

  line-height: 1.6;
}

.confirm-ready-pill {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding: 8px 10px;

  border-radius: 999px;

  color: #218b52;

  background: #eaf7ee;

  font-size: 8px;

  font-weight: 900;

  white-space: nowrap;
}

.confirm-review-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 11px;

  margin-top: 24px;
}

.confirm-review-card {
  min-width: 0;

  display: flex;

  align-items: flex-start;

  gap: 9px;

  padding: 13px;

  border: 1px solid #e1e8eb;

  border-radius: 14px;

  background: #fbfcfd;
}

.confirm-review-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.confirm-review-icon.green {
  color: #218b52;
  background: #e4f4e8;
}

.confirm-review-icon.blue {
  color: #287dad;
  background: #e3f1f8;
}

.confirm-review-icon.gold {
  color: #c6881e;
  background: #fff0cc;
}

.confirm-review-icon.orange {
  color: #d67c29;
  background: #ffead9;
}

.confirm-review-card > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.confirm-review-card span {
  color: #8b9aa2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: 0.09em;
}

.confirm-review-card strong {
  overflow: hidden;

  color: #2c4b5d;

  font-size: 9px;

  line-height: 1.35;

  white-space: normal;
}

.confirm-review-card small {
  color: #83949d;

  font-size: 7px;

  line-height: 1.4;
}

.confirm-notice {
  display: flex;

  align-items: flex-start;

  gap: 11px;

  margin-top: 17px;

  padding: 15px;

  border-radius: 13px;

  background: #f1f7fa;
}

.confirm-notice-icon {
  width: 37px;
  height: 37px;

  flex: 0 0 37px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #277cac;
  background: #deedf5;
}

.confirm-notice > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.confirm-notice strong {
  color: #31566b;

  font-size: 10px;
}

.confirm-notice p {
  margin: 0;

  color: #728893;

  font-size: 8px;

  line-height: 1.6;
}

.confirm-bottom {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  margin-top: 20px;

  padding-top: 20px;

  border-top: 1px solid #e9eef1;
}

.confirm-arrival-reminder {
  display: flex;

  align-items: center;

  gap: 8px;

  max-width: 550px;

  color: #758993;

  font-size: 8px;

  line-height: 1.5;
}

.confirm-arrival-reminder svg {
  flex: 0 0 auto;

  color: #d27e28;
}


/* =========================================================
   BOTTOM INFO
========================================================= */

.booking-bottom-information {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 12px;

  margin-top: 23px;
}

.booking-bottom-card {
  display: flex;

  align-items: center;

  gap: 10px;

  padding: 15px;

  border: 1px solid #e0e8eb;

  border-radius: 15px;

  color: inherit;

  background: #ffffff;

  text-decoration: none;
}

.booking-bottom-card.green {
  background: #f1f9f3;
  border-color: #d9ebdd;
}

.booking-bottom-card.blue {
  background: #f1f8fb;
  border-color: #dceaf1;
}

.booking-bottom-card.gold {
  background: #fff9ed;
  border-color: #f0e2c4;
}

.bottom-card-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.booking-bottom-card.green .bottom-card-icon {
  color: #218b52;
  background: #def0e3;
}

.booking-bottom-card.blue .bottom-card-icon {
  color: #277cac;
  background: #e0eef5;
}

.booking-bottom-card.gold .bottom-card-icon {
  color: #c6861b;
  background: #ffefcb;
}

.booking-bottom-card > div:nth-child(2) {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.booking-bottom-card strong {
  color: #315064;

  font-size: 9px;
}

.booking-bottom-card span {
  color: #81929b;

  font-size: 7px;

  line-height: 1.5;
}

.booking-bottom-card > svg:last-child {
  margin-left: auto;

  color: #788f9a;
}


/* =========================================================
   FOOTER
========================================================= */

.booking-page-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding: 22px 7vw;

  color: #83939c;

  border-top: 1px solid #e4eaed;

  background: #ffffff;

  font-size: 8px;
}

.booking-page-footer > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.booking-page-footer strong {
  color: #31576c;

  font-family: var(--font-heading);

  font-size: 12px;
}

.booking-page-footer span {
  line-height: 1.5;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .booking-layout {
    grid-template-columns: 1fr;
  }

  .booking-summary-column {
    position: static;
  }

  .booking-summary-card {
    max-width: none;
  }

  .slot-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 900px) {

  .booking-top-row {
    align-items: flex-start;

    flex-direction: column;
  }

  .booking-process-mini {
    min-width: 0;

    width: 100%;

    justify-content: flex-start;
  }

  .booking-info-bar {
    grid-template-columns: 1fr;
  }

  .booking-check-card {
    grid-template-columns:
      auto minmax(0, 1fr);
  }

  .booking-check-action {
    grid-column: 1 / -1;
  }

  .confirm-review-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .booking-bottom-information {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 700px) {

  .booking-container {
    padding:
      25px
      16px
      60px;
  }

  .booking-panel,
  .booking-availability-section,
  .booking-confirm-section {
    padding: 22px;

    border-radius: 19px;
  }

  .booking-title-area h1 {
    font-size: 42px;
  }

  .booking-title-area > p {
    font-size: 14px;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .date-options {
    grid-template-columns:
      repeat(3, 1fr);
  }

  .availability-section-top {
    align-items: flex-start;

    flex-direction: column;
  }

  .availability-date-card {
    width: 100%;
  }

  .availability-overview {
    grid-template-columns: 1fr;
  }

  .slot-grid {
    grid-template-columns: 1fr;
  }

  .confirm-section-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .confirm-review-grid {
    grid-template-columns: 1fr;
  }

  .confirm-bottom {
    align-items: stretch;

    flex-direction: column;
  }

  .booking-page-footer {
    align-items: flex-start;

    flex-direction: column;

    padding:
      20px
      16px;
  }

}


@media (max-width: 480px) {

  .booking-process-mini {
    overflow-x: auto;

    padding-bottom: 7px;
  }

  .mini-step-line {
    min-width: 20px;
  }

  .booking-panel-heading h2 {
    font-size: 21px;
  }

  .booking-check-card {
    grid-template-columns: 1fr;
  }

  .booking-check-action {
    grid-column: auto;
  }

  .date-options {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .availability-section-top h2 {
    font-size: 27px;
  }

  .confirm-section-heading h2 {
    font-size: 26px;
  }

  .selected-slot-banner {
    align-items: flex-start;
  }

  .selected-slot-banner > button {
    margin-left: auto;
  }

}
/* =========================================================
   BOOKING PAGE GLOBAL FINISH
========================================================= */

body:has(.farmer-book-page) {
  margin: 0;
  background: #f7faf8;
}

body:has(.farmer-book-page) #root {
  min-height: 100vh;
  background:
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f7faf8 48%,
      #ffffff 100%
    );
}

.farmer-book-page,
.farmer-book-page main {
  background: transparent;
}

.farmer-book-page *,
.farmer-book-page *::before,
.farmer-book-page *::after {
  box-sizing: border-box;
}

.farmer-book-page button,
.farmer-book-page input {
  font-family: inherit;
}

.farmer-book-page button {
  appearance: none;
}

.farmer-book-page .button {
  min-height: 50px;
  border-radius: 12px;

  font-size: 11px;
  font-weight: 900;

  box-shadow:
    0 8px 18px
    rgba(
      33,
      139,
      82,
      0.12
    );
}

.farmer-book-page .button:hover:not(:disabled) {
  transform: translateY(-1px);
}

.farmer-book-page .button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.farmer-book-page .back-link {
  color: #547180;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
}

.farmer-book-page .back-link:hover {
  color: #218b52;
}
/* =========================================================
   FARMER TOKEN PAGE
========================================================= */

.farmer-token-page {
  min-height: 100vh;
  color: #193b50;
  background:
    radial-gradient(
      circle at 4% 4%,
      rgba(33, 139, 82, 0.07),
      transparent 24%
    ),
    radial-gradient(
      circle at 96% 18%,
      rgba(242, 186, 66, 0.09),
      transparent 25%
    ),
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f6faf8 100%
    );
}

.token-container {
  width: 100%;
  max-width: 1250px;
  margin: 0 auto;
  padding: 38px 28px 75px;
}


/* =========================================================
   TOP
========================================================= */

.token-top-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 28px;
}

.token-top-row .back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 23px;
}

.token-eyebrow-row {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.token-live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid #cfe6d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
}

.token-live-pill span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #218b52;
  box-shadow:
    0 0 0 4px rgba(33, 139, 82, .10);
}

.token-top-row h1 {
  margin: 9px 0 10px;
  color: #193b50;
  font-family: var(--font-heading);
  font-size: clamp(42px, 4.5vw, 58px);
  line-height: 1;
  letter-spacing: -.04em;
}

.token-top-row p {
  max-width: 650px;
  margin: 0;
  color: #728793;
  font-size: 14px;
  line-height: 1.7;
}

.token-database-card {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 160px;
  padding: 13px;
  border: 1px solid #dce7eb;
  border-radius: 14px;
  background: rgba(255, 255, 255, .9);
}

.token-database-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #218b52;
  background: #e6f5ea;
}

.token-database-card > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.token-database-card span {
  color: #8a9aa2;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .1em;
}

.token-database-card strong {
  color: #2f5c45;
  font-size: 10px;
}

.token-database-card small {
  color: #87979f;
  font-size: 7px;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.token-main-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 335px;
  gap: 22px;
  align-items: start;
}

.token-main-column {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.token-side-column {
  position: sticky;
  top: 100px;
  display: flex;
  flex-direction: column;
  gap: 15px;
}


/* =========================================================
   TOKEN HERO
========================================================= */

.token-hero-card {
  padding: 30px;
  border: 1px solid #d9e7df;
  border-radius: 24px;
  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f2f9f4 100%
    );
  box-shadow:
    0 20px 50px rgba(30, 69, 47, .08);
}

.token-hero-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 25px;
}

.token-card-label {
  display: block;
  color: #7e9588;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.token-number {
  margin-top: 7px;
  color: #1f6946;
  font-family: var(--font-heading);
  font-size: clamp(52px, 6vw, 78px);
  font-weight: 900;
  line-height: .95;
  letter-spacing: -.045em;
}

.token-status-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 13px;
}

.token-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.token-status-dot.green {
  background: #218b52;
}

.token-status-dot.blue {
  background: #277cac;
}

.token-status-dot.orange {
  background: #d67d2d;
}

.token-status-dot.gold {
  background: #c98b1e;
}

.token-status-row strong {
  color: #315c45;
  font-size: 10px;
}

.token-status-row > span:last-child {
  color: #80918c;
  font-size: 8px;
}

.token-big-check {
  width: 58px;
  height: 58px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 17px;
  color: #218b52;
  background: #def0e4;
}

.token-arrival-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 11px;
  margin-top: 26px;
}

.token-arrival-card {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 15px;
  border: 1px solid #e0e9eb;
  border-radius: 14px;
  background: rgba(255,255,255,.92);
}

.token-arrival-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.token-arrival-icon.blue {
  color: #277cac;
  background: #e4f2f8;
}

.token-arrival-icon.orange {
  color: #d67c2d;
  background: #ffeadb;
}

.token-arrival-icon.green {
  color: #218b52;
  background: #e5f4e9;
}

.token-arrival-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.token-arrival-card span {
  color: #8a9aa1;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
}

.token-arrival-card strong {
  overflow: hidden;
  color: #2d4d5e;
  font-size: 10px;
  line-height: 1.4;
}

.token-arrival-reminder {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  padding: 13px;
  border-radius: 12px;
  background: #edf8f0;
}

.token-reminder-icon {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #218b52;
  background: #dcefe2;
}

.token-arrival-reminder > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.token-arrival-reminder strong {
  color: #2d6243;
  font-size: 9px;
}

.token-arrival-reminder span {
  color: #789087;
  font-size: 8px;
  line-height: 1.5;
}


/* =========================================================
   SHARED SECTION CARDS
========================================================= */

.token-status-card,
.token-details-card {
  padding: 28px;
  border: 1px solid #dce7eb;
  border-radius: 22px;
  background: #ffffff;
  box-shadow:
    0 15px 40px rgba(30, 63, 77, .05);
}

.token-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.token-section-heading .page-eyebrow {
  display: inline-block;
  margin-bottom: 5px;
}

.token-section-heading h2 {
  margin: 0;
  color: #29485b;
  font-family: var(--font-heading);
  font-size: 24px;
}

.token-section-heading p {
  max-width: 600px;
  margin: 7px 0 0;
  color: #81929c;
  font-size: 9px;
  line-height: 1.55;
}

.token-refresh-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border: 1px solid #d9e5e9;
  border-radius: 9px;
  color: #557182;
  background: #f8fbfc;
  cursor: pointer;
  font-size: 8px;
  font-weight: 900;
}

.token-refresh-button:hover {
  color: #218b52;
  border-color: #b9d3c1;
  background: #f0f8f2;
}


/* =========================================================
   PROGRESS
========================================================= */

.token-progress-bar {
  width: 100%;
  height: 5px;
  overflow: hidden;
  margin-top: 24px;
  border-radius: 99px;
  background: #e9eef0;
}

.token-progress-bar > div {
  height: 100%;
  border-radius: inherit;
  background: #218b52;
  transition: width .3s ease;
}

.token-status-timeline {
  display: flex;
  flex-direction: column;
  margin-top: 22px;
}

.token-timeline-item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 68px;
}

.token-timeline-marker {
  position: relative;
  z-index: 2;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce6ea;
  border-radius: 50%;
  color: #97a7af;
  background: #ffffff;
}

.token-timeline-item.complete
.token-timeline-marker {
  border-color: #9bc8a8;
  color: #ffffff;
  background: #218b52;
}

.token-timeline-item.active
.token-timeline-marker {
  border-color: #218b52;
  color: #218b52;
  background: #eef8f1;
  box-shadow:
    0 0 0 5px rgba(33,139,82,.08);
}

.token-timeline-content {
  min-width: 0;
  padding-top: 1px;
}

.token-timeline-title-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.token-timeline-title-row strong {
  color: #315165;
  font-size: 10px;
}

.token-timeline-item.upcoming
.token-timeline-title-row strong {
  color: #95a3aa;
}

.token-now-pill {
  padding: 3px 6px;
  border-radius: 999px;
  color: #218b52;
  background: #e9f7ed;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .06em;
}

.token-timeline-content p {
  max-width: 570px;
  margin: 4px 0 0;
  color: #82939c;
  font-size: 8px;
  line-height: 1.5;
}

.token-timeline-line {
  position: absolute;
  top: 36px;
  bottom: 0;
  left: 17px;
  width: 2px;
  background: #e4eaed;
}

.token-timeline-item.complete
.token-timeline-line {
  background: #9fcaaa;
}

.token-current-message {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 8px;
  padding: 14px;
  border-radius: 13px;
  background: #f4f8f9;
}

.token-current-message-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #218b52;
  background: #e0f1e5;
}

.token-current-message > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.token-current-message span {
  color: #87979f;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
}

.token-current-message strong {
  color: #2d5a42;
  font-size: 11px;
}

.token-current-message p {
  margin: 0;
  color: #768990;
  font-size: 8px;
}


/* =========================================================
   DETAILS GRID
========================================================= */

.token-details-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 11px;
  margin-top: 21px;
}

.token-detail-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px;
  border: 1px solid #e3e9ec;
  border-radius: 13px;
  background: #fbfcfd;
}

.token-detail-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #557687;
  background: #edf3f5;
}

.token-detail-item > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.token-detail-item span {
  color: #8999a1;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .06em;
}

.token-detail-item strong {
  overflow-wrap: anywhere;
  color: #315064;
  font-size: 10px;
  line-height: 1.4;
}


/* =========================================================
   TOKEN VISUAL
========================================================= */

.token-visual-card {
  position: relative;
  overflow: hidden;
  padding: 25px;
  border-radius: 23px;
  color: #ffffff;
  background:
    linear-gradient(
      145deg,
      #1e6243,
      #277a50
    );
  box-shadow:
    0 20px 45px rgba(26, 95, 64, .18);
}

.token-visual-card::before,
.token-visual-card::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 50%;
}

.token-visual-card::before {
  width: 180px;
  height: 180px;
  right: -75px;
  top: -80px;
}

.token-visual-card::after {
  width: 110px;
  height: 110px;
  left: -60px;
  bottom: -65px;
}

.token-visual-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.token-visual-top span {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
  opacity: .78;
}

.token-visual-top svg {
  opacity: .85;
}

.token-visual-number {
  position: relative;
  z-index: 2;
  margin-top: 19px;
  font-family: var(--font-heading);
  font-size: 52px;
  font-weight: 900;
  letter-spacing: -.04em;
}

.token-visual-label {
  position: relative;
  z-index: 2;
  margin-top: 6px;
  font-size: 9px;
  font-weight: 800;
  opacity: .76;
}

.token-visual-decoration {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 6px;
  margin-top: 22px;
}

.token-visual-decoration span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255,255,255,.75);
}

.token-visual-card p {
  position: relative;
  z-index: 2;
  margin: 20px 0 0;
  color: rgba(255,255,255,.78);
  font-size: 8px;
  line-height: 1.6;
}


/* =========================================================
   SIDE CARDS
========================================================= */

.token-side-card {
  padding: 19px;
  border: 1px solid #dce7eb;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 12px 34px rgba(30,63,77,.05);
}

.token-side-heading {
  display: flex;
  align-items: center;
  gap: 10px;
}

.token-side-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.token-side-icon.green {
  color: #218b52;
  background: #e5f4e9;
}

.token-side-icon.blue {
  color: #277cac;
  background: #e4f2f8;
}

.token-side-icon.gold {
  color: #c6891d;
  background: #fff0cc;
}

.token-side-heading > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.token-side-heading span {
  color: #8999a2;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .1em;
}

.token-side-heading strong {
  color: #2d4d60;
  font-size: 12px;
}

.token-side-list {
  display: flex;
  flex-direction: column;
  margin-top: 15px;
}

.token-side-list > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 0;
  border-top: 1px solid #edf1f3;
}

.token-side-list span {
  color: #87979f;
  font-size: 8px;
}

.token-side-list strong {
  max-width: 57%;
  color: #315267;
  font-size: 8px;
  text-align: right;
}

.token-side-label {
  display: block;
  margin-top: 13px;
  color: #7f929b;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .11em;
}

.token-sms-card h3,
.token-help-card h3 {
  margin: 6px 0 5px;
  color: #2c4c5e;
  font-family: var(--font-heading);
  font-size: 17px;
}

.token-sms-card p,
.token-help-card p {
  margin: 0;
  color: #7b8e98;
  font-size: 8px;
  line-height: 1.6;
}

.token-help-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 13px;
  color: #b77a19;
  font-size: 8px;
  font-weight: 900;
  text-decoration: none;
}


/* =========================================================
   ACTIONS
========================================================= */

.token-bottom-actions {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 22px;
}

.token-primary-action,
.token-secondary-action {
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 17px;
  border-radius: 11px;
  font-size: 10px;
  font-weight: 900;
  text-decoration: none;
}

.token-primary-action {
  color: #ffffff;
  background: #218b52;
}

.token-primary-action:hover {
  background: #197342;
}

.token-secondary-action {
  color: #315b70;
  border: 1px solid #d8e4e9;
  background: #ffffff;
}

.token-secondary-action:hover {
  border-color: #b9d0da;
  color: #277cac;
}


/* =========================================================
   LOADING / ERROR
========================================================= */

.token-loading-card,
.token-error-card {
  max-width: 620px;
  margin: 80px auto;
  padding: 45px 32px;
  border: 1px solid #dce7eb;
  border-radius: 24px;
  background: #ffffff;
  box-shadow:
    0 20px 50px rgba(30,63,77,.07);
  text-align: center;
}

.token-loading-icon,
.token-error-icon {
  width: 67px;
  height: 67px;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 19px;
}

.token-loading-icon {
  color: #218b52;
  background: #e7f5eb;
}

.token-error-icon {
  color: #c35549;
  background: #fff0ed;
}

.token-loading-card .page-eyebrow,
.token-error-card .page-eyebrow {
  display: inline-block;
}

.token-loading-card h1,
.token-error-card h1 {
  margin: 8px 0 10px;
  color: #28485b;
  font-family: var(--font-heading);
  font-size: 30px;
}

.token-loading-card p,
.token-error-card p {
  max-width: 500px;
  margin: 0 auto;
  color: #788b95;
  font-size: 11px;
  line-height: 1.65;
}

.token-requested-id {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  margin-top: 20px;
  padding: 13px;
  border: 1px solid #e0e8eb;
  border-radius: 11px;
  background: #f7fafb;
}

.token-requested-id span {
  color: #83949d;
  font-size: 8px;
  font-weight: 800;
}

.token-requested-id strong {
  max-width: 60%;
  overflow-wrap: anywhere;
  color: #315368;
  font-size: 9px;
}

.token-error-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 22px;
}

.token-error-actions .home-primary-action {
  min-height: 43px;
}

.token-error-actions .token-refresh-button {
  min-height: 43px;
}

.token-spin {
  animation: tokenSpin 1s linear infinite;
}

@keyframes tokenSpin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1050px) {

  .token-main-layout {
    grid-template-columns: 1fr;
  }

  .token-side-column {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    align-items: start;
  }

  .token-visual-card {
    grid-column: 1 / -1;
  }

}


@media (max-width: 760px) {

  .token-top-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .token-database-card {
    width: 100%;
  }

  .token-arrival-grid {
    grid-template-columns: 1fr;
  }

  .token-details-grid {
    grid-template-columns: 1fr;
  }

  .token-side-column {
    grid-template-columns: 1fr;
  }

  .token-bottom-actions {
    flex-direction: column;
  }

  .token-primary-action,
  .token-secondary-action {
    width: 100%;
  }

}


@media (max-width: 560px) {

  .token-container {
    padding: 25px 16px 55px;
  }

  .token-top-row h1 {
    font-size: 40px;
  }

  .token-top-row p {
    font-size: 13px;
  }

  .token-hero-card,
  .token-status-card,
  .token-details-card {
    padding: 21px;
    border-radius: 19px;
  }

  .token-number {
    font-size: 54px;
  }

  .token-hero-top {
    gap: 12px;
  }

  .token-big-check {
    width: 48px;
    height: 48px;
  }

  .token-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .token-section-heading h2 {
    font-size: 22px;
  }

  .token-progress-bar {
    margin-top: 20px;
  }

  .token-current-message {
    align-items: flex-start;
  }

  .token-visual-card {
    padding: 22px;
  }

}
/* =========================================================
   FARMER HELP PAGE
========================================================= */

.farmer-help-page {
  min-height: 100vh;

  color: #193b50;

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(33, 139, 82, 0.07),
      transparent 24%
    ),
    radial-gradient(
      circle at 100% 12%,
      rgba(242, 186, 66, 0.09),
      transparent 25%
    ),
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f6faf8 52%,
      #ffffff 100%
    );
}

.help-container {
  width: 100%;
  max-width: 1260px;

  margin: 0 auto;

  padding: 38px 28px 80px;
}


/* =========================================================
   HERO
========================================================= */

.help-hero {
  display: grid;

  grid-template-columns:
