  font-weight: 900;

  text-decoration: none;
}

.help-call-button:hover {
  background: #197342;
}

.help-contact-right {
  display: flex;

  flex-direction: column;

  gap: 12px;
}

.help-contact-use-card {
  padding: 22px;

  border: 1px solid #dce7eb;

  border-radius: 18px;

  background: #ffffff;
}

.help-contact-use-icon {
  width: 40px;
  height: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #c6871c;

  background: #fff0ca;
}

.help-contact-use-card > div:nth-child(2) {
  display: flex;

  flex-direction: column;

  gap: 4px;

  margin-top: 11px;
}

.help-contact-use-card > div:nth-child(2) span {
  color: #8b9aa2;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: .1em;
}

.help-contact-use-card h3 {
  margin: 0;

  color: #315064;

  font-family: var(--font-heading);

  font-size: 18px;
}

.help-contact-reasons {
  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 9px;

  margin-top: 17px;
}

.help-contact-reasons > div {
  display: flex;

  align-items: flex-start;

  gap: 6px;

  padding: 8px;

  border-radius: 8px;

  background: #f7fafb;
}

.help-contact-reasons svg {
  flex: 0 0 auto;

  color: #218b52;
}

.help-contact-reasons span {
  color: #728792;

  font-size: 7px;

  line-height: 1.5;
}

.help-emergency-note {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  padding: 12px;

  border: 1px solid #e3e9ed;

  border-radius: 11px;

  color: #778b95;

  background: #f7f9fa;
}

.help-emergency-note svg {
  flex: 0 0 auto;

  color: #218b52;
}

.help-emergency-note p {
  margin: 0;

  font-size: 7px;

  line-height: 1.6;
}


/* =========================================================
   LANGUAGE
========================================================= */

.help-language-section {
  display: flex;

  align-items: center;

  gap: 15px;

  margin-top: 45px;

  padding: 20px 22px;

  border: 1px solid #dce7eb;

  border-radius: 18px;

  background: #ffffff;
}

.help-language-icon {
  width: 45px;
  height: 45px;

  flex: 0 0 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #288e91;

  background: #e3f4f3;
}

.help-language-copy {
  min-width: 0;

  flex: 1;
}

.help-language-copy .page-eyebrow {
  display: inline-block;

  margin-bottom: 4px;
}

.help-language-copy h2 {
  margin: 0 0 5px;

  color: #315164;

  font-family: var(--font-heading);

  font-size: 20px;
}

.help-language-copy p {
  margin: 0;

  color: #81929b;

  font-size: 8px;

  line-height: 1.55;
}

.help-language-list {
  display: flex;

  gap: 7px;
}

.help-language-option {
  min-width: 77px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  padding: 9px;

  border: 1px solid #dbe5e9;

  border-radius: 10px;

  color: #738892;

  background: #f9fbfc;
}

.help-language-option.active {
  border-color: #9fc9aa;

  color: #218b52;

  background: #edf8f0;
}

.help-language-option strong {
  font-size: 10px;
}

.help-language-option span {
  margin-top: 2px;

  font-size: 6px;
}


/* =========================================================
   FINAL CTA
========================================================= */

.help-final-card {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  margin-top: 25px;

  padding: 25px;

  border-radius: 20px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #1e6243,
      #297952
    );

  box-shadow:
    0 17px 40px
    rgba(
      27,
      92,
      62,
      .15
    );
}

.help-final-card .page-eyebrow {
  display: inline-block;

  color: rgba(
    255,
    255,
    255,
    .67
  );
}

.help-final-card h2 {
  margin: 7px 0 6px;

  color: #ffffff;

  font-family: var(--font-heading);

  font-size: 25px;
}

.help-final-card p {
  max-width: 650px;

  margin: 0;

  color: rgba(
    255,
    255,
    255,
    .75
  );

  font-size: 9px;

  line-height: 1.6;
}

.help-final-actions {
  display: flex;

  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

  justify-content: flex-end;
}

.help-final-card .help-primary-action {
  color: #1e6243;

  background: #ffffff;

  box-shadow: none;
}

.help-final-card .help-primary-action:hover {
  background: #eef8f1;
}

.help-final-card .help-secondary-action {
  color: #ffffff;

  border-color:
    rgba(
      255,
      255,
      255,
      .28
    );

  background:
    rgba(
      255,
      255,
      255,
      .08
    );
}


/* =========================================================
   FOOTER
========================================================= */

.help-page-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding:
    22px
    7vw;

  border-top: 1px solid #e4eaed;

  color: #81929a;

  background: #ffffff;

  font-size: 8px;
}

.help-page-footer > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.help-page-footer strong {
  color: #31566b;

  font-family: var(--font-heading);

  font-size: 12px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .help-hero {
    grid-template-columns: 1fr;
  }

  .help-hero-card {
    max-width: none;
  }

  .help-topic-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .help-checklist-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .help-connectivity-section {
    grid-template-columns: 1fr;
  }

  .help-sms-section {
    grid-template-columns: 1fr;
  }

  .help-phone-mockup {
    margin: 0;
  }

  .help-faq-layout {
    grid-template-columns: 1fr;
  }

  .help-faq-side {
    display: grid;

    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 800px) {

  .help-guides-grid {
    grid-template-columns: 1fr;
  }

  .help-contact-grid {
    grid-template-columns: 1fr;
  }

  .help-language-section {
    align-items: flex-start;

    flex-wrap: wrap;
  }

  .help-language-copy {
    flex-basis: calc(
      100% - 60px
    );
  }

  .help-language-list {
    width: 100%;
  }

  .help-language-option {
    flex: 1;
  }

  .help-final-card {
    align-items: flex-start;

    flex-direction: column;
  }

  .help-final-actions {
    justify-content: flex-start;
  }

}


@media (max-width: 600px) {

  .help-container {
    padding:
      25px
      16px
      60px;
  }

  .help-hero-copy h1 {
    font-size: 44px;
  }

  .help-hero-copy > p {
    font-size: 13px;
  }

  .help-topic-grid {
    grid-template-columns: 1fr;
  }

  .help-checklist-grid {
    grid-template-columns: 1fr;
  }

  .help-connectivity-points {
    grid-template-columns: 1fr;
  }

  .help-faq-side {
    grid-template-columns: 1fr;
  }

  .help-contact-reasons {
    grid-template-columns: 1fr;
  }

  .help-sms-section {
    padding: 22px;
  }

  .help-final-actions {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }

  .help-final-actions a {
    width: 100%;
  }

  .help-page-footer {
    align-items: flex-start;

    flex-direction: column;

    padding:
      20px
      16px;
  }

}
/* =========================================================
   ADMIN LOGIN PAGE
========================================================= */

.admin-login-page {
  min-height: 100vh;

  color: #18394d;

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(39, 126, 174, 0.08),
      transparent 25%
    ),
    radial-gradient(
      circle at 98% 12%,
      rgba(199, 137, 30, 0.09),
      transparent 24%
    ),
    linear-gradient(
      180deg,
      #fbfcfa 0%,
      #f4f8fa 55%,
      #ffffff 100%
    );
}

.admin-login-header {
  min-height: 76px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding:
    0
    max(24px, 6vw);

  border-bottom: 1px solid #e1e8eb;

  background:
    rgba(
      255,
      255,
      255,
      0.92
    );

  backdrop-filter: blur(12px);
}

.admin-login-brand {
  display: flex;
  align-items: center;

  gap: 10px;

  color: inherit;

  text-decoration: none;
}

.admin-brand-mark {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #ffffff;

  background:
    linear-gradient(
      145deg,
      #276f9b,
      #3591bc
    );

  font-size: 12px;
  font-weight: 950;

  box-shadow:
    0 7px 18px
    rgba(
      39,
      111,
      155,
      0.16
    );
}

.admin-login-brand > div:last-child {
  display: flex;
  flex-direction: column;

  gap: 2px;
}

.admin-login-brand strong {
  color: #294a5d;

  font-family: var(--font-heading);

  font-size: 17px;

  line-height: 1;
}

.admin-login-brand span {
  color: #80939e;

  font-size: 8px;

  font-weight: 800;

  letter-spacing: .04em;
}

.admin-login-back {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  color: #587180;

  font-size: 10px;
  font-weight: 900;

  text-decoration: none;
}

.admin-login-back:hover {
  color: #277cac;
}


/* =========================================================
   MAIN CONTAINER
========================================================= */

.admin-login-container {
  width: 100%;
  max-width: 1240px;

  margin: 0 auto;

  padding:
    50px
    28px
    70px;
}

.admin-login-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    430px;

  gap: 65px;

  align-items: center;
}


/* =========================================================
   INTRO
========================================================= */

.admin-login-intro {
  max-width: 690px;
}

.admin-login-eyebrow-row {
  display: flex;

  align-items: center;

  gap: 9px;

  flex-wrap: wrap;
}

.admin-secure-pill {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    5px
    9px;

  border: 1px solid #d4e4ec;

  border-radius: 999px;

  color: #287aa4;

  background: #edf6fa;

  font-size: 8px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-secure-pill > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #2f8cb5;

  box-shadow:
    0 0 0 4px
    rgba(
      47,
      140,
      181,
      .08
    );
}

.admin-login-intro h1 {
  margin:
    13px
    0
    15px;

  color: #18394d;

  font-family: var(--font-heading);

  font-size: clamp(
    46px,
    5vw,
    68px
  );

  line-height: .97;

  letter-spacing: -.045em;
}

.admin-login-intro h1 span {
  display: block;

  color: #277cac;
}

.admin-login-intro > p {
  max-width: 660px;

  margin: 0;

  color: #718792;

  font-size: 15px;

  line-height: 1.75;
}


/* =========================================================
   FEATURE GRID
========================================================= */

.admin-login-feature-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 10px;

  margin-top: 28px;
}

.admin-login-feature {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  padding: 14px;

  border: 1px solid #dce7eb;

  border-radius: 14px;

  background: rgba(
    255,
    255,
    255,
    .84
  );

  transition:
    transform .16s ease,
    border-color .16s ease,
    box-shadow .16s ease;
}

.admin-login-feature:hover {
  transform: translateY(-2px);

  border-color: #bfd4df;

  box-shadow:
    0 11px 25px
    rgba(
      30,
      63,
      77,
      .06
    );
}

.admin-login-feature-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #277cac;

  background: #e5f2f8;
}

.admin-login-feature:nth-child(2)
.admin-login-feature-icon {
  color: #218b52;
  background: #e5f4e9;
}

.admin-login-feature:nth-child(3)
.admin-login-feature-icon {
  color: #c4871c;
  background: #fff0cc;
}

.admin-login-feature:nth-child(4)
.admin-login-feature-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-login-feature > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-login-feature strong {
  color: #315165;

  font-size: 10px;
}

.admin-login-feature span {
  color: #7c909a;

  font-size: 8px;

  line-height: 1.55;
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-login-workflow {
  margin-top: 25px;

  padding:
    16px
    17px;

  border: 1px solid #dce7eb;

  border-radius: 16px;

  background:
    linear-gradient(
      135deg,
      #f7fafb,
      #ffffff
    );
}

.admin-login-workflow-heading {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-login-workflow-heading span {
  color: #8b9aa1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .12em;
}

.admin-login-workflow-heading strong {
  color: #315165;

  font-size: 11px;
}

.admin-workflow-steps {
  display: flex;

  align-items: center;

  margin-top: 14px;
}

.admin-workflow-step {
  display: flex;

  flex-direction: column;

  align-items: center;

  gap: 5px;

  min-width: 50px;
}

.admin-workflow-step span {
  width: 29px;
  height: 29px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #277cac;

  background: #e5f2f8;

  font-size: 7px;

  font-weight: 900;
}

.admin-workflow-step strong {
  color: #647d8a;

  font-size: 7px;

  font-weight: 900;
}

.admin-workflow-line {
  flex: 1;

  height: 1px;

  margin:
    0
    5px;

  background: #d6e2e7;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.admin-login-card {
  padding: 29px;

  border: 1px solid #d9e5e9;

  border-radius: 24px;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );

  box-shadow:
    0 24px 60px
    rgba(
      31,
      63,
      77,
      .11
    );
}

.admin-login-card-heading {
  display: flex;

  align-items: flex-start;

  gap: 12px;

  padding-bottom: 20px;

  border-bottom: 1px solid #e9eef1;
}

.admin-login-lock {
  width: 48px;
  height: 48px;

  flex: 0 0 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  color: #277cac;

  background: #e5f2f8;
}

.admin-login-card-heading > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-login-card-heading .page-eyebrow {
  display: inline-block;
}

.admin-login-card-heading h2 {
  margin: 0;

  color: #2b4a5e;

  font-family: var(--font-heading);

  font-size: 24px;

  line-height: 1.1;
}

.admin-login-card-heading p {
  margin: 2px 0 0;

  color: #81929c;

  font-size: 9px;

  line-height: 1.5;
}


/* =========================================================
   FIELDS
========================================================= */

.admin-login-card form {
  margin-top: 22px;
}

.admin-login-field {
  margin-bottom: 17px;
}

.admin-login-field label {
  display: block;

  margin-bottom: 8px;

  color: #365366;

  font-size: 9px;

  font-weight: 900;
}

.admin-login-input {
  height: 51px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding:
    0
    13px;

  border: 1px solid #d6e2e7;

  border-radius: 11px;

  color: #78909b;

  background: #f9fbfc;

  transition:
    border-color .15s ease,
    background .15s ease,
    box-shadow .15s ease;
}

.admin-login-input:focus-within {
  border-color: #277cac;

  background: #ffffff;

  box-shadow:
    0 0 0 4px
    rgba(
      39,
      124,
      172,
      .08
    );
}

.admin-login-input > svg {
  flex: 0 0 auto;
}

.admin-login-input input {
  min-width: 0;

  width: 100%;
  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #29485b;

  background: transparent;

  font-size: 11px;
  font-weight: 700;
}

.admin-login-input input::placeholder {
  color: #b0bdc4;
}

.admin-show-password {
  flex: 0 0 auto;

  padding: 5px 2px;

  border: 0;

  color: #4c7489;

  background: transparent;

  cursor: pointer;

  font-size: 8px;

  font-weight: 900;
}

.admin-show-password:hover {
  color: #277cac;
}

.admin-login-field small {
  display: block;

  margin-top: 6px;

  color: #8b9aa2;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   ERROR
========================================================= */

.admin-login-error {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  margin:
    2px
    0
    14px;

  padding:
    11px
    12px;

  border: 1px solid #efd1cc;

  border-radius: 10px;

  color: #b05247;

  background: #fff4f1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-login-error svg {
  flex: 0 0 auto;
}


/* =========================================================
   REMEMBER
========================================================= */

.admin-remember-row {
  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    2px
    0
    15px;

  color: #71858f;

  font-size: 8px;

  cursor: pointer;
}

.admin-remember-row input {
  width: 14px;
  height: 14px;

  accent-color: #277cac;

  cursor: pointer;
}


/* =========================================================
   SUBMIT
========================================================= */

.admin-login-submit {
  width: 100%;

  min-height: 51px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  border: 0;

  border-radius: 11px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #276f9b,
      #2f91bb
    );

  box-shadow:
    0 10px 22px
    rgba(
      39,
      111,
      155,
      .17
    );

  cursor: pointer;

  font-size: 10px;

  font-weight: 900;

  transition:
    transform .15s ease,
    box-shadow .15s ease;
}

.admin-login-submit:hover:not(:disabled) {
  transform: translateY(-1px);

  box-shadow:
    0 14px 28px
    rgba(
      39,
      111,
      155,
      .22
    );
}

.admin-login-submit:disabled {
  opacity: .7;

  cursor: not-allowed;
}

.admin-login-spinner {
  width: 16px;
  height: 16px;

  border: 2px solid
    rgba(
      255,
      255,
      255,
      .4
    );

  border-top-color: #ffffff;

  border-radius: 50%;

  animation:
    adminLoginSpin .75s linear infinite;
}

@keyframes adminLoginSpin {

  to {
    transform: rotate(360deg);
  }

}


/* =========================================================
   DEMO ACCESS
========================================================= */

.admin-demo-box {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 18px;

  padding: 13px;

  border: 1px dashed #ccdce4;

  border-radius: 12px;

  background: #f6fafc;
}

.admin-demo-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #277cac;

  background: #e3f1f8;
}

.admin-demo-box > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-demo-box span {
  color: #718793;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-demo-box strong {
  color: #315266;

  font-size: 9px;
}

.admin-demo-box p {
  margin: 1px 0 0;

  color: #80919b;

  font-size: 7px;

  line-height: 1.5;
}

.admin-demo-box b {
  color: #277cac;

  font-weight: 900;
}


/* =========================================================
   SECURITY
========================================================= */

.admin-security-row {
  display: flex;

  align-items: flex-start;

  gap: 7px;

  margin-top: 15px;

  padding-top: 13px;

  border-top: 1px solid #edf1f3;

  color: #83949d;

  font-size: 7px;

  line-height: 1.55;
}

.admin-security-row svg {
  flex: 0 0 auto;

  color: #277cac;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.admin-login-trust {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-top: 37px;

  padding:
    13px;

  border: 1px solid #dce7eb;

  border-radius: 15px;

  background: #ffffff;
}

.admin-login-trust > div {
  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  min-height: 31px;

  border-right: 1px solid #e8edef;
}

.admin-login-trust > div:last-child {
  border-right: 0;
}

.admin-login-trust svg {
  flex: 0 0 auto;

  color: #218b52;
}

.admin-login-trust span {
  color: #738792;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-login-footer {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 20px;

  padding:
    21px
    7vw;

  border-top: 1px solid #e2e9ec;

  color: #83949c;

  background: #ffffff;

  font-size: 8px;
}

.admin-login-footer > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-login-footer strong {
  color: #31566c;

  font-family: var(--font-heading);

  font-size: 12px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .admin-login-layout {
    grid-template-columns: 1fr;

    gap: 35px;
  }

  .admin-login-intro {
    max-width: none;
  }

  .admin-login-card {
    max-width: 600px;

    width: 100%;

    margin: 0 auto;
  }

}


@media (max-width: 720px) {

  .admin-login-container {
    padding:
      35px
      18px
      55px;
  }

  .admin-login-header {
    padding:
      0
      18px;
  }

  .admin-login-intro h1 {
    font-size: 46px;
  }

  .admin-login-intro > p {
    font-size: 13px;
  }

  .admin-login-feature-grid {
    grid-template-columns: 1fr;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-login-trust > div {
    border-right: 0;
  }

  .admin-login-footer {
    align-items: flex-start;

    flex-direction: column;

    padding:
      20px
      18px;
  }

}


@media (max-width: 500px) {

  .admin-login-header {
    min-height: 68px;
  }

  .admin-brand-mark {
    width: 37px;
    height: 37px;
  }

  .admin-login-brand strong {
    font-size: 15px;
  }

  .admin-login-brand span {
    font-size: 7px;
  }

  .admin-login-back {
    font-size: 8px;
  }

  .admin-login-card {
    padding: 21px;

    border-radius: 19px;
  }

  .admin-login-card-heading h2 {
    font-size: 21px;
  }

  .admin-login-intro h1 {
    font-size: 40px;
  }

  .admin-workflow-steps {
    overflow-x: auto;

    justify-content: flex-start;

    padding-bottom: 4px;
  }

  .admin-workflow-step {
    flex: 0 0 52px;
  }

  .admin-workflow-line {
    min-width: 25px;
  }

  .admin-login-trust {
    grid-template-columns: 1fr;
  }

}
/* =========================================================
   ADMIN LAYOUT
========================================================= */

.admin-layout {
  min-height: 100vh;

  display: flex;

  background:
    #f4f7f8;

  color: #203f51;
}

.admin-layout-main {
  min-width: 0;

  flex: 1;

  margin-left: 245px;
}

.admin-layout-content {
  width: 100%;

  min-height:
    calc(100vh - 76px);

  padding: 28px;
}


/* =========================================================
   SIDEBAR
========================================================= */

.admin-sidebar {
  position: fixed;

  z-index: 80;

  top: 0;
  left: 0;
  bottom: 0;

  width: 245px;

  display: flex;

  flex-direction: column;

  padding: 18px 13px;

  border-right: 1px solid #dce5e9;

  background:
    #ffffff;

  box-shadow:
    8px 0 30px
    rgba(
      28,
      57,
      72,
      .04
    );
}

.admin-sidebar-top {
  display: flex;

  align-items: center;

  justify-content: space-between;

  padding:
    3px
    5px
    18px;
}

.admin-sidebar-brand {
  display: flex;

  align-items: center;

  gap: 9px;

  color: inherit;

  text-decoration: none;
}

.admin-sidebar-logo {
  width: 38px;
  height: 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #ffffff;

  background:
    linear-gradient(
      145deg,
      #276f9b,
      #3291bc
    );

  font-size: 10px;
  font-weight: 950;
}

.admin-sidebar-brand > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-sidebar-brand strong {
  color: #294a5d;

  font-family: var(--font-heading);

  font-size: 15px;
}

.admin-sidebar-brand span {
  color: #8899a1;

  font-size: 7px;

  font-weight: 800;
}

.admin-sidebar-close {
  display: none;

  border: 0;

  color: #657d89;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   CENTER
========================================================= */

.admin-center-selector {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-bottom: 18px;

  padding:
    10px;

  border:
    1px solid
    #dae7ec;

  border-radius: 11px;

  background:
    #f4f9fb;
}

.admin-center-selector-icon {
  width: 30px;
  height: 30px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #277cac;

  background:
    #e0eff6;
}

.admin-center-selector > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-center-selector span {
  color: #8699a2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-center-selector strong {
  overflow: hidden;

  color: #315266;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   NAV
========================================================= */

.admin-sidebar-nav {
  flex: 1;

  overflow-y: auto;

  padding-right: 2px;
}

.admin-sidebar-group {
  margin-bottom: 17px;
}

.admin-sidebar-section {
  display: block;

  padding:
    0
    9px
    7px;

  color: #a0adb3;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .13em;
}

.admin-sidebar-items {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-sidebar-link {
  position: relative;

  display: flex;

  align-items: center;

  gap: 9px;

  min-height: 39px;

  padding:
    0
    10px;

  border-radius: 9px;

  color: #68818e;

  text-decoration: none;

  font-size: 8px;

  font-weight: 800;

  transition:
    background .15s ease,
    color .15s ease;
}

.admin-sidebar-link:hover {
  color: #315d73;

  background:
    #f2f7f9;
}

.admin-sidebar-link.active {
  color: #277cac;

  background:
    #eaf4f8;
}

.admin-sidebar-link.active svg {
  color: #277cac;
}

.admin-sidebar-link svg {
  flex: 0 0 auto;
}

.admin-sidebar-active-dot {
  width: 5px;
  height: 5px;

  margin-left: auto;

  border-radius: 50%;

  background: #277cac;
}


/* =========================================================
   SIDEBAR BOTTOM
========================================================= */

.admin-sidebar-bottom {
  padding-top: 15px;

  border-top:
    1px solid
    #e9eef0;
}

.admin-sidebar-status {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    9px;

  border-radius: 9px;

  background:
    #f5f9f7;
}

.admin-sidebar-status > span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-sidebar-status > div {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-sidebar-status strong {
  color: #41715a;

  font-size: 7px;
}

.admin-sidebar-status small {
  color: #8a9c93;

  font-size: 6px;
}

.admin-sidebar-logout {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-top: 7px;

  padding: 8px 9px;

  border-radius: 8px;

  color: #8a6666;

  font-size: 7px;

  font-weight: 800;

  text-decoration: none;
}

.admin-sidebar-logout:hover {
  color: #b04d45;

  background:
    #fff4f2;
}


/* =========================================================
   HEADER
========================================================= */

.admin-main-header {
  position: sticky;

  z-index: 40;

  top: 0;

  min-height: 76px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding:
    0
    28px;

  border-bottom:
    1px solid
    #dfe7ea;

  background:
    rgba(
      255,
      255,
      255,
      .94
    );

  backdrop-filter:
    blur(13px);
}

.admin-header-left {
  display: flex;

  align-items: center;

  gap: 12px;

  min-width: 0;
}

.admin-header-left > div {
  min-width: 0;
}

.admin-header-left h1 {
  margin: 0;

  color: #28485b;

  font-family: var(--font-heading);

  font-size: 21px;
}

.admin-header-left p {
  margin: 3px 0 0;

  color: #82949d;

  font-size: 7px;
}

.admin-mobile-menu {
  display: none;

  width: 38px;
  height: 38px;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #d9e4e8;

  border-radius: 9px;

  color: #527080;

  background: #ffffff;

  cursor: pointer;
}

.admin-header-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-header-refresh,
.admin-notification-button {
  height: 36px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 6px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 9px;

  color: #5d7785;

  background: #ffffff;

  cursor: pointer;
}

.admin-header-refresh {
  padding:
    0
    10px;

  font-size: 7px;

  font-weight: 900;
}

.admin-header-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}

.admin-header-refresh:hover:not(:disabled) {
  color: #277cac;

  border-color:
    #b9d1db;
}

.admin-notification-button {
  position: relative;

  width: 36px;
}

.admin-notification-button > span {
  position: absolute;

  top: -4px;
  right: -3px;

  min-width: 15px;
  height: 15px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;

  background: #d56e54;

  font-size: 6px;

  font-weight: 900;
}

.admin-operator-profile {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-left: 4px;

  padding-left: 11px;

  border-left:
    1px solid
    #e4ebee;
}

.admin-operator-avatar {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #277cac;

  background: #e5f2f8;
}

.admin-operator-profile > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-operator-profile strong {
  color: #315165;

  font-size: 8px;
}

.admin-operator-profile span {
  color: #8a9aa2;

  font-size: 6px;
}


/* =========================================================
   OVERLAY
========================================================= */

.admin-sidebar-overlay {
  display: none;
}


/* =========================================================
   ANIMATIONS
========================================================= */

.admin-refresh-spin {
  animation:
    adminRefreshSpin .7s linear infinite;
}

@keyframes adminRefreshSpin {

  to {
    transform: rotate(360deg);
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-layout-main {
    margin-left: 0;
  }

  .admin-sidebar {
    transform:
      translateX(-100%);

    transition:
      transform .2s ease;
  }

  .admin-sidebar.open {
    transform:
      translateX(0);
  }

  .admin-sidebar-close {
    display: flex;

    align-items: center;
    justify-content: center;
  }

  .admin-sidebar-overlay {
    position: fixed;

    z-index: 70;

    inset: 0;

    display: block;

    border: 0;

    background:
      rgba(
        20,
        42,
        53,
        .24
      );

    cursor: pointer;
  }

  .admin-mobile-menu {
    display: flex;
  }

}


@media (max-width: 600px) {

  .admin-main-header {
    padding:
      0
      16px;
  }

  .admin-layout-content {
    padding: 18px 16px;
  }

  .admin-header-refresh span {
    display: none;
  }

  .admin-operator-profile > div:last-child {
    display: none;
  }

}
/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;

  color: #29495b;
}


