  color: #83969f;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: .13em;
}

.admin-dashboard-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    28px,
    3.1vw,
    42px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-dashboard-hero p {
  max-width: 650px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.6;
}

.admin-dashboard-hero-right {
