.admin-live-chip > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-center-chip {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 30px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 999px;

  color: #5d7887;

  background: #ffffff;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   ERROR
========================================================= */

.admin-dashboard-error {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 14px;

  padding:
    12px
    14px;

  border:
    1px solid
    #efd1cb;

  border-radius: 11px;

  background: #fff4f2;

  color: #b05146;
}

.admin-dashboard-error > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-dashboard-error > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-dashboard-error strong {
  font-size: 8px;
}

.admin-dashboard-error span {
  color: #8e7772;

  font-size: 7px;

  line-height: 1.5;
}

.admin-dashboard-error button {
  margin-left: auto;

  border: 0;

  color: #a34d42;

  background: transparent;

  cursor: pointer;

