}

.admin-panel-icon.orange {
  color: #d37a2d;
  background: #ffeadc;
}

.admin-panel-icon.purple {
  color: #8064a9;
  background: #eee9f7;
}

.admin-panel-icon.teal {
  color: #278d8f;
  background: #e2f4f3;
}

.admin-panel-link {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  color: #4b7488;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;

  white-space: nowrap;
}

.admin-panel-link:hover {
  color: #277cac;
}

.admin-panel-live {
  padding:
    5px
    7px;

  border-radius: 999px;

  color: #218b52;

  background: #edf8f0;

  font-size: 7px;

  font-weight: 900;
}

.admin-alert-count {
  width: 25px;
  height: 25px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #b56928;

  background: #fff0dd;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE SEARCH
========================================================= */

.admin-queue-controls {
  display: flex;

  gap: 7px;

  padding:
    0
    17px
    13px;
}

.admin-dashboard-search {
  flex: 1;

  height: 35px;

  display: flex;

  align-items: center;

  gap: 7px;

  padding:
    0
    10px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  color: #84969e;

  background: #fafcfd;
}

.admin-dashboard-search:focus-within {
  border-color: #a6c3d0;

  background: #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-dashboard-search input {
  min-width: 0;

  flex: 1;

  height: 100%;

  padding: 0;

  outline: none;

  border: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-dashboard-search input::placeholder {
  color: #adb9bf;
}

.admin-filter-select {
  width: 115px;
}

.admin-filter-select select {
  width: 100%;

  height: 35px;

  padding:
    0
    9px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  outline: none;

  color: #5f7785;

  background: #fafcfd;

  cursor: pointer;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   TABLE
========================================================= */

.admin-queue-table {
  width: 100%;

  overflow-x: auto;
}

.admin-table-head,
.admin-booking-row {
  min-width: 690px;

  display: grid;

  grid-template-columns:
    1.05fr
    1.3fr
    1fr
    1.05fr
    .85fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    17px;
}

.admin-table-head {
  min-height: 31px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e8edef;

  color: #9ba8ae;

  background: #fafcfd;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-booking-row {
  min-height: 67px;

  border-bottom:
    1px solid
    #edf1f3;

  color: inherit;

  text-decoration: none;

  transition:
    background .12s ease;
}

.admin-booking-row:hover {
  background:
    #f8fbfc;
}

.admin-booking-row > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-booking-id strong {
  color: #2f566c;

  font-size: 9px;
}

.admin-booking-id span {
  color: #9aa8ae;

  font-size: 6px;
}

.admin-booking-farmer strong,
.admin-booking-produce strong,
.admin-booking-schedule strong {
  overflow: hidden;

  color: #415f70;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-booking-farmer span,
.admin-booking-produce span,
.admin-booking-schedule span {
  color: #899aa2;

  font-size: 6px;
}

.admin-booking-status {
  align-items: flex-start;
}

.admin-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  width: fit-content;

  max-width: 100%;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-status-pill.green {
  color: #218b52;
  background: #eaf7ed;
}

.admin-status-pill.blue {
  color: #2a7eaa;
  background: #e8f3f8;
}

.admin-status-pill.orange {
  color: #cf7629;
  background: #fff0e4;
}

.admin-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-status-pill.gold {
  color: #bc7e17;
  background: #fff2d3;
}


/* =========================================================
   PANEL FOOTER
========================================================= */

.admin-panel-footer {
  min-height: 45px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding:
    0
    17px;

  color: #9aa7ad;

  font-size: 7px;
}

.admin-panel-footer > a {
  display: inline-flex;

  align-items: center;

  gap: 4px;

  color: #4f7589;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;
}


/* =========================================================
   CAPACITY
========================================================= */

.admin-capacity-meter {
  height: 8px;

  overflow: hidden;

  margin:
    0
    18px;

  border-radius: 99px;

  background: #e8edef;
}

.admin-capacity-meter > div {
  height: 100%;

  border-radius: inherit;

  background:
    linear-gradient(
      90deg,
      #218b52,
      #62ad76
    );
}

.admin-capacity-summary {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  margin-top: 13px;

  padding:
    0
    18px;
}

.admin-capacity-summary > div {
  display: flex;

  flex-direction: column;

  gap: 3px;

  padding-right: 8px;
}

.admin-capacity-summary > div + div {
  padding-left: 10px;

  border-left:
    1px solid
    #e8edef;
}

.admin-capacity-summary span {
  color: #8999a1;

  font-size: 6px;
}

.admin-capacity-summary strong {
  color: #365667;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-slot-list {
  display: flex;

  flex-direction: column;

  gap: 9px;

  margin:
    16px
    18px
    18px;
}

.admin-slot-row {
  display: grid;

  grid-template-columns:
    50px
    1fr
    34px;

  gap: 7px;

  align-items: center;
}

.admin-slot-row > span {
  color: #738994;

  font-size: 6px;

  font-weight: 800;
}

.admin-slot-row > strong {
  color: #667f8d;

  font-size: 6px;

  text-align: right;
}

.admin-slot-bar {
  height: 5px;

  overflow: hidden;

  border-radius: 99px;

  background: #edf1f3;
}

.admin-slot-bar > div {
  height: 100%;

  border-radius: inherit;

  background: #66ab7d;
}


/* =========================================================
   ALERTS
========================================================= */

.admin-alert-list {
  display: flex;

  flex-direction: column;

  padding:
    0
    13px
    12px;
}

.admin-alert-row {
  display: grid;

  grid-template-columns:
    29px
    1fr
    15px;

  gap: 8px;

  align-items: center;

  min-height: 51px;

  padding:
    7px
    4px;

  border-top:
    1px solid
    #edf1f3;

  color: inherit;

  text-decoration: none;
}

.admin-alert-row:first-child {
  border-top: 0;
}

.admin-alert-row > div {
  width: 29px;
  height: 29px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;
}

.admin-alert-row.blue > div {
  color: #287eaa;
  background: #e6f2f8;
}

.admin-alert-row.orange > div {
  color: #d1772b;
  background: #ffebdd;
}

.admin-alert-row.gold > div {
  color: #bc7e1a;
  background: #fff1d0;
}

.admin-alert-row.purple > div {
  color: #8165aa;
  background: #eee8f7;
}

.admin-alert-row > span {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-alert-row strong {
  overflow: hidden;

  color: #415e6f;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-alert-row small {
  color: #8c9ca3;

  font-size: 6px;

  line-height: 1.45;
}

.admin-alert-row > svg {
  color: #a4b2b8;
}

.admin-all-good {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    10px
    4px;
}

.admin-all-good > svg {
  color: #218b52;
}

.admin-all-good > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-all-good strong {
  color: #4b6b59;

  font-size: 8px;
}

.admin-all-good span {
  color: #879991;

  font-size: 6px;
}


/* =========================================================
   BOTTOM GRID
========================================================= */

.admin-dashboard-bottom-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.2fr)
    minmax(310px, .8fr);

  gap: 15px;

  margin-top: 15px;
}


/* =========================================================
   ACTIVITY
========================================================= */

.admin-activity-list {
  display: flex;

  flex-direction: column;

  padding:
    0
    17px
    12px;
}

.admin-activity-row {
  display: grid;

  grid-template-columns:
    9px
    1fr
    45px;

  gap: 8px;

  align-items: center;

  min-height: 49px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-activity-row:first-child {
  border-top: 0;
}

.admin-activity-dot {
  width: 7px;
  height: 7px;

  border-radius: 50%;
}

.admin-activity-dot.green {
  background: #218b52;
}

.admin-activity-dot.blue {
  background: #287eaa;
}

.admin-activity-dot.orange {
  background: #d2782c;
}

.admin-activity-dot.purple {
  background: #8064a9;
}

.admin-activity-dot.gold {
  background: #c2871a;
}

.admin-activity-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-activity-content strong {
  color: #405d6e;

  font-size: 8px;
}

.admin-activity-content span {
  overflow: hidden;

  color: #8c9aa0;

  font-size: 6px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-activity-row small {
  color: #a0adb2;

  font-size: 6px;

  text-align: right;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.admin-quick-actions {
  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 8px;

  padding:
    0
    17px
    17px;
}

.admin-quick-action {
  min-height: 75px;

  display: grid;

  grid-template-columns:
    34px
    1fr
    13px;

  gap: 8px;

  align-items: center;

  padding: 10px;

  border:
    1px solid
    #e2eaed;

  border-radius: 11px;

  color: inherit;

  text-decoration: none;

  background: #fbfcfd;

  transition:
    transform .14s ease,
    border-color .14s ease,
    background .14s ease;
}

.admin-quick-action:hover {
  transform:
    translateY(-1px);

  border-color:
    #c5d6dd;

  background:
    #ffffff;
}

.admin-quick-action-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;
}

.admin-quick-action.blue
.admin-quick-action-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-quick-action.purple
.admin-quick-action-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-quick-action.gold
.admin-quick-action-icon {
  color: #c2871c;
  background: #fff0cd;
}

.admin-quick-action.green
.admin-quick-action-icon {
  color: #218b52;
  background: #e5f4e9;
}

.admin-quick-action > div:nth-child(2) {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-quick-action strong {
  overflow: hidden;

  color: #3c5a6c;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-quick-action span {
  color: #8a9aa1;

  font-size: 6px;

  line-height: 1.45;
}

.admin-quick-action > svg {
  color: #9eabb2;
}


/* =========================================================
   DATA FOOTER
========================================================= */

.admin-dashboard-data-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  margin-top: 15px;

  padding:
    8px
    2px;

  color: #8b9aa1;

  font-size: 6px;
}

.admin-dashboard-data-footer > div {
  display: inline-flex;

  align-items: center;

  gap: 5px;
}

.admin-dashboard-data-footer > div:first-child svg {
  color: #277cac;
}

.admin-dashboard-data-footer > div:nth-child(2) svg {
  color: #218b52;
}

.admin-dashboard-data-footer button {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding: 6px 8px;

  border:
    1px solid
    #dce5e9;

  border-radius: 7px;

  color: #5f7a88;

  background: #ffffff;

  cursor: pointer;

  font-size: 6px;

  font-weight: 800;
}

.admin-dashboard-data-footer button:hover {
  color: #277cac;

  border-color:
    #b8d0da;
}


/* =========================================================
   LOADING SKELETON
========================================================= */

.admin-dashboard-loading-list {
  padding:
    0
    17px;
}

.admin-skeleton-row {
  display: grid;

  grid-template-columns:
    repeat(5, 1fr);

  gap: 10px;

  min-height: 67px;

  align-items: center;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f7f9fa,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminSkeleton 1.2s infinite;
}

@keyframes adminSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}


/* =========================================================
   EMPTY
========================================================= */

.admin-dashboard-empty {
  min-height: 260px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 7px;

  color: #96a5ac;

  text-align: center;
}

.admin-dashboard-empty svg {
  color: #8eabb8;
}

.admin-dashboard-empty strong {
  color: #5b7481;

  font-size: 10px;
}

.admin-dashboard-empty span {
  font-size: 7px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1050px) {

  .admin-dashboard-main-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-side {
    display: grid;

    grid-template-columns:
      repeat(2, 1fr);

    align-items: start;
  }

  .admin-dashboard-bottom-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 800px) {

  .admin-dashboard-hero {
    flex-direction: column;
  }

  .admin-dashboard-hero-right {
    padding-top: 0;
  }

  .admin-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-dashboard-side {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 560px) {

  .admin-dashboard-page {
    width: 100%;
  }

  .admin-dashboard-hero h2 {
    font-size: 30px;
  }

  .admin-dashboard-hero p {
    font-size: 9px;
  }

  .admin-dashboard-hero-right {
    width: 100%;
  }

  .admin-live-chip,
  .admin-center-chip {
    flex: 1;
  }

  .admin-kpi-grid {
    grid-template-columns:
      1fr 1fr;

    gap: 7px;
  }

  .admin-kpi-card {
    padding: 11px;
  }

  .admin-kpi-value {
    font-size: 23px;
  }

  .admin-queue-controls {
    flex-direction: column;
  }

  .admin-filter-select {
    width: 100%;
  }

  .admin-quick-actions {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-data-footer {
    align-items: flex-start;

    flex-direction: column;
  }

}
/* =========================================================
   ADMIN QUEUE
========================================================= */

.admin-queue-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-queue-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 24px;

  margin-bottom: 18px;
}

.admin-queue-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    28px,
    3vw,
    40px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-queue-hero p {
  max-width: 720px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-queue-hero-actions {
  display: flex;
  align-items: center;

  gap: 8px;
}

.admin-queue-live-indicator {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #218b52;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-queue-live-indicator > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-queue-refresh-button {
  min-height: 32px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5f7987;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-queue-refresh-button:hover:not(:disabled) {
  color: #277cac;

  border-color:
    #b9d0da;
}

.admin-queue-refresh-button:disabled {
  opacity: .65;

  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-queue-error {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    12px
    14px;

  border:
    1px solid
    #efd0cb;

  border-radius: 11px;

  color: #b05348;

  background: #fff4f2;
}

.admin-queue-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-queue-error > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-queue-error strong {
  font-size: 8px;
}

.admin-queue-error span {
  color: #8e7772;

  font-size: 7px;

  line-height: 1.5;
}

.admin-queue-error button {
  margin-left: auto;

  border: 0;

  color: #a64f44;

  background: transparent;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE STATS
========================================================= */

.admin-queue-stats {
  display: grid;

  grid-template-columns:
    repeat(6, 1fr);

  gap: 9px;

  margin-bottom: 15px;
}

.admin-queue-stat {
  position: relative;

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;

  padding:
    12px;

  border:
    1px solid
    #dce6ea;

  border-radius: 13px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  box-shadow:
    0 7px 20px
    rgba(
      30,
      62,
      77,
      .03
    );

  transition:
    transform .14s ease,
    box-shadow .14s ease,
    border-color .14s ease;
}

.admin-queue-stat:hover {
  transform:
    translateY(-2px);

  box-shadow:
    0 12px 25px
    rgba(
      30,
      62,
      77,
      .06
    );
}

.admin-queue-stat.active {
  border-color:
    #9fc3d1;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .06
    );
}

.admin-queue-stat-icon {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-queue-stat.blue
.admin-queue-stat-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-queue-stat.green
.admin-queue-stat-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-queue-stat.orange
.admin-queue-stat-icon {
  color: #d2782c;
  background: #ffebdc;
}

.admin-queue-stat.purple
.admin-queue-stat-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-queue-stat.gold
.admin-queue-stat-icon {
  color: #c3871c;
  background: #fff0cd;
}

.admin-queue-stat.teal
.admin-queue-stat-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-queue-stat-content {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-queue-stat-content span {
  overflow: hidden;

  color: #83959e;

  font-size: 6px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-queue-stat-content strong {
  color: #2f5163;

  font-family: var(--font-heading);

  font-size: 18px;
}

.admin-queue-stat-arrow {
  margin-left: auto;

  color: #a8b4b9;
}


/* =========================================================
   FILTER PANEL
========================================================= */

.admin-queue-filter-panel {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-bottom: 13px;

  padding: 9px;

  border:
    1px solid
    #dce6ea;

  border-radius: 12px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-queue-search {
  flex: 1;

  min-width: 200px;

  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  padding:
    0
    10px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  color: #84969e;

  background: #fafcfd;
}

.admin-queue-search:focus-within {
  border-color: #a9c5d0;

  background: #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-queue-search input {
  width: 100%;
  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-queue-search input::placeholder {
  color: #aebbc1;
}

.admin-queue-filter-control {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    8px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  color: #81939d;

  background: #fafcfd;
}

.admin-queue-filter-control:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-queue-filter-control select {
  min-width: 90px;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #587381;

  background: transparent;

  cursor: pointer;

  font-size: 7px;

  font-weight: 800;
}

.admin-clear-filters {
  height: 36px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    9px;

  border: 0;

  border-radius: 8px;

  color: #ac5b50;

  background: #fff3f1;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE TABLE PANEL
========================================================= */

.admin-queue-table-panel {
  overflow: hidden;

  border:
    1px solid
    #dce6ea;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 29px
    rgba(
      30,
      62,
      77,
      .045
    );
}

.admin-queue-table-header {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 15px;

  padding:
    18px
    18px
    14px;
}

.admin-queue-table-header > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-queue-table-header h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 19px;
}

.admin-queue-result-note {
  color: #91a0a6;

  font-size: 7px;
}


/* =========================================================
   FULL TABLE
========================================================= */

.admin-full-queue-table {
  width: 100%;

  overflow-x: auto;
}

.admin-full-table-head,
.admin-full-table-row {
  min-width: 1050px;

  display: grid;

  grid-template-columns:
    1.1fr
    1.45fr
    1.15fr
    1.15fr
    .85fr
    1.15fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    18px;
}

.admin-full-table-head {
  min-height: 34px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e7edef;

  color: #99a7ad;

  background: #fafcfd;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-full-table-row {
  min-height: 76px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-full-table-row:hover {
  background: #fbfcfd;
}

.admin-full-table-row > div {
  min-width: 0;
}


/* =========================================================
   TABLE CELLS
========================================================= */

.admin-full-booking-cell,
.admin-full-farmer-cell,
.admin-full-produce-cell,
.admin-full-schedule-cell,
.admin-full-status-cell,
.admin-full-action-cell {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-full-booking-cell > div:last-child,
.admin-full-farmer-cell > div:last-child,
.admin-full-produce-cell,
.admin-full-schedule-cell {
  min-width: 0;
}

.admin-full-booking-cell > div:last-child,
.admin-full-farmer-cell > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-token-badge,
.admin-farmer-avatar {
  width: 35px;
  height: 35px;

  flex: 0 0 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-token-badge {
  color: #287eaa;

  background: #e5f2f8;
}

.admin-farmer-avatar {
  color: #718795;

  background: #edf2f4;
}

.admin-full-booking-cell strong {
  color: #31566b;

  font-size: 9px;
}

.admin-full-booking-cell span {
  color: #9aa8ae;

  font-size: 6px;
}

.admin-full-farmer-cell strong {
  overflow: hidden;

  color: #405e70;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-full-farmer-cell span {
  color: #899aa2;

  font-size: 6px;
}

.admin-full-produce-cell {
  flex-direction: column;

  align-items: flex-start;

  gap: 4px;
}

.admin-produce-name {
  display: flex;

  align-items: center;

  gap: 5px;
}

.admin-produce-name svg {
  color: #218b52;
}

.admin-produce-name strong {
  color: #3d5b6a;

  font-size: 8px;
}

.admin-full-produce-cell > span {
  color: #83959d;

  font-size: 6px;
}

.admin-full-produce-cell small {
  color: #218b52;

  font-size: 5px;

  font-weight: 900;
}

.admin-full-schedule-cell {
  flex-direction: column;

  align-items: flex-start;

  gap: 4px;
}

.admin-full-schedule-cell > div {
  display: flex;

  align-items: center;

  gap: 5px;
}

.admin-full-schedule-cell svg {
  color: #73909e;
}

.admin-full-schedule-cell strong {
  color: #415f70;

  font-size: 7px;
}

.admin-full-schedule-cell > span {
  color: #8999a1;

  font-size: 6px;
}

.admin-full-status-cell {
  align-items: flex-start;
}

.admin-full-action-cell {
  flex-wrap: wrap;

  justify-content: flex-start;

  gap: 5px;
}

.admin-row-view-button,
.admin-row-action-button {
  min-height: 29px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 5px;

  padding:
    0
    8px;

  border-radius: 7px;

  cursor: pointer;

  font-size: 6px;

  font-weight: 900;
}

.admin-row-view-button {
  color: #547384;

  border:
    1px solid
    #dbe5e9;

  background: #ffffff;
}

.admin-row-view-button:hover {
  color: #287eaa;

  border-color:
    #b8d0da;
}

.admin-row-action-button {
  border: 0;

  color: #ffffff;
}

.admin-row-action-button.green {
  background: #218b52;
}

.admin-row-action-button.purple {
  background: #8064a9;
}

.admin-row-action-button.gold {
  color: #664914;

  background: #efd185;
}

.admin-row-action-button.teal {
  background: #288e91;
}

.admin-row-action-button:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-queue-empty {
  min-height: 380px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  padding: 35px;

  text-align: center;
}

.admin-queue-empty-icon {
  width: 55px;
  height: 55px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 15px;

  color: #73909e;

  background: #edf3f5;
}

.admin-queue-empty h3 {
  margin: 14px 0 5px;

  color: #486474;

  font-family: var(--font-heading);

  font-size: 18px;
}

.admin-queue-empty p {
  max-width: 360px;

  margin: 0;

  color: #899ba3;

  font-size: 8px;

  line-height: 1.6;
}

.admin-queue-empty button {
  margin-top: 15px;

  min-height: 34px;

  padding:
    0
    11px;

  border: 0;

  border-radius: 8px;

  color: #ffffff;

  background: #277cac;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-queue-loading {
  min-width: 1050px;
}

.admin-full-skeleton-row {
  min-height: 76px;

  display: grid;

  grid-template-columns:
    1.1fr
    1.45fr
    1.15fr
    1.15fr
    .85fr
    1.15fr;

  gap: 10px;

  align-items: center;

  padding:
    0
    18px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-full-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminQueueSkeleton 1.2s infinite;
}

@keyframes adminQueueSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}


/* =========================================================
   INFO CARDS
========================================================= */

.admin-queue-info-grid {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 10px;

  margin-top: 14px;
}

.admin-queue-info-card {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  padding:
    14px;

  border:
    1px solid
    #dce6ea;

  border-radius: 13px;

  background: #ffffff;
}

.admin-queue-info-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;
}

.admin-queue-info-card.blue
.admin-queue-info-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-queue-info-card.green
.admin-queue-info-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-queue-info-card.purple
.admin-queue-info-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-queue-info-card > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-queue-info-card strong {
  color: #3b5a6b;

  font-size: 8px;
}

.admin-queue-info-card span {
  color: #84959d;

  font-size: 6px;

  line-height: 1.55;
}


/* =========================================================
   DRAWER OVERLAY
========================================================= */

.admin-booking-drawer-overlay {
  position: fixed;

  z-index: 100;

  inset: 0;

  background:
    rgba(
      24,
      51,
      64,
      .28
    );
}


/* =========================================================
   DRAWER
========================================================= */

.admin-booking-drawer {
  position: fixed;

  z-index: 110;

  top: 0;
  right: 0;
  bottom: 0;

  width: min(
    480px,
    94vw
  );

  display: flex;

  flex-direction: column;

  background: #ffffff;

  box-shadow:
    -18px 0 50px
    rgba(
      27,
      54,
      68,
      .15
    );

  animation:
    adminDrawerIn .2s ease;
}

@keyframes adminDrawerIn {

  from {
    transform:
      translateX(20px);

    opacity: 0;
  }

  to {
    transform:
      translateX(0);

    opacity: 1;
  }

}

.admin-drawer-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;

  padding:
    21px;

  border-bottom:
    1px solid
    #e7edef;
}

.admin-drawer-header > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-drawer-header h2 {
  margin: 0;

  color: #284b5e;

  font-family: var(--font-heading);

  font-size: 24px;
}

.admin-drawer-close {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border: 1px solid #dce5e9;

  border-radius: 9px;

  color: #69818d;

  background: #ffffff;

  cursor: pointer;
}

.admin-drawer-close:hover {
  color: #b05147;

  border-color:
    #e1c1bc;
}

.admin-drawer-status {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    13px
    21px;

  border-bottom:
    1px solid
    #edf1f3;

  background:
    #fafcfd;
}

.admin-drawer-status > span:last-child {
  min-width: 0;

  color: #82949c;

  font-size: 7px;

  line-height: 1.5;
}

.admin-drawer-body {
  flex: 1;

  overflow-y: auto;

  padding:
    7px
    21px
    20px;
}

.admin-drawer-section {
  padding:
    18px
    0;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-drawer-section-heading {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-bottom: 11px;
}

.admin-drawer-section-heading > div {
  width: 31px;
  height: 31px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #287eaa;

  background: #e7f2f8;
}

.admin-drawer-section-heading h3 {
  margin: 0;

  color: #426274;

  font-size: 9px;

  font-weight: 900;
}

.admin-drawer-section-content {
  display: flex;

  flex-direction: column;
}

.admin-drawer-field {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding: 7px 0;
}

.admin-drawer-field span {
  color: #8a9ba2;

  font-size: 7px;
}

.admin-drawer-field strong {
  max-width: 63%;

  overflow-wrap: anywhere;

  color: #466274;

  font-size: 8px;

  text-align: right;
}


/* =========================================================
   DRAWER TIMELINE
========================================================= */

.admin-drawer-mini-timeline {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-mini-timeline-item {
  display: flex;

  align-items: center;

  gap: 8px;

  min-height: 29px;
}

.admin-mini-timeline-item > div {
  width: 23px;
  height: 23px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dae3e7;

  border-radius: 50%;

  color: #9aa8af;

  background: #ffffff;
}

.admin-mini-timeline-item > div span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #d8e0e3;
}

.admin-mini-timeline-item.complete > div {
  color: #ffffff;

  border-color:
    #218b52;

  background:
    #218b52;
}

.admin-mini-timeline-item.active > div {
  color: #277cac;

  border-color:
    #8eb7c8;

  background:
    #eaf4f8;
}

.admin-mini-timeline-item > span {
  color: #8799a1;

  font-size: 7px;
}

.admin-mini-timeline-item.complete > span {
  color: #4d735c;

  font-weight: 800;
}

.admin-mini-timeline-item.active > span {
  color: #39708c;

  font-weight: 900;
}


/* =========================================================
   DRAWER ACTION
========================================================= */

.admin-drawer-action-card {
  margin-top: 17px;

  padding: 15px;

  border:
    1px solid
    #dce7eb;

  border-radius: 12px;

  background:
    #f8fbfc;
}

.admin-drawer-action-card > span {
  display: block;

  color: #8a9ba2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-drawer-action-card > strong {
  display: block;

  margin-top: 5px;

  color: #35576a;

  font-size: 11px;
}

.admin-drawer-action-card p {
  margin: 6px 0 12px;

  color: #81929a;

  font-size: 7px;

  line-height: 1.55;
}

.admin-drawer-action {
  width: 100%;

  min-height: 41px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border: 0;

  border-radius: 9px;

  color: #ffffff;

  background: #218b52;

  cursor: pointer;

  font-size: 8px;

  font-weight: 900;
}

.admin-drawer-action.purple {
  background: #8064a9;
}

.admin-drawer-action.gold {
  color: #664914;

  background: #efd185;
}

.admin-drawer-action.teal {
  background: #288e91;
}

.admin-drawer-action:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-drawer-footer {
  min-height: 62px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  padding:
    11px
    21px;

  border-top:
    1px solid
    #e7edef;

  background:
    #ffffff;
}

.admin-drawer-footer > button {
  min-height: 35px;

  padding:
    0
    11px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 8px;

  color: #607986;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-drawer-details-link {
  min-height: 35px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    10px;

  border-radius: 8px;

  color: #287eaa;

  background: #eaf4f8;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1200px) {

  .admin-queue-stats {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 900px) {

  .admin-queue-hero {
    flex-direction: column;
  }

  .admin-queue-hero-actions {
    width: 100%;
  }

  .admin-queue-stats {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-queue-info-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 700px) {

  .admin-queue-filter-panel {
    align-items: stretch;

    flex-wrap: wrap;
  }

  .admin-queue-search {
    flex-basis: 100%;
  }

  .admin-queue-filter-control {
    flex: 1;
  }

  .admin-queue-filter-control select {
    min-width: 80px;
  }

  .admin-clear-filters {
    flex: 0 0 auto;
  }

}


@media (max-width: 520px) {

  .admin-queue-hero h2 {
    font-size: 30px;
  }

  .admin-queue-stats {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-queue-stat {
    padding: 10px;
  }

  .admin-queue-stat-icon {
    width: 31px;
    height: 31px;

    flex-basis: 31px;
  }

  .admin-queue-stat-content strong {
    font-size: 16px;
  }

  .admin-queue-stat-arrow {
    display: none;
  }

  .admin-queue-filter-control {
    width: 100%;

    flex-basis: 100%;
  }

  .admin-clear-filters {
    width: 100%;

    justify-content: center;
  }

  .admin-queue-table-header {
    align-items: flex-start;

    flex-direction: column;
  }

}
/* =========================================================
   ADMIN WEIGHING PAGE
========================================================= */

.admin-weighing-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-weighing-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 24px;

  margin-bottom: 18px;
}

.admin-weighing-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    29px,
    3vw,
    41px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-weighing-hero p {
  max-width: 700px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-weighing-hero-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-weighing-live {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #218b52;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-weighing-live > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-weighing-refresh {
  min-height: 32px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5d7887;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-weighing-refresh:hover:not(:disabled) {
  color: #287eaa;

  border-color:
    #bad0da;
}

.admin-weighing-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-weighing-feedback {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    11px
    13px;

  border-radius: 10px;
}

.admin-weighing-feedback.error {
  border:
    1px solid
    #efd0ca;

  color: #b15348;

  background: #fff4f2;
}

.admin-weighing-feedback.success {
  border:
    1px solid
    #cfe5d4;

  color: #2f7550;

  background: #eef9f1;
}

.admin-weighing-feedback > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-weighing-feedback > span {
  flex: 1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-weighing-feedback button {
  display: flex;

  align-items: center;
  justify-content: center;

  padding: 2px;

  border: 0;

  color: currentColor;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   KPI
========================================================= */

.admin-weighing-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-bottom: 15px;
}

.admin-weighing-stat {
  display: flex;

  align-items: center;

  gap: 10px;

  padding:
    13px;

  border:
    1px solid
    #dce6ea;

  border-radius: 14px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-weighing-stat-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-weighing-stat.blue
.admin-weighing-stat-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-weighing-stat.orange
.admin-weighing-stat-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-weighing-stat.purple
.admin-weighing-stat-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-weighing-stat.green
.admin-weighing-stat-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-weighing-stat > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-stat strong {
  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 20px;
}

.admin-weighing-stat span {
  color: #84969e;

  font-size: 7px;
}


/* =========================================================
   WORKSPACE
========================================================= */

.admin-weighing-workspace {
  display: grid;

  grid-template-columns:
    350px
    minmax(0, 1fr);

  gap: 15px;

  align-items: start;
}

.admin-weighing-list-panel,
.admin-weighing-form-panel {
  min-width: 0;

  border:
    1px solid
    #dce6ea;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 28px
    rgba(
      30,
      62,
      77,
      .04
    );
}


/* =========================================================
   LIST
========================================================= */

.admin-weighing-panel-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 10px;

  padding:
    17px
    17px
    13px;
}

.admin-weighing-panel-heading > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-panel-heading h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-weighing-panel-heading > span {
  color: #96a4aa;

  font-size: 7px;
}

.admin-weighing-search {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    0
    17px
    11px;

  padding:
    0
    10px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  color: #8799a1;

  background: #fafcfd;
}

.admin-weighing-search:focus-within {
  border-color:
    #a9c5d0;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-weighing-search input {
  width: 100%;

  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-weighing-search input::placeholder {
  color: #adb9bf;
}

.admin-weighing-booking-list {
  display: flex;

  flex-direction: column;

  max-height: 700px;

  overflow-y: auto;
}


/* =========================================================
   BOOKING ITEM
========================================================= */

.admin-weighing-booking-item {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 9px;

  min-height: 72px;

  padding:
    10px
    17px;

  border: 0;

  border-top:
    1px solid
    #edf1f3;

  color: #315064;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  transition:
    background .13s ease,
    box-shadow .13s ease;
}

.admin-weighing-booking-item:hover {
  background:
    #f9fbfc;
}

.admin-weighing-booking-item.selected {
  background:
    #eef6f9;

  box-shadow:
    inset 3px 0 0
    #287eaa;
}

.admin-weighing-token {
  width: 35px;
  height: 35px;

  flex: 0 0 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #287eaa;

  background: #e5f2f8;
}

.admin-weighing-booking-main {
  min-width: 0;

  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-booking-main > div {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weighing-booking-main > div strong {
  color: #31576d;

  font-size: 9px;
}

.admin-weighing-booking-main > span {
  overflow: hidden;

  color: #587281;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-weighing-booking-main > small {
  color: #899aa2;

  font-size: 6px;
}

.admin-weighing-booking-item > svg {
  color: #a1afb5;
}


/* =========================================================
   STATUS DOT
========================================================= */

.admin-weighing-status-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background:
    #218b52;
}

.admin-weighing-status-dot.blue {
  background:
    #287eaa;
}

.admin-weighing-status-dot.orange {
  background:
    #d2772b;
}

.admin-weighing-status-dot.purple {
  background:
    #8064a9;
}

.admin-weighing-status-dot.gold {
  background:
    #c3871c;
}

.admin-weighing-status-dot.green {
  background:
    #218b52;
}


/* =========================================================
   EMPTY LIST
========================================================= */

.admin-weighing-empty {
  min-height: 240px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding: 25px;

  color: #9aa8ae;

  text-align: center;
}

.admin-weighing-empty strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-weighing-empty span {
  max-width: 220px;

  color: #8b9ba2;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   SKELETON
========================================================= */

.admin-weighing-loading {
  display: flex;

  flex-direction: column;
}

.admin-weighing-skeleton {
  display: flex;

  align-items: center;

  gap: 10px;

  min-height: 72px;

  padding:
    0
    17px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-weighing-skeleton > span {
  width: 35px;
  height: 35px;

  border-radius: 10px;

  background: #edf2f4;

  animation:
    adminWeightPulse 1.1s infinite;
}

.admin-weighing-skeleton > div {
  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 6px;
}

.admin-weighing-skeleton > div span {
  height: 7px;

  border-radius: 99px;

  background:
    #edf2f4;

  animation:
    adminWeightPulse 1.1s infinite;
}

.admin-weighing-skeleton > div span:nth-child(1) {
  width: 40%;
}

.admin-weighing-skeleton > div span:nth-child(2) {
  width: 65%;
}

.admin-weighing-skeleton > div span:nth-child(3) {
  width: 45%;
}

@keyframes adminWeightPulse {

  0%,
  100% {
    opacity: .65;
  }

  50% {
    opacity: 1;
  }

}


/* =========================================================
   FORM
========================================================= */

.admin-weighing-form {
  padding: 20px;
}

.admin-weighing-form-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;
}

.admin-weighing-form-token {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #287eaa;

  font-size: 8px;

  font-weight: 900;
}

.admin-weighing-form-header h3 {
  margin: 7px 0 4px;

  color: #2c4f61;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-weighing-form-header p {
  margin: 0;

  color: #85969e;

  font-size: 7px;
}

.admin-weighing-close {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dde6ea;

  border-radius: 8px;

  color: #728792;

  background: #ffffff;

  cursor: pointer;
}

.admin-weighing-close:hover {
  color: #b05046;

  border-color:
    #e2c4bf;
}


/* =========================================================
   STATUS BANNER
========================================================= */

.admin-weighing-status-banner {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-top: 17px;

  padding:
    10px
    12px;

  border:
    1px solid
    #e3eaed;

  border-radius: 10px;

  background: #f8fafb;
}

.admin-weighing-status-banner > span {
  color: #81939c;

  font-size: 7px;

  line-height: 1.5;
}

.admin-weighing-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-weighing-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-weighing-status-pill.green {
  color: #218b52;
  background: #eaf7ed;
}

.admin-weighing-status-pill.blue {
  color: #287eaa;
  background: #e7f3f8;
}

.admin-weighing-status-pill.orange {
  color: #d1772a;
  background: #fff0e5;
}

.admin-weighing-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-weighing-status-pill.gold {
  color: #bd7f18;
  background: #fff2d4;
}


/* =========================================================
   SUMMARY
========================================================= */

.admin-weighing-summary {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 8px;

  margin-top: 13px;

  padding-bottom: 15px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-weighing-summary > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-summary span {
  color: #8999a1;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .04em;
}

.admin-weighing-summary strong {
  overflow: hidden;

  color: #4a6574;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   START WEIGHING
========================================================= */

.admin-weighing-start-card {
  display: flex;

  align-items: center;

  gap: 10px;

  margin-top: 15px;

  padding: 13px;

  border:
    1px solid
    #ded3ec;

  border-radius: 11px;

  background:
    #f8f4fc;
}

.admin-weighing-start-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #8064a9;

  background: #ede6f7;
}

.admin-weighing-start-card > div:nth-child(2) {
  min-width: 0;

  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-start-card h4 {
  margin: 0;

  color: #5b4a72;

  font-family: var(--font-heading);

  font-size: 14px;
}

.admin-weighing-start-card p {
  margin: 0;

  color: #82768d;

  font-size: 7px;

  line-height: 1.5;
}

.admin-weighing-start-button {
  min-height: 36px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border: 0;

  border-radius: 8px;

  color: #ffffff;

  background: #8064a9;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-weighing-start-button:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   SECTION TITLES
========================================================= */

.admin-weighing-section-title {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-bottom: 12px;
}

.admin-weighing-section-title > div:first-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-section-title h4 {
  margin: 0;

  color: #315265;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-weight-status-mark {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 7px;

  color: #657e8b;

  background: #f0f4f5;

  font-size: 6px;

  font-weight: 900;
}


/* =========================================================
   WEIGHT ENTRY
========================================================= */

.admin-weight-entry-section {
  margin-top: 17px;

  padding: 16px;

  border:
    1px solid
    #dce7eb;

  border-radius: 13px;

  background: #fbfcfd;
}

.admin-weight-entry-section.disabled {
  opacity: .72;
}

.admin-weight-comparison {
  display: grid;

  grid-template-columns:
    1fr
    35px
    1.2fr;

  gap: 8px;

  align-items: center;
}

.admin-weight-estimated,
.admin-weight-actual {
  min-width: 0;

  padding:
    14px;

  border:
    1px solid
    #e1e8eb;

  border-radius: 11px;

  background: #ffffff;
}

.admin-weight-estimated {
  background: #f6f9fa;
}

.admin-weight-estimated,
.admin-weight-actual {
  display: flex;

  flex-direction: column;

  gap: 5px;
}

.admin-weight-estimated span,
.admin-weight-actual span {
  color: #899aa2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .05em;
}

.admin-weight-estimated strong {
  color: #526f7e;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-weight-estimated small {
  color: #9aa8ae;

  font-size: 7px;
}

.admin-weight-arrow {
  display: flex;

  align-items: center;

  justify-content: center;

  color: #a3b2b8;
}

.admin-weight-input-wrap {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weight-input-wrap input {
  width: 100%;

  height: 43px;

  padding:
    0
    11px;

  border:
    1px solid
    #cbdde4;

  border-radius: 9px;

  outline: 0;

  color: #2f576b;

  background: #ffffff;

  font-family: var(--font-heading);

  font-size: 21px;

  font-weight: 900;
}

.admin-weight-input-wrap input:focus {
  border-color:
    #287eaa;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .07
    );
}

.admin-weight-input-wrap input:disabled {
  color: #8999a2;

  background:
    #f2f5f6;

  cursor: not-allowed;
}

.admin-weight-input-wrap > span {
  color: #718895;

  font-size: 8px;

  font-weight: 900;
}


/* =========================================================
   DIFFERENCE
========================================================= */

.admin-weight-difference {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-top: 9px;

  padding:
    8px
    10px;

  border-radius: 8px;
}

.admin-weight-difference > div {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weight-difference span {
  color: #778b95;

  font-size: 6px;

  font-weight: 800;
}

.admin-weight-difference strong {
  font-size: 7px;
}

.admin-weight-difference.positive {
  background: #edf8f0;
}

.admin-weight-difference.positive strong {
  color: #218b52;
}

.admin-weight-difference.negative {
  background: #fff3ef;
}

.admin-weight-difference.negative strong {
  color: #bd5a4e;
}

.admin-weight-difference.equal {
  background: #eef4f6;
}

.admin-weight-difference.equal strong {
  color: #537181;
}


/* =========================================================
   QUALITY
========================================================= */

.admin-quality-section {
  margin-top: 17px;
}

.admin-quality-options {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 8px;
}

.admin-quality-option {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  padding:
    12px;

  border:
    1px solid
    #dfe7ea;

  border-radius: 10px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;
}

.admin-quality-option:hover:not(:disabled) {
  border-color:
    #b9cfd7;
}

.admin-quality-option.selected {
  border-color:
    #9dc7aa;

  background:
    #f0f8f2;

  box-shadow:
    inset 0 0 0 1px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-quality-option:disabled {
  opacity: .6;

  cursor: not-allowed;
}

.admin-quality-radio {
  width: 18px;
  height: 18px;

  flex: 0 0 18px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #cad9de;

  border-radius: 50%;
}

.admin-quality-option.selected
.admin-quality-radio {
  border-color:
    #218b52;
}

.admin-quality-radio span {
  width: 8px;
  height: 8px;

  border-radius: 50%;

  background: #218b52;
}

.admin-quality-option > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-quality-option strong {
  color: #3b5b6d;

  font-size: 8px;
}

.admin-quality-option span {
  color: #84969f;

  font-size: 6px;

  line-height: 1.45;
}


/* =========================================================
   NOTES
========================================================= */

.admin-weighing-notes-section {
  margin-top: 17px;
}

.admin-weighing-notes-section textarea {
  width: 100%;

  min-height: 88px;

  resize: vertical;

  padding:
    10px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 9px;

  outline: 0;

  color: #496677;

  background: #ffffff;

  font-family: inherit;

  font-size: 8px;

  line-height: 1.55;
}

.admin-weighing-notes-section textarea:focus {
  border-color:
    #9fbfcf;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-weighing-notes-section textarea:disabled {
  color: #8999a1;

  background: #f3f6f7;

  cursor: not-allowed;
}

.admin-weighing-notes-section textarea::placeholder {
  color: #acb8bd;
}


/* =========================================================
   DISABLED NOTE
========================================================= */

.admin-weighing-disabled-note {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-top: 13px;

  padding:
    9px
    10px;

  border-radius: 8px;

  color: #8c7b62;

  background: #fff8ed;

  font-size: 7px;
}

.admin-weighing-disabled-note svg {
  color: #c48a23;
}


/* =========================================================
   FORM ACTIONS
========================================================= */

.admin-weighing-form-actions {
  display: grid;

  grid-template-columns:
    .7fr
    1fr
    1.35fr;

  gap: 7px;

  margin-top: 18px;

  padding-top: 15px;

  border-top:
    1px solid
    #e8edef;
}

.admin-weighing-cancel,
.admin-weighing-save,
.admin-weighing-complete {
  min-height: 43px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  border-radius: 9px;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-weighing-cancel {
  border:
    1px solid
    #dce5e9;

  color: #6c828e;

  background: #ffffff;
}

.admin-weighing-save {
  border:
    1px solid
    #b9d4df;

  color: #287eaa;

  background: #edf6fa;
}

.admin-weighing-complete {
  border: 0;

  color: #ffffff;

  background: #218b52;

  box-shadow:
    0 8px 18px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-weighing-cancel:hover:not(:disabled) {
  border-color:
    #bfd1d8;
}

.admin-weighing-save:hover:not(:disabled) {
  background: #e4f2f8;
}

.admin-weighing-complete:hover:not(:disabled) {
  background: #197342;
}

.admin-weighing-cancel:disabled,
.admin-weighing-save:disabled,
.admin-weighing-complete:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   COMPLETED
========================================================= */

.admin-weighing-completed-banner {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 17px;

  padding: 14px;

  border:
    1px solid
    #cfe5d4;

  border-radius: 11px;

  color: #218b52;

  background: #eef9f1;
}

.admin-weighing-completed-banner > svg {
  flex: 0 0 auto;
}

.admin-weighing-completed-banner > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-completed-banner strong {
  color: #387253;

  font-size: 9px;
}

.admin-weighing-completed-banner span {
  color: #718a7a;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   PROCESS NOTE
========================================================= */

.admin-weighing-note {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-top: 14px;

  padding:
    12px
    14px;

  border:
    1px solid
    #dce6ea;

  border-radius: 11px;

  background: #f8fafb;
}

.admin-weighing-note-icon {
  width: 30px;
  height: 30px;

  flex: 0 0 30px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #287eaa;

  background: #e6f2f8;
}

.admin-weighing-note > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-note strong {
  color: #496576;

  font-size: 8px;
}

.admin-weighing-note p {
  margin: 0;

  color: #83949d;

  font-size: 7px;

  line-height: 1.55;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1150px) {

  .admin-weighing-workspace {
    grid-template-columns:
      300px
      minmax(0, 1fr);
  }

  .admin-weighing-summary {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 950px) {

  .admin-weighing-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-weighing-workspace {
    grid-template-columns:
      1fr;
  }

  .admin-weighing-booking-list {
    max-height: 320px;
  }

}


@media (max-width: 700px) {

  .admin-weighing-hero {
    flex-direction: column;
  }

  .admin-weighing-hero-actions {
    width: 100%;
  }

  .admin-weighing-live,
  .admin-weighing-refresh {
    flex: 1;
  }

  .admin-weighing-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-quality-options {
    grid-template-columns:
      1fr;
  }

  .admin-weight-comparison {
    grid-template-columns:
      1fr;
  }

  .admin-weight-arrow {
    transform:
      rotate(90deg);
  }

}


@media (max-width: 520px) {

  .admin-weighing-hero h2 {
    font-size: 30px;
  }

  .admin-weighing-form {
    padding: 16px;
  }

  .admin-weighing-summary {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-weighing-form-actions {
    grid-template-columns:
      1fr;
  }

  .admin-weighing-note {
    align-items: flex-start;
  }

}
/* =========================================================
   ADMIN PAYMENTS
========================================================= */

.admin-payments-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-payments-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 25px;

  margin-bottom: 18px;
}

.admin-payments-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    29px,
    3vw,
    41px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-payments-hero p {
  max-width: 730px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-payments-hero-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-payment-live {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #218b52;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-payment-live > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #218b52;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-payment-refresh {
  min-height: 32px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5d7887;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-payment-refresh:hover:not(:disabled) {
  color: #287eaa;

  border-color:
    #bad0da;
}

.admin-payment-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-payment-feedback {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    11px
    13px;

  border-radius: 10px;
}

.admin-payment-feedback.error {
  border:
    1px solid
    #efd0ca;

  color: #b15348;

  background: #fff4f2;
}

.admin-payment-feedback.success {
  border:
    1px solid
    #cfe5d4;

  color: #2f7550;

  background: #eef9f1;
}

.admin-payment-feedback > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-payment-feedback > span {
  flex: 1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-payment-feedback button {
  display: flex;

  align-items: center;
  justify-content: center;

  padding: 2px;

  border: 0;

  color: currentColor;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   KPI
========================================================= */

.admin-payment-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-bottom: 15px;
}

.admin-payment-kpi {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  padding:
    14px;

  border:
    1px solid
    #dce6ea;

  border-radius: 14px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-payment-kpi-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-payment-kpi.gold
.admin-payment-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-payment-kpi.blue
.admin-payment-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-payment-kpi.green
.admin-payment-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-payment-kpi.purple
.admin-payment-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-payment-kpi-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-kpi-content strong {
  overflow: hidden;

  color: #304f61;

  font-family: var(--font-heading);

  font-size: 18px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-kpi-content span {
  color: #768c97;

  font-size: 7px;

  line-height: 1.4;
}

.admin-payment-kpi-content small {
  color: #9aa7ad;

  font-size: 6px;
}


/* =========================================================
   WORKSPACE
========================================================= */

.admin-payments-workspace {
  display: grid;

  grid-template-columns:
    370px
    minmax(0, 1fr);

  gap: 15px;

  align-items: start;
}

.admin-payments-list-panel,
.admin-payments-form-panel {
  min-width: 0;

  border:
    1px solid
    #dce6ea;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 28px
    rgba(
      30,
      62,
      77,
      .04
    );
}


/* =========================================================
   LIST PANEL
========================================================= */

.admin-payment-panel-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 10px;

  padding:
    17px
    17px
    13px;
}

.admin-payment-panel-heading > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-panel-heading h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-payment-panel-heading > span {
  color: #96a4aa;

  font-size: 7px;
}

.admin-payment-search {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    0
    17px
    11px;

  padding:
    0
    10px;

  border:
    1px solid
    #dce5e9;

  border-radius: 8px;

  color: #8799a1;

  background: #fafcfd;
}

.admin-payment-search:focus-within {
  border-color:
    #a9c5d0;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-search input {
  width: 100%;

  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-payment-search input::placeholder {
  color: #adb9bf;
}

.admin-payment-list {
  display: flex;

  flex-direction: column;

  max-height: 720px;

  overflow-y: auto;
}


/* =========================================================
   PAYMENT ITEM
========================================================= */

.admin-payment-item {
  width: 100%;

  display: grid;

  grid-template-columns:
    37px
    minmax(0, 1fr)
    auto;

  gap: 9px;

  align-items: center;

  min-height: 78px;

  padding:
    10px
    17px;

  border: 0;

  border-top:
    1px solid
    #edf1f3;

  color: #315064;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  transition:
    background .13s ease,
    box-shadow .13s ease;
}

.admin-payment-item:hover {
  background:
    #fafcfd;
}

.admin-payment-item.selected {
  background:
    #eef7f1;

  box-shadow:
    inset 3px 0 0
    #218b52;
}

.admin-payment-token {
  width: 37px;
  height: 37px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #287eaa;

  background: #e5f2f8;
}

.admin-payment-item-main {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-item-main > div {
  display: flex;

  align-items: center;

  gap: 6px;
}

.admin-payment-item-main > div strong {
  color: #31566b;

  font-size: 9px;
}

.admin-payment-item-main > span {
  overflow: hidden;

  color: #5a7280;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-item-main > small {
  color: #899aa2;

  font-size: 6px;
}

.admin-payment-item-amount {
  min-width: 75px;

  display: flex;

  flex-direction: column;

  align-items: flex-end;

  gap: 5px;
}

.admin-payment-item-amount > strong {
  color: #36586a;

  font-family: var(--font-heading);

  font-size: 9px;
}

.admin-payment-status-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #287eaa;
}

.admin-payment-status-dot.gold {
  background: #c38a20;
}

.admin-payment-status-dot.green {
  background: #218b52;
}

.admin-payment-status-dot.purple {
  background: #8064a9;
}


/* =========================================================
   STATUS PILL
========================================================= */

.admin-payment-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  width: fit-content;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-payment-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-payment-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-payment-status-pill.gold {
  color: #bd7f18;
  background: #fff2d4;
}

.admin-payment-status-pill.green {
  color: #218b52;
  background: #eaf7ed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-payment-empty {
  min-height: 260px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding: 25px;

  color: #9aa8ae;

  text-align: center;
}

.admin-payment-empty strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-payment-empty span {
  max-width: 230px;

  color: #8b9ba2;

  font-size: 7px;

  line-height: 1.5;
}

.admin-payment-loading {
  display: flex;

  flex-direction: column;
}

.admin-payment-skeleton {
  display: grid;

  grid-template-columns:
    37px
    1fr
    55px;

  gap: 9px;

  align-items: center;

  min-height: 78px;

  padding:
    0
    17px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-payment-skeleton > span:first-child {
  width: 37px;
  height: 37px;

  border-radius: 10px;

  background:
    #edf2f4;
}

.admin-payment-skeleton > div {
  display: flex;

  flex-direction: column;

  gap: 6px;
}

.admin-payment-skeleton > div span {
  height: 7px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminPaymentSkeleton 1.2s infinite;
}

.admin-payment-skeleton > div span:nth-child(1) {
  width: 45%;
}

.admin-payment-skeleton > div span:nth-child(2) {
  width: 70%;
}

.admin-payment-skeleton > div span:nth-child(3) {
  width: 52%;
}

.admin-payment-skeleton > span:last-child {
  width: 50px;
  height: 8px;

  border-radius: 99px;

  background:
    #edf2f4;

  animation:
    adminPaymentSkeleton 1.2s infinite;
}

@keyframes adminPaymentSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   PAYMENT FORM
========================================================= */

.admin-payment-form {
  padding: 20px;
}

.admin-payment-form-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;
}

.admin-payment-form-token {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #287eaa;

  font-size: 8px;

  font-weight: 900;
}

.admin-payment-form-header h3 {
  margin: 7px 0 4px;

  color: #2c4f61;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-payment-form-header p {
  margin: 0;

  color: #85969e;

  font-size: 7px;
}

.admin-payment-close {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dde6ea;

  border-radius: 8px;

  color: #728792;

  background: #ffffff;

  cursor: pointer;
}

.admin-payment-close:hover {
  color: #b05046;

  border-color:
    #e2c4bf;
}


/* =========================================================
   STATUS BANNER
========================================================= */

.admin-payment-status-banner {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-top: 17px;

  padding:
    10px
    12px;

  border:
    1px solid
    #e3eaed;

  border-radius: 10px;

  background: #f8fafb;
}

.admin-payment-status-banner > span {
  color: #81939c;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   SUMMARY
========================================================= */

.admin-payment-summary {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 8px;

  margin-top: 13px;

  padding-bottom: 15px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-payment-summary > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-summary span {
  color: #8999a1;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .04em;
}

.admin-payment-summary strong {
  overflow: hidden;

  color: #496574;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   SECTION HEADING
========================================================= */

.admin-payment-section-heading {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-bottom: 11px;
}

.admin-payment-section-heading > div:first-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-section-heading h4 {
  margin: 0;

  color: #315265;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-payment-calculation-badge {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 7px;

  color: #5f7785;

  background: #f0f4f5;

  font-size: 6px;

  font-weight: 900;
}


/* =========================================================
   CALCULATION
========================================================= */

.admin-payment-calculation {
  margin-top: 17px;

  padding: 16px;

  border:
    1px solid
    #dce7eb;

  border-radius: 13px;

  background: #fbfcfd;
}

.admin-payment-equation {
  display: grid;

  grid-template-columns:
    1fr
    25px
    1.15fr
    25px
    1.1fr;

  gap: 7px;

  align-items: end;
}

.admin-payment-equation > div:first-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 5px;

  padding:
    12px;

  border:
    1px solid
    #e1e8eb;

  border-radius: 10px;

  background: #ffffff;
}

.admin-payment-equation > div:first-child span,
.admin-payment-total-box span {
  color: #899aa1;

  font-size: 6px;

  font-weight: 900;
}

.admin-payment-equation > div:first-child strong {
  color: #526f7e;

  font-family: var(--font-heading);

  font-size: 20px;
}

.admin-payment-equation > div:first-child small {
  margin-left: 3px;

  color: #98a6ac;

  font-size: 6px;
}

.admin-payment-multiply,
.admin-payment-equals {
  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 42px;

  color: #a1afb5;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-rate-field {
  min-width: 0;
}

.admin-rate-field label {
  display: block;

  margin-bottom: 5px;

  color: #899aa1;

  font-size: 6px;

  font-weight: 900;
}

.admin-rate-field > div {
  height: 42px;

  display: flex;

  align-items: center;

  gap: 4px;

  padding:
    0
    9px;

  border:
    1px solid
    #cbdde4;

  border-radius: 9px;

  background: #ffffff;
}

.admin-rate-field > div:focus-within {
  border-color:
    #287eaa;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .06
    );
}

.admin-rate-field > div > span {
  color: #647f8d;

  font-size: 10px;

  font-weight: 900;
}

.admin-rate-field input {
  width: 100%;
  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #375a6c;

  background: transparent;

  font-family: var(--font-heading);

  font-size: 17px;

  font-weight: 900;
}

.admin-rate-field input:disabled {
  color: #87989f;
}

.admin-payment-total-box {
  min-width: 0;

  display: flex;

  flex-direction: column;

  justify-content: center;

  gap: 5px;

  min-height: 64px;

  padding:
    10px
    12px;

  border:
    1px solid
    #cfe5d5;

  border-radius: 10px;

  background:
    #eef8f0;
}

.admin-payment-total-box strong {
  overflow: hidden;

  color: #218b52;

  font-family: var(--font-heading);

  font-size: 19px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-calculation-note {
  display: flex;

  align-items: center;

  gap: 6px;

  margin-top: 9px;

  padding:
    8px
    9px;

  border-radius: 8px;

  color: #47755a;

  background: #edf8ef;

  font-size: 6px;
}

.admin-payment-calculation-note svg {
  flex: 0 0 auto;
}


/* =========================================================
   PAYMENT METHODS
========================================================= */

.admin-payment-method-section {
  margin-top: 17px;
}

.admin-payment-method-grid {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 8px;
}

.admin-payment-method {
  min-width: 0;

  display: grid;

  grid-template-columns:
    17px
    34px
    1fr;

  gap: 8px;

  align-items: center;

  padding:
    11px;

  border:
    1px solid
    #dfe7ea;

  border-radius: 10px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;
}

.admin-payment-method:hover:not(:disabled) {
  border-color:
    #bcd0d8;
}

.admin-payment-method.selected {
  border-color:
    #a0c8ad;

  background:
    #f0f8f2;
}

.admin-payment-method:disabled {
  opacity: .65;

  cursor: not-allowed;
}

.admin-payment-method-radio {
  width: 16px;
  height: 16px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #cad9de;

  border-radius: 50%;
}

.admin-payment-method.selected
.admin-payment-method-radio {
  border-color:
    #218b52;
}

.admin-payment-method-radio span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background:
    #218b52;
}

.admin-payment-method-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #287eaa;

  background: #e6f2f8;
}

.admin-payment-method:nth-child(2)
.admin-payment-method-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-payment-method:nth-child(3)
.admin-payment-method-icon {
  color: #c3871d;
  background: #fff0cc;
}

.admin-payment-method > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-method strong {
  color: #3d5c6d;

  font-size: 8px;
}

.admin-payment-method > div:last-child span {
  color: #87979f;

  font-size: 6px;

  line-height: 1.45;
}


/* =========================================================
   REFERENCE
========================================================= */

.admin-payment-reference-section {
  margin-top: 17px;
}

.admin-payment-reference-section > input {
  width: 100%;

  height: 42px;

  padding:
    0
    10px;

  border:
    1px solid
    #d7e3e8;

  border-radius: 9px;

  outline: 0;

  color: #426273;

  background: #ffffff;

  font-size: 8px;
}

.admin-payment-reference-section > input:focus {
  border-color:
    #8fb8c9;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-reference-section > input:disabled {
  color: #8999a1;

  background:
    #f3f6f7;
}

.admin-payment-reference-section > input::placeholder {
  color: #abb7bc;
}

.admin-payment-reference-section > small {
  display: block;

  margin-top: 5px;

  color: #919fa5;

  font-size: 6px;

  line-height: 1.5;
}


/* =========================================================
   NOTES
========================================================= */

.admin-payment-notes-section {
  margin-top: 17px;
}

.admin-payment-notes-section textarea {
  width: 100%;

  min-height: 75px;

  resize: vertical;

  padding:
    10px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 9px;

  outline: 0;

  color: #4a6675;

  background: #ffffff;

  font-family: inherit;

  font-size: 8px;

  line-height: 1.55;
}

.admin-payment-notes-section textarea:focus {
  border-color:
    #9dbfcb;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-notes-section textarea:disabled {
  color: #8999a1;

  background:
    #f3f6f7;
}

.admin-payment-notes-section textarea::placeholder {
  color: #aab7bc;
}


/* =========================================================
   VERIFICATION
========================================================= */

.admin-payment-verification {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  margin-top: 15px;

  padding:
    10px
    11px;

  border:
    1px solid
    #dbe7ec;

  border-radius: 9px;

  color: #287eaa;

  background: #f4f9fb;
}

.admin-payment-verification > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-payment-verification > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-verification strong {
  color: #496a7b;

  font-size: 8px;
}

.admin-payment-verification span {
  color: #80929b;

  font-size: 6px;

  line-height: 1.5;
}


/* =========================================================
   ACTIONS
========================================================= */

.admin-payment-form-actions {
  display: grid;

  grid-template-columns:
    .7fr
    1fr
    1.35fr;

  gap: 7px;

  margin-top: 18px;

  padding-top: 15px;

  border-top:
    1px solid
    #e8edef;
}

.admin-payment-cancel,
.admin-payment-pending,
.admin-payment-send {
  min-height: 43px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  border-radius: 9px;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-payment-cancel {
  border:
    1px solid
    #dce5e9;

  color: #6b818d;

  background: #ffffff;
}

.admin-payment-pending {
  border:
    1px solid
    #e1cb8d;

  color: #8b671a;

  background: #fff7df;
}

.admin-payment-send {
  border: 0;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #218b52,
      #2b9a5e
    );

  box-shadow:
    0 8px 18px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-payment-cancel:hover:not(:disabled) {
  border-color:
    #bdcfd6;
}

.admin-payment-pending:hover:not(:disabled) {
  background:
    #fff2c7;
}

.admin-payment-send:hover:not(:disabled) {
  background:
    #197342;
}

.admin-payment-cancel:disabled,
.admin-payment-pending:disabled,
.admin-payment-send:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   COMPLETED
========================================================= */

.admin-payment-completed {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-top: 17px;

  padding: 15px;

  border:
    1px solid
    #cfe5d4;

  border-radius: 12px;

  background:
    #eef9f1;
}

.admin-payment-completed-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #218b52;

  background: #dff1e4;
}

.admin-payment-completed > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-completed strong {
  color: #3d7255;

  font-size: 9px;
}

.admin-payment-completed span {
  color: #718879;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1200px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-payments-workspace {
    grid-template-columns:
      1fr;
  }

  .admin-payment-list {
    max-height: 330px;
  }

}


@media (max-width: 800px) {

  .admin-payments-hero {
    flex-direction: column;
  }

  .admin-payments-hero-actions {
    width: 100%;
  }

  .admin-payment-live,
  .admin-payment-refresh {
    flex: 1;
  }

  .admin-payment-summary {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-payment-method-grid {
    grid-template-columns:
      1fr;
  }

  .admin-payment-equation {
    grid-template-columns:
      1fr;
  }

  .admin-payment-multiply,
  .admin-payment-equals {
    min-height: 20px;

    transform:
      rotate(90deg);
  }

}


@media (max-width: 600px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-payment-kpi {
    padding: 10px;
  }

  .admin-payment-kpi-content strong {
    font-size: 15px;
  }

  .admin-payment-form {
    padding: 16px;
  }

  .admin-payment-form-actions {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 460px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-payment-summary {
    grid-template-columns:
      1fr;
  }

  .admin-payment-item {
    grid-template-columns:
      35px
      minmax(0, 1fr);
  }

  .admin-payment-item-amount {
    display: none;
  }

}
/* =========================================================
   ADMIN REPORTS
========================================================= */

.admin-reports-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-reports-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-reports-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-reports-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-reports-hero-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-report-data-chip {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-report-refresh,
.admin-report-export {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-report-refresh {
  border: 1px solid #d9e4e8;
  color: #5d7887;
  background: #ffffff;
}

.admin-report-refresh:hover:not(:disabled) {
  color: #287eaa;
  border-color: #bad0da;
}

.admin-report-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.admin-report-export {
  border: 0;
  color: #ffffff;
  background: #287eaa;
}

.admin-report-export:hover {
  background: #226d93;
}


/* =========================================================
   ERROR
========================================================= */

.admin-report-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-report-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-report-error > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-error strong {
  font-size: 8px;
}

.admin-report-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-report-error button {
  margin-left: auto;
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-reports-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dce6ea;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-reports-search {
  flex: 1;
  min-width: 190px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #84969e;
  background: #fafcfd;
}

.admin-reports-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-reports-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-reports-search input::placeholder {
  color: #aebbc1;
}

.admin-report-filter {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #81939d;
  background: #fafcfd;
}

.admin-report-filter:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-report-filter select {
  min-width: 88px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-reports-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-report-kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 9px;
  margin-bottom: 15px;
}

.admin-report-kpi {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 13px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 21px
    rgba(30, 62, 77, .03);
}

.admin-report-kpi-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-report-kpi.blue .admin-report-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-report-kpi.green .admin-report-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-report-kpi.gold .admin-report-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-report-kpi.orange .admin-report-kpi-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-report-kpi.purple .admin-report-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-report-kpi.teal .admin-report-kpi-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-report-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 17px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-report-kpi strong small {
  color: #8b9aa1;
  font-family: inherit;
  font-size: 7px;
}

.admin-report-kpi span {
  color: #768c97;
  font-size: 6px;
  line-height: 1.4;
}


/* =========================================================
   ANALYTICS GRID
========================================================= */

.admin-reports-analytics-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 14px;
}

.admin-report-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
}

.admin-report-daily-panel {
  min-height: 260px;
}

.admin-report-panel-header {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 17px 18px 13px;
}

.admin-report-panel-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-report-panel-icon.blue {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-report-panel-icon.green {
  color: #218b52;
  background: #e4f4e8;
}

.admin-report-panel-icon.gold {
  color: #be811a;
  background: #fff0ce;
}

.admin-report-panel-icon.purple {
  color: #8064a9;
  background: #eee9f7;
}

.admin-report-panel-icon.teal {
  color: #288e91;
  background: #e2f4f3;
}

.admin-report-panel-header > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-panel-header span {
  color: #8a9aa2;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .1em;
}

.admin-report-panel-header h3 {
  margin: 0;
  color: #345467;
  font-family: var(--font-heading);
  font-size: 15px;
}


/* =========================================================
   CROP CHART
========================================================= */

.admin-report-chart-list {
  display: flex;
  flex-direction: column;
  gap: 13px;
  padding:
    2px
    18px
    18px;
}

.admin-horizontal-bar-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.admin-horizontal-bar-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.admin-horizontal-bar-heading span {
  color: #607986;
  font-size: 7px;
