/* =========================================================
   PAYMENT ANALYSIS
========================================================= */

.admin-payment-analysis {
  padding:
    0
    18px
    17px;
}

.admin-payment-analysis-row {
  min-height: 37px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid #edf1f3;
}

.admin-payment-analysis-row:first-child {
  border-top: 0;
}

.admin-payment-analysis-row > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-payment-analysis-row > div > span:last-child {
  color: #687f8c;
  font-size: 7px;
}

.admin-payment-analysis-row strong {
  color: #405e70;
  font-family: var(--font-heading);
  font-size: 9px;
}

.admin-payment-analysis-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.admin-payment-analysis-dot.green {
  background: #218b52;
}

.admin-payment-analysis-dot.gold {
  background: #c3871c;
}

.admin-payment-analysis-dot.blue {
  background: #287eaa;
}

.admin-payment-method-heading {
  margin:
    12px
    0
    5px;

  color: #9aa7ad;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-payment-method-row {
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #f0f3f4;
}

.admin-payment-method-row span {
  color: #7b8e97;
  font-size: 6px;
}

.admin-payment-method-row strong {
  color: #516c7a;
  font-size: 7px;
}


/* =========================================================
   DAILY CHART
========================================================= */

.admin-daily-chart {
  min-height: 190px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding:
    8px
    18px
    17px;
}

.admin-daily-column {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.admin-daily-bar-area {
  width: 100%;
  height: 145px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  border-bottom:
    1px solid
    #e3eaed;
}

.admin-daily-bar {
  position: relative;
  width: 55%;
  min-width: 10px;
  max-width: 30px;
  border-radius:
    6px
    6px
    0
    0;
  background:
    linear-gradient(
      180deg,
      #8064a9,
      #a18bc2
    );
}

.admin-daily-bar span {
  position: absolute;

  top: -14px;
  left: 50%;

  transform:
    translateX(-50%);

  color: #6d7f89;

  font-size: 5px;
  font-weight: 900;
}

.admin-daily-column > span {
  overflow: hidden;
  color: #8999a1;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   EMPTY ANALYTICS
========================================================= */

.admin-report-empty {
  min-height: 150px;

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 7px;

  padding: 20px;

  color: #99a8ae;

  text-align: center;
}

.admin-report-empty span {
  max-width: 220px;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   DETAIL TABLE
========================================================= */

.admin-report-record-panel {
  margin-top: 0;
}

.admin-report-record-table {
  width: 100%;
  overflow-x: auto;
}

.admin-report-record-head,
.admin-report-record-row {
  min-width: 860px;

  display: grid;

  grid-template-columns:
    1fr
    1.3fr
    .9fr
    .95fr
    .95fr
    1fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    18px;
}

.admin-report-record-head {
  min-height: 34px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e7edef;

  color: #99a7ad;

  background: #fafcfd;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-report-record-row {
  min-height: 67px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-report-record-row:hover {
  background: #fbfcfd;
}

.admin-report-record-row > div {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-record-row strong {
  overflow: hidden;

  color: #456273;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-report-record-row span {
  color: #8c9ba2;

  font-size: 6px;
}

.admin-report-status {
  width: fit-content;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 5px !important;

  font-weight: 900;

  white-space: nowrap;
}

.admin-report-status.blue {
  color: #287eaa;
  background: #e7f3f8;
}

.admin-report-status.green {
  color: #218b52;
  background: #eaf7ed;
}

.admin-report-status.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-report-status.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-report-status.gold {
  color: #bd7f18;
  background: #fff2d4;
}


/* =========================================================
   TABLE EMPTY / LOADING
========================================================= */

.admin-report-no-records {
  min-height: 260px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 6px;

  padding: 30px;

  color: #9caab0;

  text-align: center;
}

.admin-report-no-records strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-report-no-records span {
  color: #8c9ba2;

  font-size: 7px;

  line-height: 1.5;
}

.admin-report-loading {
  min-width: 860px;
}

.admin-report-skeleton-row {
  min-height: 67px;

  display: grid;

  grid-template-columns:
    repeat(6, 1fr);

  gap: 10px;

  align-items: center;

  padding:
    0
    18px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-report-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminReportSkeleton 1.2s infinite;
}

@keyframes adminReportSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}

.admin-report-table-footer {
  min-height: 42px;

  display: flex;

  align-items: center;

  padding:
    0
    18px;

  color: #93a1a7;

  font-size: 6px;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-reports-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  margin-top: 12px;

  padding:
    3px
    2px
    10px;

  color: #8d9ca2;

  font-size: 6px;
}

.admin-reports-footer > div {
  display: inline-flex;

  align-items: center;

  gap: 5px;
}

.admin-reports-footer svg {
  color: #287eaa;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-reports-hero {
    flex-direction: column;
  }

  .admin-reports-hero-actions {
    width: 100%;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1;
  }

  .admin-reports-analytics-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 800px) {

  .admin-reports-filter-panel {
    flex-wrap: wrap;
  }

  .admin-reports-search {
    flex-basis: 100%;
  }

  .admin-report-filter {
    flex: 1;
  }

  .admin-report-filter select {
    min-width: 75px;
  }

  .admin-reports-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 600px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-report-kpi {
    padding: 10px;
  }

  .admin-report-kpi-icon {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
  }

  .admin-report-kpi strong {
    font-size: 15px;
  }

  .admin-reports-hero h2 {
    font-size: 30px;
  }

  .admin-reports-hero-actions {
    flex-wrap: wrap;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1 1 30%;
  }

}


@media (max-width: 450px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-report-filter {
    flex-basis: 100%;
  }

  .admin-reports-clear {
    width: 100%;
  }

}
/* =========================================================
   ADMIN FARMERS
========================================================= */

.admin-farmers-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-farmers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-farmers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-farmers-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-farmers-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-farmers-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmers-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmers-refresh:hover:not(:disabled) {
  color: #287eaa;
  border-color: #bad0da;
}

.admin-farmers-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-farmers-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-farmers-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-farmers-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmers-error strong {
  font-size: 8px;
}

.admin-farmers-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-farmers-error button {
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-farmer-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 15px;
}

.admin-farmer-kpi {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-farmer-kpi-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-farmer-kpi.blue
.admin-farmer-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-farmer-kpi.green
.admin-farmer-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-farmer-kpi.purple
.admin-farmer-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-farmer-kpi.gold
.admin-farmer-kpi-icon {
  color: #c3871c;
  background: #fff0ce;
}

.admin-farmer-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 20px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-kpi strong small {
  color: #8b9aa1;
  font-family: inherit;
  font-size: 7px;
}

.admin-farmer-kpi span {
  color: #7b8f98;
  font-size: 7px;
}


/* =========================================================
   FILTER PANEL
========================================================= */

.admin-farmers-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dce6ea;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-farmers-search {
  flex: 1;
  min-width: 200px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #84969e;
  background: #fafcfd;
}

.admin-farmers-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-farmers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-farmers-search input::placeholder {
  color: #adb9bf;
}

.admin-farmers-filter {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #81939d;
  background: #fafcfd;
}

.admin-farmers-filter:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-farmers-filter select {
  min-width: 95px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-farmers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   TABLE PANEL
========================================================= */

.admin-farmers-table-panel {
  overflow: hidden;
  border: 1px solid #dce6ea;
  border-radius: 17px;
  background: #ffffff;
  box-shadow:
    0 10px 28px
    rgba(30, 62, 77, .04);
}

.admin-farmers-table-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 18px 14px;
}

.admin-farmers-table-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmers-table-header h3 {
  margin: 0;
  color: #2f5063;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-farmers-table-header > span {
  color: #95a3a9;
  font-size: 7px;
}


/* =========================================================
   TABLE
========================================================= */

.admin-farmers-table {
  width: 100%;
  overflow-x: auto;
}

.admin-farmers-table-head,
.admin-farmer-row {
  min-width: 1050px;
  display: grid;

  grid-template-columns:
    1.3fr
    1fr
    1.25fr
    1fr
    .75fr
    .8fr;

  column-gap: 11px;
  align-items: center;
  padding: 0 18px;
