  align-items: center;
}

.admin-farmer-main-cell {
  gap: 9px;
}

.admin-farmer-large-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #718795;
  background: #edf2f4;
}

.admin-farmer-main-cell > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-main-cell strong {
  overflow: hidden;
  color: #3d5a6b;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-main-cell span {
  overflow: hidden;
  color: #9aa7ad;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
