.admin-farmer-location-cell {
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.admin-farmer-location-cell strong {
  overflow: hidden;
  color: #4c6877;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-location-cell span {
  overflow: hidden;
  color: #8b9ba2;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   CROP
========================================================= */

.admin-farmer-crop-cell > div {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.admin-farmer-crop-cell svg {
  color: #218b52;
}

.admin-farmer-crop-cell strong {
  color: #496677;
  font-size: 7px;
}


/* =========================================================
   ACTIVITY
========================================================= */

.admin-farmer-activity-cell {
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.admin-farmer-activity-cell strong {
  color: #3c5d6d;
  font-family: var(--font-heading);
  font-size: 13px;
}

.admin-farmer-activity-cell span {
  color: #8999a1;
  font-size: 6px;
}

.admin-farmer-activity-cell small {
  padding: 3px 5px;
  border-radius: 999px;
  color: #287eaa;
  background: #e8f3f8;
  font-size: 5px;
  font-weight: 900;
}


/* =========================================================
   ACTION
========================================================= */

.admin-farmer-view-button {
  min-height: 31px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #dbe5e9;
  border-radius: 7px;
  color: #567483;
  background: #ffffff;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-farmer-view-button:hover {
  color: #287eaa;
  border-color: #b9d1db;
  background: #f8fbfc;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-farmers-empty {
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  color: #99a8ae;
  text-align: center;
}

.admin-farmers-empty strong {
  color: #5e7784;
  font-size: 10px;
}

.admin-farmers-empty span {
  color: #8b9ba2;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-farmer-loading {
  min-width: 1050px;
}

.admin-farmer-skeleton {
  min-height: 76px;
  display: grid;
  grid-template-columns:
    1.3fr
    1fr
    1.25fr
    1fr
    .75fr
    .8fr;
  gap: 11px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-farmer-skeleton > span:first-child {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #edf2f4;
}

.admin-farmer-skeleton > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.admin-farmer-skeleton > div span {
  height: 7px;
  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size: 200% 100%;
  animation: adminFarmerSkeleton 1.2s infinite;
}

.admin-farmer-skeleton > div span:first-child {
  width: 55%;
}

.admin-farmer-skeleton > div span:last-child {
  width: 38%;
}

.admin-farmer-skeleton > span:not(:first-child) {
  height: 8px;
  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size: 200% 100%;
  animation: adminFarmerSkeleton 1.2s infinite;
}

@keyframes adminFarmerSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-farmers-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
  padding:
    3px
    2px
    10px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   DRAWER OVERLAY
========================================================= */

.admin-farmer-drawer-overlay {
  position: fixed;
  z-index: 100;
  inset: 0;
  background: rgba(24, 51, 64, .28);
}


/* =========================================================
   DRAWER
========================================================= */

.admin-farmer-drawer {
  position: fixed;
  z-index: 110;
  top: 0;
  right: 0;
  bottom: 0;

  width: min(
    520px,
    95vw
  );

  display: flex;
  flex-direction: column;

  background: #ffffff;

  box-shadow:
    -18px 0 50px
    rgba(27, 54, 68, .15);

  animation:
    adminFarmerDrawerIn .2s ease;
}

@keyframes adminFarmerDrawerIn {

  from {
    transform: translateX(20px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }

}

.admin-farmer-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 21px;
  border-bottom: 1px solid #e7edef;
}

.admin-farmer-drawer-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-drawer-header h2 {
  margin: 0;
  color: #294c5f;
  font-family: var(--font-heading);
  font-size: 24px;
}

.admin-farmer-drawer-header > div > span:last-child {
  color: #96a4aa;
  font-size: 6px;
}

.admin-farmer-drawer-close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce5e9;
  border-radius: 9px;
  color: #6d8390;
  background: #ffffff;
  cursor: pointer;
}

.admin-farmer-drawer-close:hover {
  color: #b05046;
  border-color: #dfc2bd;
}


/* =========================================================
   DRAWER PROFILE
========================================================= */

.admin-farmer-profile-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 21px;
  border-bottom: 1px solid #edf1f3;
  background: #fafcfd;
}

.admin-farmer-profile-avatar {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  color: #287eaa;
  background: #e5f2f8;
}

.admin-farmer-profile-summary > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-profile-summary strong {
  color: #3d5b6b;
  font-size: 10px;
}

.admin-farmer-profile-summary span {
  color: #84979f;
  font-size: 7px;
}


/* =========================================================
   DRAWER DETAILS
========================================================= */

.admin-farmer-profile-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  margin: 15px 21px 0;
  overflow: hidden;
  border: 1px solid #e5ecef;
  border-radius: 11px;
  background: #e5ecef;
}

.admin-farmer-drawer-field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  background: #ffffff;
}

.admin-farmer-drawer-field span {
  color: #8c9ba2;
  font-size: 6px;
}

.admin-farmer-drawer-field strong {
  overflow: hidden;
  color: #466474;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   DRAWER STATS
========================================================= */

.admin-farmer-profile-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 12px 21px;
}

.admin-farmer-profile-stats > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 11px;
  border: 1px solid #dfe7ea;
  border-radius: 10px;
  background: #fafcfd;
}

.admin-farmer-profile-stats strong {
  color: #37596b;
  font-family: var(--font-heading);
  font-size: 13px;
}

.admin-farmer-profile-stats span {
  color: #8999a1;
  font-size: 6px;
}


/* =========================================================
   HISTORY
========================================================= */

.admin-farmer-history {
  margin:
    4px
    21px
    18px;
}

.admin-farmer-history-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}

.admin-farmer-history-heading > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-history-heading h3 {
  margin: 0;
  color: #3c5c6d;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-farmer-history-heading > span {
  color: #8e9da4;
  font-size: 7px;
}

.admin-farmer-history-row {
  display: grid;
  grid-template-columns:
    58px
    1fr
    auto;
  gap: 8px;
  align-items: center;
  min-height: 54px;
  padding:
    7px
    0;
  border-top: 1px solid #edf1f3;
}

.admin-farmer-history-token {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  padding: 0 6px;
  border-radius: 7px;
  color: #287eaa;
  background: #e7f3f8;
  font-size: 6px;
  font-weight: 900;
}

.admin-farmer-history-row > div:nth-child(2),
.admin-farmer-history-row > div:nth-child(3) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-history-row strong {
  overflow: hidden;
  color: #496575;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-history-row span {
  color: #8b9ba2;
  font-size: 6px;
}

.admin-farmer-history-row > div:last-child {
  align-items: flex-end;
}

.admin-farmer-history-empty {
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  color: #98a6ac;
  text-align: center;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-farmer-drawer-footer {
  margin-top: auto;
  min-height: 63px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding:
    11px
    21px;
  border-top: 1px solid #e7edef;
  background: #ffffff;
}

.admin-farmer-drawer-footer button {
  min-height: 35px;
  padding: 0 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #617985;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmer-drawer-footer button:hover {
  color: #287eaa;
  border-color: #b9d0da;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1200px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 900px) {

  .admin-farmers-hero {
    flex-direction: column;
  }

  .admin-farmers-actions {
    width: 100%;
  }

  .admin-farmers-live,
  .admin-farmers-refresh {
    flex: 1;
  }

}


@media (max-width: 700px) {

  .admin-farmers-filter-panel {
    flex-wrap: wrap;
  }

  .admin-farmers-search {
    flex-basis: 100%;
  }

  .admin-farmers-filter {
    flex: 1;
  }

  .admin-farmers-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 560px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-farmer-kpi {
    padding: 10px;
  }

  .admin-farmer-kpi strong {
    font-size: 16px;
  }

  .admin-farmers-hero h2 {
    font-size: 30px;
  }

  .admin-farmer-profile-grid {
    grid-template-columns: 1fr;
  }

  .admin-farmer-profile-stats {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 420px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-farmers-filter {
    flex-basis: 100%;
  }

  .admin-farmers-clear {
    width: 100%;
  }

}
/* =========================================================
   ADMIN CENTERS
========================================================= */

.admin-centers-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-centers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-centers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-centers-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-centers-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-centers-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-centers-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-centers-refresh:hover:not(:disabled) {
  color: #287eaa;
  border-color: #bad0da;
}

.admin-centers-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-centers-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-centers-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-centers-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-centers-error strong {
  font-size: 8px;
}

.admin-centers-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-centers-error button {
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-center-kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 15px;
}

.admin-center-kpi {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-center-kpi-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-center-kpi.blue .admin-center-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-center-kpi.green .admin-center-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-center-kpi.purple .admin-center-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-center-kpi.gold .admin-center-kpi-icon {
  color: #c3871c;
  background: #fff0ce;
}

.admin-center-kpi.teal .admin-center-kpi-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-center-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-center-kpi strong {
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-center-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-centers-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dce6ea;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-centers-search {
  flex: 1;
  min-width: 210px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #84969e;
  background: #fafcfd;
}

.admin-centers-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-centers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-centers-search input::placeholder {
  color: #aebbc1;
}

.admin-centers-filter {
  height: 36px;
  display: flex;
  align-items: center;
  padding: 0 9px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  background: #fafcfd;
}

.admin-centers-filter select {
  height: 100%;
  min-width: 100px;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-centers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   CENTER GRID
========================================================= */

.admin-centers-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.admin-center-card {
  min-width: 0;
  padding: 16px;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
  transition:
    transform .15s ease,
    box-shadow .15s ease,
    border-color .15s ease;
}

.admin-center-card:hover {
  transform: translateY(-2px);
  border-color: #cfdee4;
  box-shadow:
    0 14px 30px
    rgba(30, 62, 77, .06);
}

.admin-center-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.admin-center-card-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #287eaa;
  background: #e5f2f8;
}

.admin-center-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
}

.admin-center-state > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-center-state.active {
  color: #218b52;
  background: #eaf7ed;
}

.admin-center-state.active > span {
  background: #218b52;
}

.admin-center-state.idle {
  color: #8899a0;
  background: #f0f3f4;
}

.admin-center-state.idle > span {
  background: #9ba9ae;
}

.admin-center-card h3 {
  margin: 13px 0 5px;
  color: #345567;
  font-family: var(--font-heading);
  font-size: 17px;
}

.admin-center-location {
  min-height: 25px;
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin: 0;
  color: #84969e;
  font-size: 7px;
  line-height: 1.5;
}

.admin-center-location svg {
  flex: 0 0 auto;
  margin-top: 1px;
  color: #89a2ad;
}


/* =========================================================
   CAPACITY
========================================================= */

.admin-center-capacity {
  margin-top: 14px;
  padding: 11px;
  border: 1px solid #e2e9ec;
  border-radius: 10px;
  background: #fafcfd;
}

.admin-center-capacity-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}

.admin-center-capacity-heading span {
  color: #82949c;
  font-size: 6px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .05em;
}

.admin-center-capacity-heading strong {
  color: #486575;
  font-size: 8px;
}

.admin-center-progress {
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: #e7eef0;
}

.admin-center-progress > div {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #5fa778,
      #86bd91
    );
  transition: width .3s ease;
}

.admin-center-utilization {
  display: block;
  margin-top: 5px;
  color: #8c9ba2;
  font-size: 6px;
}


/* =========================================================
   CARD STATS
========================================================= */

.admin-center-card-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 11px;
}

.admin-center-card-stats > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  border-radius: 8px;
  background: #f7fafb;
}

.admin-center-card-stats span {
  overflow: hidden;
  color: #909fa5;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-card-stats strong {
  overflow: hidden;
  color: #486676;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-view-button {
  width: 100%;
  min-height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #587483;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-center-view-button:hover {
  color: #287eaa;
  border-color: #b9d1db;
  background: #f7fbfc;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-centers-empty {
  grid-column: 1 / -1;
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  color: #99a8ae;
  background: #ffffff;
  text-align: center;
}

.admin-centers-empty strong {
  color: #5e7784;
  font-size: 10px;
}

.admin-centers-empty span {
  color: #8b9ba2;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-center-loading-grid {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.admin-center-loading-card {
  min-height: 280px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border: 1px solid #e0e8eb;
  border-radius: 16px;
  background: #ffffff;
}

.admin-center-loading-card > span:first-child {
  width: 42px;
  height: 42px;
  border-radius: 11px;
  background: #edf2f4;
}

.admin-center-loading-card > div {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.admin-center-loading-card > div span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCenterSkeleton 1.2s infinite;
}

.admin-center-loading-card > div span:nth-child(1) {
  width: 65%;
}

.admin-center-loading-card > div span:nth-child(2) {
  width: 90%;
}

.admin-center-loading-card > div span:nth-child(3) {
  width: 45%;
}

.admin-center-loading-card > span:not(:first-child) {
  height: 7px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCenterSkeleton 1.2s infinite;
}

@keyframes adminCenterSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-centers-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
  padding: 3px 2px 10px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   DRAWER
========================================================= */

.admin-center-drawer-overlay {
  position: fixed;
  z-index: 100;
  inset: 0;
  background: rgba(24, 51, 64, .28);
}

.admin-center-drawer {
  position: fixed;
  z-index: 110;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(500px, 95vw);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #ffffff;
  box-shadow:
    -18px 0 50px
    rgba(27, 54, 68, .15);
  animation:
    adminCenterDrawerIn .2s ease;
}

@keyframes adminCenterDrawerIn {

  from {
    transform: translateX(20px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }

}

.admin-center-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 21px;
  border-bottom: 1px solid #e7edef;
}

.admin-center-drawer-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-center-drawer-header h2 {
  margin: 0;
  color: #294c5f;
  font-family: var(--font-heading);
  font-size: 24px;
}

.admin-center-drawer-header > div > span:last-child {
  color: #96a4aa;
  font-size: 6px;
}

.admin-center-drawer-close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce5e9;
  border-radius: 9px;
  color: #6d8390;
  background: #ffffff;
  cursor: pointer;
}

.admin-center-drawer-close:hover {
  color: #b05046;
  border-color: #dfc2bd;
}


/* =========================================================
   DRAWER SUMMARY
========================================================= */

.admin-center-drawer-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 21px;
  border-bottom: 1px solid #edf1f3;
  background: #fafcfd;
}

.admin-center-drawer-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #287eaa;
  background: #e5f2f8;
}

.admin-center-drawer-summary > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-center-drawer-summary strong {
  color: #3c5a6b;
  font-size: 10px;
}

.admin-center-drawer-summary span {
  color: #85979f;
  font-size: 7px;
  line-height: 1.45;
}


/* =========================================================
   DRAWER DETAILS
========================================================= */

.admin-center-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  margin: 15px 21px 0;
  overflow: hidden;
  border: 1px solid #e4ebee;
  border-radius: 11px;
  background: #e4ebee;
}

.admin-center-detail-grid > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  background: #ffffff;
}

.admin-center-detail-grid span {
  color: #8d9ca3;
  font-size: 6px;
}

.admin-center-detail-grid strong {
  color: #476575;
  font-size: 8px;
}


/* =========================================================
   DRAWER SECTIONS
========================================================= */

.admin-center-drawer-section {
  margin: 17px 21px 0;
  padding-bottom: 16px;
  border-bottom: 1px solid #edf1f3;
}

.admin-center-drawer-section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
  color: #287eaa;
}

.admin-center-drawer-section-title h3 {
  margin: 0;
  color: #466373;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-center-no-data {
  padding: 10px;
  border-radius: 8px;
  color: #909fa5;
  background: #f7fafb;
  font-size: 7px;
}

.admin-center-crop-row {
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #edf1f3;
}

.admin-center-crop-row:first-of-type {
  border-top: 0;
}

.admin-center-crop-row span {
  color: #718792;
  font-size: 7px;
}

.admin-center-crop-row strong {
  min-width: 24px;
  text-align: right;
  color: #466576;
  font-family: var(--font-heading);
  font-size: 9px;
}

.admin-center-booking-row {
  min-height: 49px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid #edf1f3;
}

.admin-center-booking-row:first-of-type {
  border-top: 0;
}

.admin-center-booking-row > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-center-booking-row > div:last-child {
  align-items: flex-end;
}

.admin-center-booking-row strong {
  overflow: hidden;
  color: #516d7b;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-booking-row span {
  color: #8c9aa1;
  font-size: 6px;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-center-drawer-footer {
  margin-top: auto;
  min-height: 63px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 11px 21px;
  border-top: 1px solid #e7edef;
  background: #ffffff;
}

.admin-center-drawer-footer button {
  min-height: 35px;
  padding: 0 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #617985;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-center-drawer-footer button:hover {
  color: #287eaa;
  border-color: #b9d0da;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

  .admin-centers-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-center-loading-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


@media (max-width: 850px) {

  .admin-centers-hero {
    flex-direction: column;
  }

  .admin-centers-actions {
    width: 100%;
  }

  .admin-centers-live,
  .admin-centers-refresh {
    flex: 1;
  }

  .admin-center-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-centers-grid {
    grid-template-columns:
      1fr;
  }

  .admin-center-loading-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 650px) {

  .admin-centers-filter-panel {
    flex-wrap: wrap;
  }

  .admin-centers-search {
    flex-basis: 100%;
  }

  .admin-centers-filter {
    flex: 1;
  }

  .admin-centers-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 500px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-center-card {
    padding: 14px;
  }

  .admin-center-detail-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 390px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-centers-filter {
    flex-basis: 100%;
  }

  .admin-centers-clear {
    width: 100%;
  }

}
/* =========================================================
   ADD / EDIT CENTER MODAL
========================================================= */

.admin-center-form-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 24px;

  background:
    rgba(26, 49, 61, .34);

  backdrop-filter:
    blur(4px);
}


/* =========================================================
   MODAL
========================================================= */

.admin-center-form-modal {
  width: min(
    780px,
    96vw
  );

  max-height: 92vh;

  overflow:
    hidden auto;

  border:
    1px solid
    #d8e3e7;

  border-radius:
    18px;

  background:
    #ffffff;

  box-shadow:
    0 28px 80px
    rgba(
      27,
      55,
      68,
      .20
    );

  animation:
    adminCenterModalIn
    .2s ease;
}

@keyframes adminCenterModalIn {

  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(.985);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}


/* =========================================================
   HEADER
========================================================= */

.admin-center-form-header {
  position: sticky;
  top: 0;
  z-index: 2;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 18px;

  padding:
    21px
    22px
    18px;

  border-bottom:
    1px solid
    #e5ecef;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );
}

.admin-center-form-header > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 5px;
}

.admin-center-form-header h2 {
  margin: 0;

  color:
    #294d60;

  font-family:
    var(--font-heading);

  font-size:
    24px;

  line-height:
    1.1;

  letter-spacing:
    -.025em;
}

.admin-center-form-header p {
  max-width: 590px;

  margin: 0;

  color:
    #84969f;

  font-size:
    7px;

  line-height:
    1.6;
}

.admin-center-form-close {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dce5e9;

  border-radius:
    9px;

  color:
    #6e8490;

  background:
    #ffffff;

  cursor:
    pointer;

  transition:
    .15s ease;
}

.admin-center-form-close:hover {
  color:
    #ad5147;

  border-color:
    #dfc7c2;

  background:
    #fff8f7;
}


/* =========================================================
   FORM
========================================================= */

.admin-center-form {
  padding:
    20px
    22px
    23px;
}

.admin-center-form-section {
  margin-bottom:
    20px;

  padding-bottom:
    20px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-center-form-section:last-of-type {
  margin-bottom: 0;

  padding-bottom: 2px;

  border-bottom: 0;
}


/* =========================================================
   SECTION TITLE
========================================================= */

.admin-center-form-section-title {
  display: flex;
  align-items: center;

  gap: 7px;

  margin-bottom:
    11px;

  color:
    #287eaa;
}

.admin-center-form-section-title svg {
  width: 16px;
  height: 16px;
}

.admin-center-form-section-title h3 {
  margin: 0;

  color:
    #405f70;

  font-family:
    var(--font-heading);

  font-size:
    14px;

  letter-spacing:
    -.01em;
}


/* =========================================================
   GRID
========================================================= */

.admin-center-form-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 10px;
}

.admin-center-form-grid.three {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}


/* =========================================================
   FIELD
========================================================= */

.admin-center-form-field {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 5px;
}

.admin-center-form-field.wide {
  grid-column:
    1 / -1;
}

.admin-center-form-field > span {
  color:
    #7d919b;

  font-size:
    6px;

  font-weight:
    900;

  letter-spacing:
    .05em;

  text-transform:
    uppercase;
}

.admin-center-form-field > span b {
  margin-left:
    2px;

  color:
    #bd5b51;
}


/* =========================================================
   INPUTS
========================================================= */

.admin-center-form-field input {
  width: 100%;

  min-height: 42px;

  padding:
    0
    11px;

  border:
    1px solid
    #d5e1e5;

  border-radius:
    8px;

  outline:
    none;

  color:
    #466473;

  background:
    #ffffff;

  font-family:
    inherit;

  font-size:
    8px;

  transition:
    border-color .15s ease,
    box-shadow .15s ease,
    background .15s ease;
}

.admin-center-form-field input:hover:not(:disabled) {
  border-color:
    #c4d4da;
}

.admin-center-form-field input:focus {
  border-color:
    #8eb7c7;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .055
    );
}

.admin-center-form-field input:disabled {
  color:
    #97a5aa;

  background:
    #f3f6f7;

  cursor:
    not-allowed;
}

.admin-center-form-field input::placeholder {
  color:
    #acb8bd;
}


/* =========================================================
   NUMBER INPUT
========================================================= */

.admin-center-form-field input[type="number"] {
  appearance:
    textfield;
}

.admin-center-form-field input[type="number"]::-webkit-inner-spin-button,
.admin-center-form-field input[type="number"]::-webkit-outer-spin-button {
  opacity:
    .55;
}


/* =========================================================
   TIME INPUT
========================================================= */

.admin-center-form-field input[type="time"] {
  cursor:
    pointer;
}


/* =========================================================
   ACTIVE TOGGLE
========================================================= */

.admin-center-active-toggle {
  position: relative;

  display: flex;
  align-items: center;

  gap: 11px;

  margin-top:
    13px;

  padding:
    12px;

  border:
    1px solid
    #dce6ea;

  border-radius:
    10px;

  background:
    #fafcfd;

  cursor:
    pointer;

  transition:
    border-color .15s ease,
    background .15s ease;
}

.admin-center-active-toggle:hover {
  border-color:
    #c4d8df;

  background:
    #f7fbfc;
}

.admin-center-active-toggle input {
  position:
    absolute;

  opacity:
    0;

  pointer-events:
    none;
}

.admin-center-toggle-track {
  width: 40px;
  height: 22px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;

  padding:
    3px;

  border-radius:
    999px;

  background:
    #c8d3d8;

  transition:
    background .17s ease;
}

.admin-center-toggle-track > span {
  width: 16px;
  height: 16px;

  border-radius:
    50%;

  background:
    #ffffff;

  box-shadow:
    0 1px 4px
    rgba(
      0,
      0,
      0,
      .14
    );

  transition:
    transform .17s ease;
}

.admin-center-active-toggle input:checked
+ .admin-center-toggle-track {
  background:
    #218b52;
}

.admin-center-active-toggle input:checked
+ .admin-center-toggle-track > span {
  transform:
    translateX(18px);
}

.admin-center-active-toggle > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-center-active-toggle strong {
  color:
    #4a6675;

  font-size:
    8px;
}

.admin-center-active-toggle > div > span {
  color:
    #87989f;

  font-size:
    6px;

  line-height:
    1.45;
}


/* =========================================================
   FORM ACTIONS
========================================================= */

.admin-center-form-actions {
  position: sticky;
  bottom: 0;

  display: flex;
  justify-content: flex-end;

  gap: 8px;

  margin:
    20px
    -22px
    -23px;

  padding:
    13px
    22px;

  border-top:
    1px solid
    #e4ebee;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );

  box-shadow:
    0 -5px 18px
    rgba(
      35,
      62,
      75,
      .025
    );
}

.admin-center-form-cancel,
.admin-center-form-save {
  min-height:
    41px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    13px;

  border-radius:
    8px;

  cursor:
    pointer;

  font-size:
    7px;

  font-weight:
    900;

  transition:
    .15s ease;
}

.admin-center-form-cancel {
  border:
    1px solid
    #d8e3e7;

  color:
    #657c88;

  background:
    #ffffff;
}

.admin-center-form-cancel:hover:not(:disabled) {
  color:
    #486a79;

  border-color:
    #bdcfd6;

  background:
    #fafcfd;
}

.admin-center-form-save {
  min-width:
    135px;

  border:
    0;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #218b52,
      #2b9b60
    );

  box-shadow:
    0 7px 17px
