/* =========================================================
   ADMIN SETTINGS
========================================================= */

.admin-settings-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-settings-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-settings-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-settings-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-settings-hero-status {
  display: flex;
  align-items: center;
}

.admin-settings-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid #cfe1e7;
  border-radius: 999px;
  color: #287eaa;
  background: #edf7fa;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-settings-error,
.admin-settings-success {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
}

.admin-settings-error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-settings-success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-settings-error > svg,
.admin-settings-success > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-settings-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-error strong {
  font-size: 8px;
}

.admin-settings-error span,
.admin-settings-success span {
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-error span {
  color: #8e7772;
}

.admin-settings-success span {
  color: #668977;
}

.admin-settings-error button,
.admin-settings-success button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.admin-settings-error button {
  color: #ad554a;
}

.admin-settings-success button {
  color: #40815e;
}


/* =========================================================
   SYSTEM STATUS
========================================================= */

.admin-settings-status-card {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding: 15px;
  border: 1px solid #dce6ea;
  border-radius: 15px;
  background: #ffffff;
  box-shadow:
    0 8px 24px
    rgba(30, 62, 77, .035);
}

.admin-settings-status-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #287eaa;
  background: #e5f2f8;
}

.admin-settings-status-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-settings-status-copy h3 {
  margin: 0;
  color: #36576a;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-settings-status-copy p {
  max-width: 760px;
  margin: 0;
  color: #8798a0;
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-status-badge {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
}

.admin-settings-status-badge > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-settings-status-badge.active {
  color: #218b52;
  background: #eaf7ed;
}

.admin-settings-status-badge.active > span {
  background: #218b52;
}

.admin-settings-status-badge.paused {
  color: #bb751c;
  background: #fff1d4;
}

.admin-settings-status-badge.paused > span {
  background: #bb751c;
}

.admin-settings-status-badge.warning {
  color: #b8574c;
  background: #fff0ed;
}

.admin-settings-status-badge.warning > span {
  background: #b8574c;
}


/* =========================================================
   MAIN GRID
========================================================= */

.admin-settings-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}


/* =========================================================
   SECTION
========================================================= */

.admin-settings-section {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 8px 25px
    rgba(30, 62, 77, .035);
}

.admin-settings-section-header {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 17px 18px 13px;
  border-bottom: 1px solid #edf1f3;
}

.admin-settings-section-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-settings-section-icon.blue {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-settings-section-icon.green {
  color: #218b52;
  background: #e4f4e8;
}

.admin-settings-section-icon.gold {
  color: #be811a;
  background: #fff0ce;
}

.admin-settings-section-icon.purple {
  color: #8064a9;
  background: #eee9f7;
}

.admin-settings-section-header > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-section-header > div:last-child > span {
  color: #96a4aa;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.admin-settings-section-header h3 {
  margin: 0;
  color: #3c5c6e;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-settings-section-header p {
  margin: 1px 0 0;
  color: #8999a1;
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-section-body {
  padding: 1px 18px 16px;
}


/* =========================================================
   TOGGLE
========================================================= */

.admin-setting-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 0;
  cursor: pointer;
}

.admin-setting-toggle.disabled {
  opacity: .5;
  cursor: not-allowed;
}

.admin-setting-toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-setting-toggle-track {
  width: 39px;
  height: 21px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  padding: 3px;
  border-radius: 99px;
  background: #c9d4d9;
  transition: background .17s ease;
}

.admin-setting-toggle-track > span {
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow:
    0 1px 4px
    rgba(0, 0, 0, .14);
  transition: transform .17s ease;
}

.admin-setting-toggle input:checked
+ .admin-setting-toggle-track {
  background: #218b52;
}

.admin-setting-toggle input:checked
+ .admin-setting-toggle-track > span {
  transform: translateX(18px);
}

.admin-setting-toggle > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-setting-toggle strong {
  color: #4a6676;
  font-size: 8px;
}

.admin-setting-toggle > div > span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   DIVIDER
========================================================= */

.admin-settings-divider {
  height: 1px;
  margin: 1px 0;
  background: #edf1f3;
}


/* =========================================================
   NUMBER ROW
========================================================= */

.admin-setting-number-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 0;
}

.admin-setting-number-row > div:first-child {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-setting-number-row strong {
  color: #4a6675;
  font-size: 8px;
}

.admin-setting-number-row > div:first-child span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-setting-number {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  overflow: hidden;
  min-height: 36px;
  border: 1px solid #d8e3e7;
  border-radius: 8px;
  background: #ffffff;
}

.admin-setting-number:focus-within {
  border-color: #8fb7c6;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .05);
}

.admin-setting-number input {
  width: 65px;
  height: 34px;
  padding: 0 7px;
  border: 0;
  outline: 0;
  color: #4b6877;
  background: transparent;
  text-align: right;
  font-family: inherit;
  font-size: 8px;
}

.admin-setting-number input[type="number"] {
  appearance: textfield;
}

.admin-setting-number input::-webkit-inner-spin-button,
.admin-setting-number input::-webkit-outer-spin-button {
  opacity: .45;
}

.admin-setting-number > span {
  padding: 0 8px 0 3px;
  color: #96a4aa;
  font-size: 6px;
  font-weight: 900;
}


/* =========================================================
   INFO CARD
========================================================= */

.admin-settings-info-card {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid #e2e9ec;
  border-radius: 9px;
  background: #fafcfd;
}

.admin-settings-info-icon {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #218b52;
  background: #e5f5e9;
}

.admin-settings-info-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-info-card strong {
  color: #4a6676;
  font-size: 7px;
}

.admin-settings-info-card span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   LANGUAGE
========================================================= */

.admin-settings-language-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 11px 0;
}

.admin-settings-language-row > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-language-row strong {
  color: #4a6675;
  font-size: 8px;
}

.admin-settings-language-row span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-settings-language-row select {
  min-width: 105px;
  height: 36px;
  padding: 0 9px;
  border: 1px solid #d8e3e7;
  border-radius: 8px;
  outline: 0;
  color: #587381;
  background: #ffffff;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-settings-language-row select:focus {
  border-color: #8fb7c6;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .05);
}


/* =========================================================
   WARNING
========================================================= */

.admin-settings-warning-card {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 10px;
  border: 1px solid #f0dfb9;
  border-radius: 9px;
  color: #a87a25;
  background: #fffaf0;
}

.admin-settings-warning-card > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-settings-warning-card > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-warning-card strong {
  color: #92691e;
  font-size: 7px;
}

.admin-settings-warning-card span {
  color: #9a855f;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   SAVE BAR
========================================================= */

.admin-settings-save-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 14px;
  padding: 13px 15px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 8px 24px
    rgba(30, 62, 77, .035);
}

.admin-settings-save-bar.has-changes {
  border-color: #c8dce4;
  box-shadow:
    0 8px 25px
    rgba(40, 126, 170, .055);
}

.admin-settings-save-bar > div:first-child {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

.admin-settings-save-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #218b52;
  background: #eaf7ed;
}

.admin-settings-save-bar.has-changes
.admin-settings-save-icon {
  color: #287eaa;
  background: #e8f4f8;
}

.admin-settings-save-bar > div:first-child > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-save-bar strong {
  color: #486575;
  font-size: 8px;
}

.admin-settings-save-bar span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-settings-save-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.admin-settings-discard,
.admin-settings-save,
.admin-settings-reset {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-settings-discard {
  border: 1px solid #dbe5e9;
  color: #697f8a;
  background: #ffffff;
}

.admin-settings-save {
  min-width: 105px;
  border: 0;
  color: #ffffff;
  background: #218b52;
}

.admin-settings-reset {
  border: 1px solid #e0d4d1;
  color: #a1594f;
  background: #fff9f8;
}

.admin-settings-discard:hover:not(:disabled) {
  border-color: #becfd6;
  background: #fafcfd;
}

.admin-settings-save:hover:not(:disabled) {
  background: #197342;
}

.admin-settings-reset:hover:not(:disabled) {
  border-color: #d7b9b3;
  background: #fff4f2;
}

.admin-settings-discard:disabled,
.admin-settings-save:disabled,
.admin-settings-reset:disabled {
  opacity: .5;
  cursor: not-allowed;
}


/* =========================================================
   LOADING
========================================================= */

.admin-settings-loading-status {
  height: 75px;
  margin-bottom: 14px;
  border: 1px solid #e0e8eb;
  border-radius: 15px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminSettingsSkeleton 1.2s infinite;
}

.admin-settings-loading-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.admin-settings-loading-card {
  min-height: 290px;
  padding: 17px;
  border: 1px solid #e0e8eb;
  border-radius: 16px;
  background: #ffffff;
}

.admin-settings-loading-card span {
  display: block;
  height: 8px;
  margin-bottom: 15px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminSettingsSkeleton 1.2s infinite;
}

.admin-settings-loading-card span:nth-child(1) {
  width: 30%;
  height: 28px;
  border-radius: 8px;
}

.admin-settings-loading-card span:nth-child(2) {
  width: 45%;
}

.admin-settings-loading-card span:nth-child(3) {
  width: 85%;
}

.admin-settings-loading-card span:nth-child(4) {
  width: 70%;
}

.admin-settings-loading-card span:nth-child(5) {
  width: 55%;
}

@keyframes adminSettingsSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .admin-settings-grid {
    grid-template-columns: 1fr;
  }

  .admin-settings-loading-grid {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 800px) {

  .admin-settings-hero {
    flex-direction: column;
  }

  .admin-settings-hero-status {
    width: 100%;
  }

  .admin-settings-live {
    width: 100%;
  }

  .admin-settings-status-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .admin-settings-status-badge {
    margin-left: 52px;
  }

}


@media (max-width: 600px) {

  .admin-settings-status-card {
    flex-direction: column;
  }

  .admin-settings-status-badge {
    margin-left: 0;
  }

  .admin-settings-save-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-save-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .admin-settings-discard,
  .admin-settings-save,
  .admin-settings-reset {
    flex: 1;
  }

}


@media (max-width: 480px) {

  .admin-settings-form-grid,
  .admin-settings-grid {
    grid-template-columns: 1fr;
  }

  .admin-setting-number-row,
  .admin-settings-language-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-setting-number,
  .admin-settings-language-row select {
    width: 100%;
  }

  .admin-setting-number input {
    flex: 1;
    width: auto;
  }

  .admin-settings-save-actions {
    flex-direction: column;
  }

  .admin-settings-discard,
  .admin-settings-save,
  .admin-settings-reset {
    width: 100%;
  }

}
/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-dashboard-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-dashboard-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-dashboard-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-dashboard-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-dashboard-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-dashboard-live > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #218b52;
  box-shadow:
    0 0 0 4px
    rgba(33, 139, 82, .08);
}

.admin-dashboard-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-dashboard-refresh:hover:not(:disabled) {
  color: #287eaa;
  border-color: #bad0da;
}

.admin-dashboard-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-dashboard-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-dashboard-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-dashboard-error > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-error strong {
  font-size: 8px;
}

.admin-dashboard-error span {
  color: #8e7772;
  font-size: 7px;
}


/* =========================================================
   KPI GRID
========================================================= */

.admin-dashboard-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));
  gap: 9px;
  margin-bottom: 14px;
}

.admin-dashboard-kpi {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 13px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-dashboard-kpi-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-dashboard-kpi.blue
.admin-dashboard-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-dashboard-kpi.purple
.admin-dashboard-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-dashboard-kpi.gold
.admin-dashboard-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-dashboard-kpi.green
.admin-dashboard-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-dashboard-kpi.orange
.admin-dashboard-kpi-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-dashboard-kpi.teal
.admin-dashboard-kpi-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-dashboard-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-kpi strong small {
  color: #8a999f;
  font-size: 7px;
}

.admin-dashboard-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   ALERTS
========================================================= */

.admin-dashboard-alerts-panel,
.admin-dashboard-panel {
  min-width: 0;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
}

.admin-dashboard-alerts-panel {
  overflow: hidden;
  margin-bottom: 14px;
}

.admin-dashboard-panel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px 13px;
  border-bottom: 1px solid #edf1f3;
}

.admin-dashboard-panel-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-dashboard-panel-header h3 {
  margin: 0;
  color: #3c5b6c;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-dashboard-alert-count {
  flex: 0 0 auto;
  padding: 5px 7px;
  border-radius: 999px;
  color: #8c9aa1;
  background: #f3f6f7;
  font-size: 5px;
  font-weight: 900;
}

.admin-dashboard-alert-list {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

.admin-dashboard-alert-row {
  min-width: 0;
  min-height: 68px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 14px;
  gap: 8px;
  align-items: center;
  padding: 10px 14px;
  border-right: 1px solid #edf1f3;
  text-decoration: none;
}

.admin-dashboard-alert-row:last-child {
  border-right: 0;
}

.admin-dashboard-alert-row:hover {
  background: #fbfcfd;
}

.admin-dashboard-alert-icon {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
}

.admin-dashboard-alert-row.orange
.admin-dashboard-alert-icon {
  color: #d1772b;
  background: #fff0e4;
}

.admin-dashboard-alert-row.gold
.admin-dashboard-alert-icon {
  color: #bd821a;
  background: #fff2d5;
}

.admin-dashboard-alert-row.red
.admin-dashboard-alert-icon {
  color: #b3554b;
  background: #fff0ed;
}

.admin-dashboard-alert-row.purple
.admin-dashboard-alert-icon {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-dashboard-alert-row > div:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-alert-row strong {
  overflow: hidden;
  color: #4a6675;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-alert-row span {
  color: #8b9aa1;
  font-size: 6px;
  line-height: 1.4;
}

.admin-dashboard-alert-row > svg:last-child {
  color: #a0adb2;
}

.admin-dashboard-no-alerts {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  color: #6f8b79;
  background: #fbfdfb;
  font-size: 7px;
}


/* =========================================================
   MAIN GRID
========================================================= */

.admin-dashboard-main-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 14px;
}


/* =========================================================
   PANEL LINK
========================================================= */

.admin-dashboard-panel-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #67818e;
  text-decoration: none;
  font-size: 6px;
  font-weight: 900;
}

.admin-dashboard-panel-link:hover {
  color: #287eaa;
}


/* =========================================================
   CENTER LOAD
========================================================= */

.admin-dashboard-center-list {
  padding: 2px 18px 14px;
}

.admin-dashboard-center-row {
  min-height: 53px;
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    1.35fr;
  gap: 12px;
  align-items: center;
  border-bottom: 1px solid #edf1f3;
}

.admin-dashboard-center-row:last-child {
  border-bottom: 0;
}

.admin-dashboard-center-name {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-dashboard-center-name > div {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #287eaa;
  background: #e7f3f8;
}

.admin-dashboard-center-name span {
  overflow: hidden;
  color: #526e7c;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-center-load {
  min-width: 0;
}

.admin-dashboard-center-load > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 7px;
  margin-bottom: 5px;
}

.admin-dashboard-center-load span {
  color: #87979e;
  font-size: 6px;
}

.admin-dashboard-center-load strong {
  color: #4a6675;
  font-size: 6px;
}

.admin-dashboard-mini-progress {
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: #e8eef0;
}

.admin-dashboard-mini-progress > div {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #5fa778,
      #87c192
    );
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-dashboard-workflow {
  display: grid;
  grid-template-columns:
    repeat(3, 1fr);
  gap: 1px;
  margin: 0 18px 18px;
  overflow: hidden;
  border: 1px solid #e6ecef;
  border-radius: 11px;
  background: #e6ecef;
}

.admin-dashboard-workflow-step {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  background: #ffffff;
}

.admin-dashboard-workflow-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.admin-dashboard-workflow-step span {
  color: #88999f;
  font-size: 5px;
  text-align: center;
}

.admin-dashboard-workflow-step strong {
  color: #486575;
  font-family: var(--font-heading);
  font-size: 12px;
}

.admin-dashboard-workflow-step.blue
.admin-dashboard-workflow-dot {
  background: #287eaa;
}

.admin-dashboard-workflow-step.purple
.admin-dashboard-workflow-dot {
  background: #8064a9;
}

.admin-dashboard-workflow-step.gold
.admin-dashboard-workflow-dot {
  background: #c3871c;
}

.admin-dashboard-workflow-step.green
.admin-dashboard-workflow-dot {
  background: #218b52;
}

.admin-dashboard-workflow-step.orange
.admin-dashboard-workflow-dot {
  background: #d1772b;
}

.admin-dashboard-workflow-step.teal
.admin-dashboard-workflow-dot {
  background: #288e91;
}


/* =========================================================
   MONEY
========================================================= */

.admin-dashboard-money {
  display: grid;
  grid-template-columns:
    repeat(3, 1fr);
  gap: 7px;
  padding: 0 18px 18px;
}

.admin-dashboard-money-card {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 10px;
  border-radius: 10px;
}

.admin-dashboard-money-card span {
  color: #87979e;
  font-size: 6px;
}

.admin-dashboard-money-card strong {
  overflow: hidden;
  color: #486575;
  font-family: var(--font-heading);
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-money-card.paid {
  background: #edf8f0;
}

.admin-dashboard-money-card.pending {
  background: #fff6df;
}

.admin-dashboard-money-card.total {
  background: #edf6f9;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.admin-dashboard-quick-actions {
  display: grid;
  grid-template-columns:
    repeat(2, 1fr);
  gap: 7px;
  padding: 0 18px 18px;
}

.admin-dashboard-quick-action {
  min-width: 0;
  min-height: 66px;
  display: grid;
  grid-template-columns:
    33px minmax(0, 1fr) 13px;
  gap: 8px;
  align-items: center;
  padding: 9px;
  border: 1px solid #e1e8eb;
  border-radius: 10px;
  color: inherit;
  text-decoration: none;
  background: #fbfcfd;
  transition:
    border-color .14s ease,
    background .14s ease;
}

.admin-dashboard-quick-action:hover {
  border-color: #c4d7df;
  background: #f7fbfc;
}

.admin-dashboard-quick-icon {
  width: 33px;
  height: 33px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #287eaa;
  background: #e7f3f8;
}

.admin-dashboard-quick-action > div:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-quick-action strong {
  overflow: hidden;
  color: #526d7b;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-quick-action span {
  color: #8a9aa1;
  font-size: 5px;
  line-height: 1.4;
}

.admin-dashboard-quick-action > svg {
  color: #a1adb2;
}


/* =========================================================
   RECENT BOOKINGS
========================================================= */

.admin-dashboard-recent-panel {
  overflow: hidden;
}

.admin-dashboard-recent-list {
  width: 100%;
  overflow-x: auto;
}

.admin-dashboard-recent-row {
  min-width: 850px;
  min-height: 64px;
  display: grid;
  grid-template-columns:
    65px
    1.35fr
    1fr
    .9fr
    .9fr;
  gap: 10px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-dashboard-recent-row:last-child {
  border-bottom: 0;
}

.admin-dashboard-recent-row:hover {
  background: #fbfcfd;
}

.admin-dashboard-recent-token {
  width: fit-content;
  padding: 5px 7px;
  border-radius: 7px;
  color: #287eaa;
  background: #e8f3f8;
  font-size: 6px;
  font-weight: 900;
}

.admin-dashboard-recent-farmer,
.admin-dashboard-recent-row > div:nth-child(4) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-recent-farmer strong,
.admin-dashboard-recent-row > div:nth-child(4) strong {
  overflow: hidden;
  color: #506b79;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-dashboard-recent-farmer span,
.admin-dashboard-recent-row > div:nth-child(4) span {
  color: #8b9ba2;
  font-size: 6px;
}

.admin-dashboard-recent-crop {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #587482;
}

.admin-dashboard-recent-crop svg {
  color: #218b52;
}

.admin-dashboard-recent-crop span {
  font-size: 7px;
}

.admin-dashboard-status {
  width: fit-content;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
  white-space: nowrap;
}

.admin-dashboard-status.blue {
  color: #287eaa;
  background: #e7f3f8;
}

.admin-dashboard-status.green {
  color: #218b52;
  background: #eaf7ed;
}

.admin-dashboard-status.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-dashboard-status.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-dashboard-status.gold {
  color: #be811a;
  background: #fff2d5;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-dashboard-empty {
  min-height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 20px;
  color: #9aa8ad;
  text-align: center;
}

.admin-dashboard-empty span {
  color: #8b9aa1;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-dashboard-loading {
  min-width: 850px;
}

.admin-dashboard-skeleton {
  min-height: 64px;
  display: grid;
  grid-template-columns:
    .7fr
    1.4fr
    1fr
    1fr;
  gap: 10px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-dashboard-skeleton span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminDashboardSkeleton 1.2s infinite;
}

@keyframes adminDashboardSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-dashboard-footer {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 10px;
  color: #8d9ca2;
  font-size: 6px;
}

.admin-dashboard-footer svg {
  color: #287eaa;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1300px) {

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-dashboard-main-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-alert-list {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-dashboard-alert-row:nth-child(2) {
    border-right: 0;
  }

}


@media (max-width: 750px) {

  .admin-dashboard-hero {
    flex-direction: column;
  }

  .admin-dashboard-actions {
    width: 100%;
  }

  .admin-dashboard-live,
  .admin-dashboard-refresh {
    flex: 1;
  }

  .admin-dashboard-alert-list {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-alert-row {
    border-right: 0;
    border-bottom: 1px solid #edf1f3;
  }

  .admin-dashboard-alert-row:last-child {
    border-bottom: 0;
  }

}


@media (max-width: 600px) {

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-dashboard-workflow {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-dashboard-money {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-quick-actions {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 430px) {

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-workflow {
    grid-template-columns:
      1fr;
  }

}
/* =========================================================
   ADMIN PAYMENTS
========================================================= */

.admin-payments-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-payments-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-payments-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-payments-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-payments-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-payments-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-payments-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-payments-refresh:hover:not(:disabled) {
  color: #287eaa;
  border-color: #bad0da;
}

.admin-payments-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-payments-error,
.admin-payments-success {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
}

.admin-payments-error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-payments-success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-payments-error > svg,
.admin-payments-success > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-payments-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payments-error strong {
  font-size: 8px;
}

.admin-payments-error span,
.admin-payments-success span {
  font-size: 7px;
  line-height: 1.5;
}

.admin-payments-error span {
  color: #8e7772;
}

.admin-payments-success span {
  color: #658877;
}

.admin-payments-error button,
.admin-payments-success button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.admin-payments-error button {
  color: #ad554a;
}

.admin-payments-success button {
  color: #418160;
}


/* =========================================================
   KPI
========================================================= */

.admin-payment-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.admin-payment-kpi {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px;
  border: 1px solid #dce6ea;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-payment-kpi-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-payment-kpi.blue .admin-payment-kpi-icon {
  color: #287eaa;
  background: #e5f2f8;
}

.admin-payment-kpi.gold .admin-payment-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-payment-kpi.green .admin-payment-kpi-icon {
  color: #218b52;
  background: #e4f4e8;
}

.admin-payment-kpi.orange .admin-payment-kpi-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-payment-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-payment-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-payments-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dce6ea;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-payments-search {
  flex: 1;
  min-width: 210px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  color: #84969e;
  background: #fafcfd;
}

.admin-payments-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-payments-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-payments-search input::placeholder {
  color: #adb9bf;
}

.admin-payments-filter {
  height: 36px;
  display: flex;
  align-items: center;
  padding: 0 9px;
  border: 1px solid #dce5e9;
  border-radius: 8px;
  background: #fafcfd;
}

.admin-payments-filter select {
  min-width: 105px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}


/* =========================================================
   TABLE
========================================================= */

.admin-payments-table-panel {
  overflow: hidden;
  border: 1px solid #dce6ea;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
}

.admin-payments-table-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 17px 18px 14px;
}

.admin-payments-table-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-payments-table-header h3 {
  margin: 0;
  color: #3c5b6c;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-payments-table-header > span {
  color: #95a3a9;
  font-size: 6px;
}

.admin-payments-table {
  width: 100%;
  overflow-x: auto;
}

.admin-payments-table-head,
.admin-payment-row {
  min-width: 1050px;
  display: grid;
  grid-template-columns:
    1.15fr
    1.25fr
    .9fr
    .8fr
    1fr
    1fr;
  column-gap: 11px;
  align-items: center;
  padding: 0 18px;
}

.admin-payments-table-head {
  min-height: 34px;
  border-top: 1px solid #edf1f3;
  border-bottom: 1px solid #e7edef;
  color: #99a7ad;
  background: #fafcfd;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-payment-row {
  min-height: 78px;
  border-bottom: 1px solid #edf1f3;
  transition: background .13s ease;
}

.admin-payment-row:hover {
  background: #fbfcfd;
}


/* =========================================================
   BOOKING
========================================================= */

.admin-payment-booking {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-payment-token {
  min-width: 43px;
  min-height: 27px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 6px;
  border-radius: 7px;
  color: #287eaa;
  background: #e8f3f8;
  font-size: 6px;
  font-weight: 900;
}

.admin-payment-booking > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-booking strong {
  overflow: hidden;
  color: #506b79;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-payment-booking span {
  color: #8b9aa1;
  font-size: 6px;
}


/* =========================================================
   FARMER
========================================================= */

.admin-payment-farmer {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-payment-avatar {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #728995;
  background: #edf2f4;
}

.admin-payment-farmer > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-farmer strong {
  overflow: hidden;
  color: #4e6978;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-payment-farmer span {
  color: #8b9aa1;
  font-size: 6px;
}


/* =========================================================
   AMOUNT
========================================================= */

.admin-payment-amount {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-amount strong {
  color: #456474;
  font-family: var(--font-heading);
  font-size: 11px;
}

.admin-payment-amount span {
  color: #8b9aa1;
  font-size: 6px;
}


/* =========================================================
   STATUS
========================================================= */

.admin-payment-status {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
}

.admin-payment-status > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-payment-status.pending {
  color: #bd811a;
  background: #fff2d4;
}

.admin-payment-status.pending > span {
  background: #bd811a;
}

.admin-payment-status.paid {
  color: #218b52;
  background: #eaf7ed;
}

.admin-payment-status.paid > span {
  background: #218b52;
}


/* =========================================================
   REFERENCE
========================================================= */

.admin-payment-reference {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-reference strong {
  overflow: hidden;
  color: #536e7b;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-payment-reference span {
  color: #8b9aa1;
  font-size: 6px;
}


/* =========================================================
   ACTION
========================================================= */

.admin-payment-pay-button {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid #cddfe6;
  border-radius: 8px;
  color: #287eaa;
  background: #f5fafc;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-payment-pay-button:hover {
  border-color: #abc8d4;
  background: #eaf5f9;
}

.admin-payment-completed {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: #218b52;
  font-size: 6px;
  font-weight: 900;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-payments-empty {
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  color: #98a7ad;
  text-align: center;
}

.admin-payments-empty strong {
  color: #5e7784;
  font-size: 10px;
}

.admin-payments-empty span {
  color: #8b9ba2;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-payment-loading {
  min-width: 1050px;
}

.admin-payment-skeleton {
  min-height: 78px;
  display: grid;
  grid-template-columns:
    1.15fr
    1.25fr
    .9fr
    .8fr
    1fr
    1fr;
  column-gap: 11px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-payment-skeleton span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminPaymentSkeleton 1.2s infinite;
}

@keyframes adminPaymentSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-payments-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 10px;
  padding: 3px 2px 10px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   PAYMENT MODAL
========================================================= */

.admin-payment-form-overlay {
  position: fixed;
  z-index: 300;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    rgba(24, 51, 64, .34);
  backdrop-filter:
    blur(4px);
}

.admin-payment-form-modal {
  width: min(530px, 96vw);
  max-height: 92vh;
  overflow-y: auto;
  border: 1px solid #d8e3e7;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 28px 80px
    rgba(27, 55, 68, .20);
  animation:
    adminPaymentModalIn .2s ease;
}

@keyframes adminPaymentModalIn {

  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(.985);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}

.admin-payment-form-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 21px 22px 17px;
  border-bottom: 1px solid #e5ecef;
}

.admin-payment-form-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.admin-payment-form-header h2 {
  margin: 0;
  color: #294d60;
  font-family: var(--font-heading);
  font-size: 23px;
}

.admin-payment-form-header p {
  margin: 0;
  color: #84969f;
  font-size: 7px;
  line-height: 1.6;
}

.admin-payment-form-close {
  width: 35px;
  height: 35px;
  flex: 0 0 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce5e9;
  border-radius: 9px;
  color: #6d8390;
  background: #ffffff;
  cursor: pointer;
}

.admin-payment-form-close:hover {
  color: #b05046;
  border-color: #dfc7c2;
}


/* =========================================================
   MODAL BOOKING
========================================================= */

.admin-payment-form-booking {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 15px 22px;
  padding: 11px;
  border: 1px solid #dfe7ea;
  border-radius: 10px;
  background: #fafcfd;
}

.admin-payment-form-token {
  width: 45px;
  height: 32px;
  flex: 0 0 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #287eaa;
  background: #e7f3f8;
  font-size: 7px;
  font-weight: 900;
}

.admin-payment-form-booking > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-payment-form-booking strong {
  color: #4c6978;
  font-size: 8px;
}

.admin-payment-form-booking span {
  color: #8b9ba1;
  font-size: 6px;
}


/* =========================================================
   FORM
========================================================= */

.admin-payment-form {
  padding: 0 22px 22px;
}

.admin-payment-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 12px;
}

.admin-payment-field > span {
  color: #7d919b;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.admin-payment-field > input,
.admin-payment-field > select,
.admin-payment-field > textarea {
  width: 100%;
  padding: 10px;
  border: 1px solid #d5e1e5;
  border-radius: 8px;
  outline: 0;
  color: #466473;
  background: #ffffff;
  font-family: inherit;
  font-size: 8px;
  resize: vertical;
}

.admin-payment-field > input,
.admin-payment-field > select {
  min-height: 40px;
}

.admin-payment-field > input:focus,
.admin-payment-field > select:focus,
.admin-payment-field > textarea:focus {
  border-color: #8eb7c7;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .055);
}

.admin-payment-field > textarea {
  min-height: 72px;
}

.admin-payment-field > input::placeholder,
.admin-payment-field > textarea::placeholder {
  color: #aebbc1;
}


/* =========================================================
   RUPEE INPUT
========================================================= */

.admin-payment-input-wrap {
  display: flex;
  align-items: center;
  overflow: hidden;
  min-height: 40px;
  border: 1px solid #d5e1e5;
  border-radius: 8px;
  background: #ffffff;
}

.admin-payment-input-wrap:focus-within {
  border-color: #8eb7c7;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .055);
}

.admin-payment-input-wrap > span {
  padding-left: 11px;
  color: #7f929c;
  font-size: 9px;
  font-weight: 900;
}

.admin-payment-input-wrap input {
  width: 100%;
  min-height: 38px;
  padding: 0 10px 0 6px;
  border: 0;
  outline: 0;
  color: #456474;
  background: transparent;
  font-family: inherit;
  font-size: 9px;
}

.admin-payment-input-wrap input[type="number"] {
  appearance: textfield;
}

.admin-payment-input-wrap input::-webkit-inner-spin-button,
.admin-payment-input-wrap input::-webkit-outer-spin-button {
  opacity: .45;
}


/* =========================================================
   WARNING
========================================================= */

.admin-payment-form-warning {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 13px;
  padding: 10px;
  border: 1px solid #f0dfb9;
  border-radius: 9px;
  color: #a67825;
  background: #fffaf0;
}

.admin-payment-form-warning svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-payment-form-warning span {
  color: #9a855f;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   ACTIONS
========================================================= */

.admin-payment-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  margin:
    18px
    -22px
    -22px;
  padding:
    13px
    22px;
  border-top: 1px solid #e5ecef;
  background: #ffffff;
}

.admin-payment-form-cancel,
.admin-payment-form-submit {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 13px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-payment-form-cancel {
  border: 1px solid #d8e3e7;
  color: #657c88;
  background: #ffffff;
}

.admin-payment-form-cancel:hover:not(:disabled) {
  border-color: #bdcfd6;
  background: #fafcfd;
}

.admin-payment-form-submit {
  min-width: 120px;
  border: 0;
  color: #ffffff;
  background: #218b52;
}

.admin-payment-form-submit:hover:not(:disabled) {
  background: #197342;
}

.admin-payment-form-cancel:disabled,
.admin-payment-form-submit:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   MODAL SCROLLBAR
========================================================= */

.admin-payment-form-modal::-webkit-scrollbar {
  width: 7px;
}

.admin-payment-form-modal::-webkit-scrollbar-track {
  background: #f4f7f8;
}

.admin-payment-form-modal::-webkit-scrollbar-thumb {
  border-radius: 99px;
  background: #ccd9de;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 750px) {

  .admin-payments-hero {
    flex-direction: column;
  }

  .admin-payments-actions {
    width: 100%;
  }

  .admin-payments-live,
  .admin-payments-refresh {
    flex: 1;
  }

  .admin-payments-filter-panel {
    flex-wrap: wrap;
  }

  .admin-payments-search {
    flex-basis: 100%;
  }

  .admin-payments-filter {
    flex: 1;
  }

}


@media (max-width: 600px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

}


@media (max-width: 470px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-payment-form-overlay {
    align-items: flex-end;
    padding: 0;
  }

  .admin-payment-form-modal {
    width: 100%;
    max-height: 94vh;
    border-radius:
      18px
      18px
      0
      0;
  }

  .admin-payment-form-header {
    padding:
      17px;
  }

  .admin-payment-form {
    padding:
      0
      17px
      17px;
  }

  .admin-payment-form-booking {
    margin:
      13px
      17px;
  }

  .admin-payment-form-actions {
    margin:
      18px
      -17px
      -17px;
    padding:
      12px
      17px;
    flex-direction:
      column-reverse;
  }

  .admin-payment-form-cancel,
  .admin-payment-form-submit {
    width: 100%;
  }

}
/* =========================================================
   ADMIN PROCUREMENT
========================================================= */

.admin-procurement-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}

.admin-procurement-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-procurement-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-procurement-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-procurement-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-procurement-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #218b52;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-procurement-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #fff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-procurement-error {
  display: flex;
  align-items: center;
