/* =========================================================
   FARMER HISTORY + PAYMENTS
   LARGE FARMER-FRIENDLY UI
========================================================= */

.farmer-history-page,
.farmer-payments-page {
  min-height: 100vh;
  background: #f7faf8;
}

.farmer-history-container,
.farmer-payments-container {
  width: min(1250px, calc(100% - 32px));
  margin: 0 auto;
  padding: 34px 0 55px;
}


/* =========================================================
   HEADER
========================================================= */

.farmer-history-top,
.farmer-payments-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.farmer-history-top h1,
.farmer-payments-top h1 {
  margin: 8px 0 8px;
  color: #234a5c;
  font-family: var(--font-heading);
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.03;
  letter-spacing: -.035em;
}

.farmer-history-top p,
.farmer-payments-top p {
  max-width: 760px;
  margin: 0;
  color: #738a95;
  font-size: 15px;
  line-height: 1.6;
}

.farmer-history-refresh,
.farmer-payments-refresh {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  border: 1px solid #d5e3e7;
  border-radius: 10px;
  color: #55727f;
  background: #ffffff;
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
}

.farmer-history-refresh:hover:not(:disabled),
.farmer-payments-refresh:hover:not(:disabled) {
  color: #287ea5;
  border-color: #bcd3dc;
}

.farmer-history-refresh:disabled,
.farmer-payments-refresh:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   SUMMARY CARDS
========================================================= */

.farmer-history-stats,
.farmer-payments-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.farmer-history-stat,
.farmer-payments-stat {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 17px;
  border: 1px solid #dce7e9;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgba(35, 73, 92, .035);
}

.farmer-history-stat-icon,
.farmer-payments-stat-icon {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  color: #2d7ea3;
  background: #e8f4f8;
}

.farmer-history-stat > div:last-child,
.farmer-payments-stat > div:last-child {
  min-width: 0;
}

.farmer-history-stat span,
.farmer-payments-stat span {
  display: block;
  margin-bottom: 5px;
  color: #82969f;
  font-size: 11px;
  font-weight: 800;
}

.farmer-history-stat strong,
.farmer-payments-stat strong {
  display: block;
  overflow: hidden;
  color: #365b6b;
  font-family: var(--font-heading);
  font-size: 25px;
  line-height: 1.1;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   FILTERS
========================================================= */

.farmer-history-filter-bar,
.farmer-payments-filter-bar {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 16px;
  padding: 10px;
  border: 1px solid #dce7e9;
  border-radius: 12px;
  background: #ffffff;
}

.farmer-history-search,
.farmer-payments-search {
  flex: 1;
  min-width: 240px;
  height: 44px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid #d8e3e7;
  border-radius: 9px;
  color: #8598a0;
  background: #fbfcfd;
}

.farmer-history-search:focus-within,
.farmer-payments-search:focus-within {
  border-color: #a8c4ce;
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(47, 126, 163, .06);
}

.farmer-history-search input,
.farmer-payments-search input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  color: #466676;
  background: transparent;
  font-size: 13px;
}

.farmer-history-search input::placeholder,
.farmer-payments-search input::placeholder {
  color: #a2afb4;
}

.farmer-history-filter-bar select,
.farmer-payments-filter-bar select {
  height: 44px;
  min-width: 155px;
  padding: 0 12px;
  border: 1px solid #d8e3e7;
  border-radius: 9px;
  outline: 0;
  color: #57727e;
  background: #fbfcfd;
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.farmer-history-filter-bar > button,
.farmer-payments-filter-bar > button {
  height: 44px;
  padding: 0 13px;
  border: 1px solid #e0d4d0;
  border-radius: 9px;
  color: #a05d51;
  background: #fff8f6;
  cursor: pointer;
  font-size: 11px;
  font-weight: 900;
}


/* =========================================================
   MAIN LIST CARD
========================================================= */

.farmer-history-list-card,
.farmer-payments-list-card {
  overflow: hidden;
  border: 1px solid #dce7e9;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .035);
}

.farmer-history-list-heading,
.farmer-payments-list-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 19px 20px;
  border-bottom: 1px solid #edf1f2;
}

.farmer-history-list-heading h2,
.farmer-payments-list-heading h2 {
  margin: 5px 0 0;
  color: #496776;
  font-family: var(--font-heading);
  font-size: 22px;
}


/* =========================================================
   HISTORY RECORD
========================================================= */

.farmer-history-record {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr) 130px 130px 18px;
  align-items: center;
  gap: 14px;
  min-height: 88px;
  padding: 13px 20px;
  border-bottom: 1px solid #edf1f2;
  color: inherit;
  text-decoration: none;
}

.farmer-history-record:last-child {
  border-bottom: 0;
}

.farmer-history-record:hover {
  background: #fbfcfd;
}

.farmer-history-token {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #2d7598;
  background: #e9f5f8;
  font-size: 13px;
  font-weight: 900;
}

.farmer-history-crop {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.farmer-history-crop-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #619475;
  background: #edf7f0;
}

.farmer-history-crop > div:last-child {
  min-width: 0;
}

.farmer-history-crop strong,
.farmer-history-crop span {
  display: block;
}

.farmer-history-crop strong {
  overflow: hidden;
  color: #496875;
  font-size: 14px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-history-crop span {
  margin-top: 4px;
  color: #8b9da4;
  font-size: 11px;
}

.farmer-history-status {
  justify-self: start;
}

.farmer-history-amount {
  text-align: right;
}

.farmer-history-amount strong,
.farmer-history-amount span {
  display: block;
}

.farmer-history-amount strong {
  color: #307b52;
  font-family: var(--font-heading);
  font-size: 16px;
}

.farmer-history-amount span {
  margin-top: 3px;
  color: #8ea096;
  font-size: 10px;
}


/* =========================================================
   PAYMENT RECORD
========================================================= */

.farmer-payment-record {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 135px 150px auto 18px;
  align-items: center;
  gap: 13px;
  min-height: 92px;
  padding: 14px 20px;
  border-bottom: 1px solid #edf1f2;
  color: inherit;
  text-decoration: none;
}

.farmer-payment-record:last-child {
  border-bottom: 0;
}

.farmer-payment-record:hover {
  background: #fbfcfd;
}

.farmer-payment-record-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.farmer-payment-record-icon.paid {
  color: #2c8d59;
  background: #e9f7ed;
}

.farmer-payment-record-icon.pending {
  color: #b57e27;
  background: #fff3db;
}

.farmer-payment-record-main {
  min-width: 0;
}

.farmer-payment-record-main > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.farmer-payment-record-main strong {
  overflow: hidden;
  color: #4b6976;
  font-size: 14px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-payment-record-main > div span {
  color: #8e9da3;
  font-size: 11px;
}

.farmer-payment-record-main p {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 5px 0 0;
  color: #8e9da3;
  font-size: 10px;
}

.farmer-payment-record-amount {
  text-align: right;
}

.farmer-payment-record-amount strong,
.farmer-payment-record-amount span {
  display: block;
}

.farmer-payment-record-amount strong {
  color: #2c7d50;
  font-family: var(--font-heading);
  font-size: 17px;
}

.farmer-payment-record-amount span {
  margin-top: 3px;
  color: #8fa096;
  font-size: 10px;
}

.farmer-payment-record-reference {
  min-width: 0;
}

.farmer-payment-record-reference span,
.farmer-payment-record-reference strong {
  display: block;
}

.farmer-payment-record-reference span {
  margin-bottom: 4px;
  color: #98a5aa;
  font-size: 9px;
  font-weight: 900;
}

.farmer-payment-record-reference strong {
  overflow: hidden;
  color: #617d88;
  font-size: 10px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.farmer-history-loading,
.farmer-history-empty,
.farmer-payments-state,
.farmer-payments-empty {
  min-height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 10px;
  padding: 35px;
  color: #8ea0a7;
  text-align: center;
}

.farmer-history-empty strong,
.farmer-payments-state strong,
.farmer-payments-empty h1 {
  color: #58727e;
  font-family: var(--font-heading);
  font-size: 19px;
}

.farmer-history-empty span,
.farmer-payments-state span,
.farmer-payments-empty p {
  max-width: 470px;
  color: #8c9ba1;
  font-size: 12px;
  line-height: 1.6;
}


/* =========================================================
   PAYMENT HELP
========================================================= */

.farmer-payments-help {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 15px;
  padding: 15px 17px;
  border: 1px solid #e4ddd0;
  border-radius: 13px;
  background: #fffaf2;
}

.farmer-payments-help-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #ae7b2c;
  background: #fff0cd;
}

.farmer-payments-help > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.farmer-payments-help strong {
  display: block;
  color: #715c38;
  font-size: 13px;
}

.farmer-payments-help span {
  display: block;
  margin-top: 3px;
  color: #95866c;
  font-size: 10px;
}


/* =========================================================
   FOOTER ACTIONS
========================================================= */

.farmer-history-footer,
.farmer-payments-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 17px;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1050px) {

  .farmer-history-stats,
  .farmer-payments-summary {
    grid-template-columns: repeat(2, 1fr);
  }

  .farmer-history-record {
    grid-template-columns: 60px minmax(0, 1fr) 110px 18px;
  }

  .farmer-history-status {
    grid-column: 3;
  }

  .farmer-history-amount {
    grid-column: 2;
    text-align: left;
  }

  .farmer-payment-record {
    grid-template-columns: 42px minmax(0, 1fr) 110px 18px;
  }

  .farmer-payment-record-reference,
  .farmer-payment-record .admin-status-pill {
    display: none;
  }

}


@media (max-width: 760px) {

  .farmer-history-container,
  .farmer-payments-container {
    width: min(100% - 20px, 1250px);
    padding-top: 20px;
  }

  .farmer-history-top,
  .farmer-payments-top {
    flex-direction: column;
  }

  .farmer-history-refresh,
  .farmer-payments-refresh {
    width: 100%;
  }

  .farmer-history-top h1,
  .farmer-payments-top h1 {
    font-size: 36px;
  }

  .farmer-history-top p,
  .farmer-payments-top p {
    font-size: 14px;
  }

  .farmer-history-filter-bar,
  .farmer-payments-filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .farmer-history-search,
  .farmer-payments-search {
    min-width: 0;
  }

  .farmer-history-filter-bar select,
  .farmer-payments-filter-bar select,
  .farmer-history-filter-bar > button,
  .farmer-payments-filter-bar > button {
    width: 100%;
  }

  .farmer-history-stats,
  .farmer-payments-summary {
    grid-template-columns: 1fr;
  }

  .farmer-history-record {
    grid-template-columns: 48px minmax(0, 1fr) 18px;
    gap: 9px;
    min-height: 76px;
    padding: 10px 12px;
  }

  .farmer-history-status,
  .farmer-history-amount {
    grid-column: auto;
  }

  .farmer-history-amount {
    display: none;
  }

  .farmer-history-record .admin-status-pill {
    display: none;
  }

  .farmer-payment-record {
    grid-template-columns: 40px minmax(0, 1fr) 18px;
    gap: 9px;
    min-height: 78px;
    padding: 11px 12px;
  }

  .farmer-payment-record-amount {
    grid-column: 2;
    text-align: left;
  }

  .farmer-payment-record-reference,
  .farmer-payment-record .admin-status-pill {
    display: none;
  }

  .farmer-history-footer,
  .farmer-payments-footer {
    flex-direction: column;
  }

  .farmer-history-footer a,
  .farmer-payments-footer a {
    width: 100%;
  }

  .farmer-payments-help {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .farmer-payments-help a {
    width: 100%;
  }

}
/* =========================================================
   FARMER HISTORY - GRAPH
========================================================= */

.farmer-history-chart-card {
  margin-bottom: 18px;
  padding: 24px;
  border: 1px solid #dce7e9;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .04);
}

.farmer-history-chart-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 20px;
}

.farmer-history-chart-heading h2 {
  margin: 6px 0 5px;
  color: #496875;
  font-family: var(--font-heading);
  font-size: 22px;
}

.farmer-history-chart-heading p {
  margin: 0;
  color: #8c9ca3;
  font-size: 12px;
}

.farmer-history-chart-heading > svg {
  color: #629476;
}

.farmer-history-chart {
  display: flex;
  flex-direction: column;
  gap: 17px;
}

.farmer-history-chart-row {
  display: grid;
  grid-template-columns: 145px minmax(0, 1fr) 130px;
  align-items: center;
  gap: 15px;
}

.farmer-history-chart-label {
