  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 9px;
  text-align: center;
  color: #98a7ac;
}

.farmer-history-chart-empty strong {
  color: #57727e;
  font-family: var(--font-heading);
  font-size: 18px;
}

.farmer-history-chart-empty span {
  max-width: 430px;
  color: #8f9da2;
  font-size: 12px;
  line-height: 1.55;
}


/* =========================================================
   MONTH SELECTOR
========================================================= */

.farmer-history-filter-bar select {
  min-width: 175px;
  height: 46px;
  padding: 0 14px;
  border: 1px solid #d5e2e6;
  border-radius: 9px;
  outline: none;
  color: #526f7c;
  background: #ffffff;
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
