/* =========================================================
   CROP CARDS
========================================================= */

.farmer-history-crop-summary {
  margin-bottom: 18px;
  padding: 24px;
  border: 1px solid #dce7e9;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .04);
}

.farmer-history-crop-cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
