  margin-top: 15px;
}

.farmer-history-crop-card {
  padding: 15px;
  border: 1px solid #e0e9eb;
  border-radius: 12px;
  background: #fbfcfc;
}

.farmer-history-crop-card-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  border-radius: 10px;
  color: #5d9472;
  background: #edf7f0;
}

.farmer-history-crop-card strong,
.farmer-history-crop-card span,
.farmer-history-crop-card small {
  display: block;
}

.farmer-history-crop-card strong {
  color: #4f6c78;
  font-size: 14px;
}

.farmer-history-crop-card span {
  margin-top: 6px;
  color: #5e7680;
  font-size: 16px;
  font-weight: 800;
}

.farmer-history-crop-card small {
  margin-top: 3px;
  color: #348052;
  font-size: 11px;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {

  .farmer-history-chart-row {
    grid-template-columns: 120px minmax(0, 1fr) 95px;
    gap: 9px;
  }

  .farmer-history-crop-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 600px) {

  .farmer-history-chart-card,
  .farmer-history-crop-summary {
