/* =========================================================
   ADMIN PAYMENT ISSUES
========================================================= */

.admin-payment-issues-page {
  width: 100%;
}


/* =========================================================
   HERO
========================================================= */

.admin-payment-issues-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.admin-payment-issues-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  color: #6f8791;
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
}

.admin-payment-issues-back:hover {
  color: #2d7da1;
}

.admin-payment-issues-hero h2 {
  margin: 7px 0 7px;
  color: #294f61;
  font-family: var(--font-heading);
  font-size: 31px;
  line-height: 1.08;
}

.admin-payment-issues-hero p {
  max-width: 670px;
  margin: 0;
  color: #81959e;
  font-size: 12px;
  line-height: 1.6;
}

.admin-payment-issues-refresh {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid #d9e5e8;
  border-radius: 9px;
  color: #5d7884;
  background: #ffffff;
  cursor: pointer;
  font-size: 10px;
  font-weight: 800;
}

.admin-payment-issues-refresh:hover:not(:disabled) {
  color: #2d7da1;
  border-color: #bed5de;
}

.admin-payment-issues-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-payment-issues-error {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 14px;
  padding: 11px 13px;
  border: 1px solid #ecd6d1;
  border-radius: 10px;
  color: #9a5e54;
  background: #fff8f6;
  font-size: 10px;
}

.admin-payment-issues-error span {
  flex: 1;
}

.admin-payment-issues-error button {
  width: 27px;
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 7px;
  color: #9a665e;
  background: transparent;
  cursor: pointer;
}


/* =========================================================
   STATS
========================================================= */

.admin-payment-issues-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.admin-payment-issue-stat {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid #dfe8ea;
  border-radius: 12px;
  background: #ffffff;
}

.admin-payment-issue-stat-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: #edf4f6;
  color: #63808b;
}

.admin-payment-issue-stat span,
.admin-payment-issue-stat strong {
  display: block;
}

.admin-payment-issue-stat span {
  color: #91a1a7;
  font-size: 7px;
  font-weight: 800;
}

.admin-payment-issue-stat strong {
  margin-top: 3px;
  color: #526d78;
  font-family: var(--font-heading);
  font-size: 21px;
}

.admin-payment-issue-stat.orange .admin-payment-issue-stat-icon {
  color: #ae772c;
  background: #fff1d8;
}

.admin-payment-issue-stat.green .admin-payment-issue-stat-icon {
  color: #2d8955;
  background: #e8f6eb;
}

.admin-payment-issue-stat.blue .admin-payment-issue-stat-icon {
  color: #2d7da2;
  background: #e8f4f8;
}


/* =========================================================
   FILTER
========================================================= */

.admin-payment-issues-filter {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dfe8ea;
  border-radius: 11px;
  background: #ffffff;
}

.admin-payment-issues-search {
  flex: 1;
  min-width: 240px;
  height: 38px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid #d9e3e6;
  border-radius: 8px;
  color: #879ba3;
  background: #fbfcfc;
}

.admin-payment-issues-search:focus-within {
  border-color: #aac5cf;
  box-shadow: 0 0 0 3px rgba(45, 125, 161, .05);
}

.admin-payment-issues-search input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  color: #506e79;
  background: transparent;
  font-size: 10px;
}

.admin-payment-issues-search input::placeholder {
  color: #a1afb4;
}

.admin-payment-issues-filter select {
  height: 38px;
  min-width: 135px;
  padding: 0 10px;
  border: 1px solid #d9e3e6;
  border-radius: 8px;
  outline: 0;
  color: #5a7480;
  background: #fbfcfd;
  cursor: pointer;
  font-size: 9px;
  font-weight: 800;
}


/* =========================================================
   LIST
========================================================= */

.admin-payment-issues-list-card {
  overflow: hidden;
  border: 1px solid #dfe8ea;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 7px 23px rgba(35, 73, 92, .025);
}

.admin-payment-issues-list-header {
  padding: 15px 16px;
  border-bottom: 1px solid #edf1f2;
}

.admin-payment-issues-list-header h3 {
  margin: 5px 0 0;
  color: #516c78;
  font-family: var(--font-heading);
  font-size: 16px;
}


/* =========================================================
   ISSUE ROW
========================================================= */

.admin-payment-issue-row {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 180px;
  gap: 12px;
  align-items: start;
  padding: 15px 16px;
  border-bottom: 1px solid #edf1f2;
}

.admin-payment-issue-row:last-child {
  border-bottom: 0;
}

.admin-payment-issue-row:hover {
  background: #fcfdfd;
}

.admin-payment-issue-icon {
  width: 39px;
  height: 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-payment-issue-icon.open {
  color: #b4762a;
  background: #fff0d5;
}

.admin-payment-issue-icon.resolved {
  color: #2a8a56;
  background: #e8f6eb;
}

.admin-payment-issue-main {
  min-width: 0;
}

.admin-payment-issue-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-payment-issue-title strong {
  color: #4f6a76;
  font-size: 11px;
}

.admin-payment-issue-status {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-payment-issue-status.open {
  color: #a66c24;
  background: #fff1d9;
}

.admin-payment-issue-status.resolved {
  color: #2b8352;
  background: #e8f6eb;
}

.admin-payment-issue-farmer {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 6px;
  color: #84979f;
  font-size: 8px;
}

.admin-payment-issue-main p {
  margin: 8px 0 5px;
  color: #627b85;
  font-size: 9px;
  line-height: 1.55;
}

.admin-payment-issue-main small {
  color: #a1adb1;
  font-size: 6px;
}

.admin-payment-issue-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}

.admin-payment-issue-view,
.admin-payment-issue-resolve,
.admin-payment-issue-reopen {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 7px;
  font-size: 7px;
  font-weight: 900;
  text-decoration: none;
  cursor: pointer;
}

.admin-payment-issue-view {
  border: 1px solid #d7e4e8;
  color: #477182;
  background: #ffffff;
}

.admin-payment-issue-view:hover {
  background: #f5f9fa;
}

.admin-payment-issue-resolve {
  border: 1px solid #c9e2d2;
  color: #287a4d;
  background: #edf8f0;
}

.admin-payment-issue-resolve:hover:not(:disabled) {
  background: #e3f4e8;
}

.admin-payment-issue-reopen {
  border: 1px solid #e0d5ca;
  color: #946e47;
  background: #fffaf5;
}

.admin-payment-issue-resolve:disabled,
.admin-payment-issue-reopen:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-payment-issues-state {
  min-height: 230px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  padding: 28px;
  color: #93a2a7;
  text-align: center;
}

.admin-payment-issues-state strong {
  color: #5a7480;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-payment-issues-state span {
  color: #96a3a8;
  font-size: 8px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 800px) {

  .admin-payment-issues-hero {
    flex-direction: column;
  }

  .admin-payment-issues-refresh {
    width: 100%;
  }

  .admin-payment-issues-stats {
    grid-template-columns: 1fr;
  }

  .admin-payment-issues-filter {
    flex-direction: column;
    align-items: stretch;
  }

  .admin-payment-issues-search {
    min-width: 0;
  }

  .admin-payment-issues-filter select {
    width: 100%;
  }

  .admin-payment-issue-row {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .admin-payment-issue-actions {
    grid-column: 2;
    flex-direction: row;
  }

  .admin-payment-issue-actions > * {
    flex: 1;
  }

}

@media (max-width: 500px) {

  .admin-payment-issues-hero h2 {
    font-size: 26px;
  }

  .admin-payment-issues-hero p {
    font-size: 10px;
  }

  .admin-payment-issue-row {
    padding: 12px;
  }

  .admin-payment-issue-title {
    flex-wrap: wrap;
  }

  .admin-payment-issue-actions {
    flex-direction: column;
  }

}
