  border-radius: 14px;
  background: #fbfcfc;
}


.home-detail-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border-radius: 11px;
}


.home-detail span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .04em;
}


.home-detail strong {
  display: block;
  margin-top: 5px;
  color: var(--ks-text);
