  --ks-green: #6fd091;
  --ks-green-light: #15392a;

  --ks-orange: #f0b56a;
  --ks-orange-light: #3b2b1c;

  --ks-red: #ee8c84;
  --ks-red-light: #3b211f;

  --ks-purple: #ad9be7;
  --ks-purple-light: #2c2544;

  --ks-teal: #72cec8;
  --ks-teal-light: #183b39;

  --ks-gold: #d9b75e;
  --ks-gold-light: #392f1a;
}


