/* =========================================================
   KRISHISETU — PUNCHY LANDING PAGE
   Bright civic + agricultural visual style
========================================================= */

.landing-page {

  --lp-blue: #168bd0;
  --lp-blue-dark: #075a91;
  --lp-blue-soft: #e4f4ff;

  --lp-green: #16a05a;
  --lp-green-dark: #08753e;
  --lp-green-soft: #e2f8eb;

  --lp-orange: #f28a18;
  --lp-orange-soft: #fff0d9;

  --lp-purple: #7757d5;
  --lp-purple-soft: #f0ebff;

  --lp-teal: #0a9990;
  --lp-teal-soft: #e1f8f5;

  --lp-navy: #123e59;
  --lp-text: #426575;
  --lp-soft: #718b96;

  --lp-bg: #edf7f7;
  --lp-card: #ffffff;
  --lp-border: #d4e6ea;

  min-height: 100vh;
  overflow-x: hidden;

  color: var(--lp-text);

  background:
    radial-gradient(
      circle at 5% 0%,
      rgba(28,160,90,.15),
      transparent 22%
    ),
    radial-gradient(
      circle at 96% 4%,
      rgba(22,139,208,.15),
      transparent 25%
    ),
    radial-gradient(
      circle at 52% 38%,
      rgba(242,138,24,.05),
      transparent 30%
    ),
    linear-gradient(
      180deg,
      #eaf6f7 0%,
      #f9fcfb 43%,
      #eef7f5 100%
    );
}


/* =========================================================
   HEADER
========================================================= */

.landing-header {

  position: sticky;
  top: 0;
  z-index: 100;

  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: 88px;

  padding:
    8px
    clamp(18px, 4vw, 64px);

  border-bottom:
    1px solid rgba(194,216,222,.85);

  background:
    rgba(255,255,255,.86);

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);

}


.landing-brand {

  display: flex;
  align-items: center;

  min-width: 250px;

  color: var(--lp-navy);

  text-decoration: none;

}


.landing-brand svg {

  transform:
    scale(1.09);

  transform-origin:
    left center;

}


.landing-nav {

  display: flex;
  align-items: center;
  gap: 32px;

}


.landing-nav a {

  position: relative;

  color: #4f6f7c;

  font-size: 12px;
  font-weight: 850;

  text-decoration: none;

}


.landing-nav a::after {

  content: "";

  position: absolute;

  left: 0;
  right: 100%;

  bottom: -8px;

  height: 3px;

  border-radius: 999px;

  background:
    linear-gradient(
      90deg,
      var(--lp-green),
      var(--lp-blue)
    );

  transition:
    right .25s ease;

}


.landing-nav a:hover {

  color:
    var(--lp-blue);

}


.landing-nav a:hover::after {

  right:
    0;

}


/* =========================================================
   HEADER BUTTONS
========================================================= */

.landing-header-actions {

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

}


.landing-nav-farmer,
.landing-nav-admin {

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  min-height:
    43px;

  padding:
    0 16px;

  border-radius:
    11px;

  font-size:
    10px;

  font-weight:
    950;

  text-decoration:
    none;

}


.landing-nav-farmer {

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #19a85c,
      #08733f
    );

  box-shadow:
    0 8px 18px rgba(22,160,90,.20);

}


.landing-nav-admin {

  color:
    var(--lp-blue-dark);

  border:
    1px solid #b9d7e4;

  background:
    #f5fbfe;

}


.landing-nav-farmer:hover,
.landing-nav-admin:hover {

  transform:
    translateY(-2px);

}


/* =========================================================
   HERO
========================================================= */

.landing-hero {

  position:
    relative;

  display:
    grid;

  grid-template-columns:
    minmax(0, 1.02fr)
    minmax(470px, .98fr);

  gap:
    35px;

  min-height:
    700px;

  padding:
    74px
    clamp(22px, 7vw, 100px)
    68px;

}


.landing-hero-background {

  position:
    absolute;

  inset:
    0;

  pointer-events:
    none;

}


.landing-glow {

  position:
    absolute;

  border-radius:
    50%;

}


.landing-glow-one {

  width:
    560px;

  height:
    560px;

  left:
    -250px;

  top:
    -280px;

  background:
    rgba(22,160,90,.11);

  filter:
    blur(14px);

}


.landing-glow-two {

  width:
    620px;

  height:
    620px;

  right:
    -270px;

  bottom:
    -340px;

  background:
    rgba(22,139,208,.11);

  filter:
    blur(14px);

}


.landing-grid-pattern {

  position:
    absolute;

  inset:
    0;

  opacity:
    .5;

  background-image:
    linear-gradient(
      rgba(24,89,113,.04) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(24,89,113,.04) 1px,
      transparent 1px
    );

  background-size:
    52px 52px;

}


/* =========================================================
   HERO CONTENT
========================================================= */

.landing-hero-content {

  position:
    relative;

  z-index:
    5;

  align-self:
    center;

  max-width:
    760px;

}


.landing-hero-badge {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    9px;

  min-height:
    35px;

  padding:
    0 13px;

  border:
    1px solid #bce0ca;

  border-radius:
    999px;

  color:
    #197445;

  background:
    #e8f8ee;

  font-size:
    9px;

  font-weight:
    950;

  letter-spacing:
    .12em;

  box-shadow:
    0 5px 16px rgba(30,117,70,.08);

}


/* =========================================================
   HERO LOGO
========================================================= */

.landing-hero-logo {

  display:
    flex;

  align-items:
    center;

  min-height:
    128px;

  margin:
    25px 0 28px;

}


.landing-hero-logo svg {

  transform:
    scale(1.10);

  transform-origin:
    left center;

}


/* =========================================================
   HERO TITLE
========================================================= */

.landing-hero-content h1 {

  max-width:
    740px;

  margin:
    8px 0 0;

  color:
    var(--lp-navy);

  font-size:
    clamp(
      50px,
      6vw,
      82px
    );

  line-height:
    .89;

  letter-spacing:
    -.065em;

  font-weight:
    950;

