/* =========================================================
   MOTION ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .landing-page *,
  .landing-page *::before,
  .landing-page *::after {

    animation:
      none !important;

    transition:
      none !important;

  }

  
}

/* =========================================================
   FARMER LOGIN — FINAL STYLE
========================================================= */

.farmer-login-page {
  position: relative;
  min-height: 100vh;
  overflow-x: hidden;

  color: #345866;

  background:
    radial-gradient(
      circle at 8% 5%,
      rgba(29, 166, 91, .13),
      transparent 25%
    ),
    radial-gradient(
      circle at 94% 7%,
      rgba(23, 142, 207, .14),
      transparent 27%
    ),
    radial-gradient(
      circle at 52% 90%,
      rgba(243, 143, 29, .06),
      transparent 30%
    ),
    linear-gradient(
      180deg,
      #edf8f5 0%,
      #f8fcfb 52%,
      #eef7f8 100%
    );
}


/* =========================================================
   LANGUAGE SELECTOR
========================================================= */

.farmer-login-language {
  position: absolute;
  top: 98px;
  right: clamp(16px, 5vw, 70px);
  z-index: 30;

  display: flex;
  align-items: center;
  gap: 3px;

  padding: 4px;

  border: 1px solid #d2e3e7;
  border-radius: 12px;

  background: rgba(255,255,255,.92);

  box-shadow:
    0 8px 24px rgba(30,73,86,.08);

  backdrop-filter: blur(14px);
}


.farmer-login-language > svg {
  margin:
    0 4px 0 6px;

  color:
    #1689bd;
}


.farmer-login-language button {
  min-height:
    35px;

  padding:
    0 10px;

  border:
    0;

  border-radius:
    8px;

  color:
    #738990;

  background:
    transparent;

  font-size:
    9px;

  font-weight:
    950;

  cursor:
    pointer;

  transition:
    .2s ease;
}


.farmer-login-language button:hover {
  color:
    #1479a7;

  background:
    #edf8fb;
}


.farmer-login-language button.active {
  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #168fca,
      #126a99
