.register-crop-card {
  display:
    flex;

  flex-direction:
    column;

  align-items:
    center;

  justify-content:
    center;

  min-height:
    92px;

  padding:
    10px;

  border:
    1px solid #d4e3e6;

  border-radius:
    13px;

  color:
    #58747e;

  background:
    #fbfdfd;

  cursor:
    pointer;
}


.register-crop-card:hover {
  transform:
    translateY(-2px);

  border-color:
    #a8ced8;

  background:
    #f2fafb;
}


.register-crop-card.selected {
  border:
    2px solid #1b9657;

  color:
    #177b4b;

  background:
    #ebf8ef;

  box-shadow:
    0 8px 18px rgba(27,150,87,.08);
}


.register-crop-card span {
  margin-top:
    6px;

  font-size:
    9px;

  font-weight:
    900;
}


/* =========================================================
   QUANTITY
========================================================= */

.register-quantity-row {
  display:
    flex;

  align-items:
    center;

  min-height:
    53px;

  overflow:
    hidden;

  border:
    1px solid #cadde2;

  border-radius:
    12px;

  background:
    #fbfefe;
}


.register-quantity-row input {
  flex:
    1;

  height:
    51px;

  padding:
    0 13px;

  border:
    0;

  outline:
    none;

  color:
    #284f60;

  background:
    transparent;

  font-size:
    15px;

  font-weight:
    850;
}


.register-quantity-unit {
  display:
    grid;

  place-items:
    center;

  width:
    58px;

  height:
    53px;

  border-left:
    1px solid #dce8ea;

  color:
    #718991;

  background:
    #f5f9fa;

  font-size:
    10px;

  font-weight:
    950;
}


/* =========================================================
   LANGUAGE SECTION
========================================================= */

.register-language-options {
  display:
    grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:
    9px;
}


.register-language-option {
  min-height:
    50px;

  border:
    1px solid #d3e2e5;

  border-radius:
    11px;

  color:
    #617b84;

  background:
    #fbfdfd;

  font-size:
    11px;

  font-weight:
    850;

  cursor:
    pointer;
}


.register-language-option:hover {
  border-color:
    #9fc8d4;

  background:
    #f1fafc;
}


.register-language-option.selected {
  color:
    #ffffff;

  border-color:
    #168d58;

  background:
    linear-gradient(
      135deg,
      #1b9d5d,
      #0b7440
    );

  box-shadow:
    0 7px 17px rgba(27,157,93,.16);
}


/* =========================================================
   SUBMIT / FORM BUTTON
========================================================= */

.register-form-card button[type="submit"] {
  min-height:
    55px;

  margin-top:
    12px;

  border-radius:
    12px;

  font-size:
    12px;

  font-weight:
    950;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark .farmer-register-page,
body.dark .farmer-register-page,
html.dark-mode .farmer-register-page,
body.dark-mode .farmer-register-page,
html[data-theme="dark"] .farmer-register-page,
body[data-theme="dark"] .farmer-register-page {

  color:
    #dcebed;

  background:
    radial-gradient(
      circle at 5% 2%,
      rgba(38,160,99,.13),
      transparent 27%
    ),
    radial-gradient(
      circle at 95% 5%,
      rgba(42,143,191,.14),
      transparent 29%
    ),
    linear-gradient(
      180deg,
      #07161d,
      #0b1d24 55%,
      #091a21
    ) !important;
}


/* dark intro */

html.dark .register-intro h1,
html.dark .register-form-heading h2,
html.dark .register-feature strong,
html.dark .register-field label,
body.dark .register-intro h1,
body.dark .register-form-heading h2,
body.dark .register-feature strong,
body.dark .register-field label {

  color:
    #f0f8fa !important;
}


html.dark .register-intro h1 span {
  color:
    #72d99a;
}


html.dark .register-intro > p,
html.dark .register-benefit span,
html.dark .register-form-heading p,
html.dark .register-hint,
html.dark .register-input input,
html.dark .register-input select,
body.dark .register-intro > p,
body.dark .register-benefit span,
body.dark .register-form-heading p,
body.dark .register-hint,
body.dark .register-input input,
body.dark .register-input select {

  color:
    #aec5ca !important;
}


/* dark benefit cards */

html.dark .register-benefit,
html.dark .register-benefits > div {

  background:
    #11272f !important;

  border-color:
    #2a4650 !important;

  box-shadow:
    0 8px 22px rgba(0,0,0,.20);
}


html.dark .register-benefit-icon {

  color:
    #77d99a;

  background:
    #173b2c;
}


/* dark form card */

html.dark .register-form-card {

  background:
    #11272f !important;

  border-color:
    #2a4650 !important;

  box-shadow:
    0 24px 60px rgba(0,0,0,.28);
}


/* dark section */

html.dark .register-section {

  border-color:
    #29444d;
}


html.dark .register-section-label {

  color:
    #72d89a;
}


/* dark inputs */

html.dark .register-input,
html.dark .register-quantity-row,
html.dark .register-select-button,
html.dark .register-location-button {

  color:
    #d6e6e9;

  background:
    #0d2028;

  border-color:
    #35535d;
}


html.dark .register-input:focus-within {

  background:
    #102730;

  border-color:
    #55b7db;

  box-shadow:
    0 0 0 4px rgba(85,183,219,.08);
}


html.dark .register-input > svg {

  color:
    #87aab3;
}


html.dark .register-input input::placeholder,
html.dark .register-quantity-row input::placeholder {

  color:
    #627b82;
}


html.dark .register-quantity-unit {

  color:
    #9db8be;

  background:
    #142b33;

  border-color:
    #29454e;
}


/* dark verified */

html.dark .verified-input {

  background:
    #123126;

  border-color:
    #2c6549;
}


html.dark .verified-mark {

  color:
    #7cdf9f;

  background:
    #194333;
}


/* dark dropdowns */

html.dark .register-select-menu,
html.dark .register-location-menu {

  background:
    #10252d;

  border-color:
    #31505a;

  box-shadow:
    0 20px 40px rgba(0,0,0,.35);
}


html.dark .register-select-option,
html.dark .register-location-option {

  color:
    #bad0d5;
}


html.dark .register-select-option:hover,
html.dark .register-location-option:hover {

  color:
    #8ed4ed;

  background:
    #183640;
}


html.dark .register-select-option.selected,
html.dark .register-location-option.selected {

  color:
    #7de0a0;

  background:
    #193f30;
}


/* dark crop cards */

html.dark .register-crop-card {

  color:
    #abc3c9;

  background:
    #10252d;

  border-color:
    #2c4851;
}


html.dark .register-crop-card:hover {

  background:
    #15323b;

  border-color:
    #41626c;
}


html.dark .register-crop-card.selected {

  color:
    #7ce09e;

  background:
    #163d2e;

  border-color:
    #4ab97b;
}


/* dark language options */

html.dark .register-language-option {

  color:
    #abc3c9;

  background:
    #0f242c;

  border-color:
    #2c4851;
}


html.dark .register-language-option:hover {

  background:
    #183640;

  border-color:
    #41626c;
}


/* dark error */

html.dark .register-error {

  color:
    #ffaaa2;
}


html.dark .register-input-error {

  background:
    #2b1d1d;

  border-color:
    #693e39;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 950px) {

  .register-layout {

    grid-template-columns:
      1fr;

    gap:
      35px;

  }


  .register-intro {

    position:
      static;

  }


  .register-intro h1 {

    max-width:
      760px;

  }

}


@media (max-width: 650px) {

  .register-container {

    width:
      calc(100% - 20px);

    padding:
      25px 0 55px;

  }


  .register-layout {

    gap:
      28px;

  }


  .register-intro h1 {

    font-size:
      39px;

  }


  .register-intro > p {

    font-size:
      13px;

  }


  .register-form-card {

    padding:
      20px;

    border-radius:
      19px;

  }


  .register-form-heading h2 {

    font-size:
      24px;

  }


  .register-two-column {

    grid-template-columns:
      1fr;

  }


  .register-crop-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


  .register-language-options {

    grid-template-columns:
      1fr;

  }

}


@media (max-width: 400px) {

  .register-intro h1 {

    font-size:
      35px;

  }


  .register-form-card {

    padding:
      17px;

  }


  .verified-mark {

    padding:
      4px 6px;

    font-size:
      7px;

  }

}

/* =========================================================
   FARMER HELP — LARGE, COLOURFUL, HIGH-CONTRAST DESIGN
========================================================= */

.farmer-help-page {
  --help-green: #18a45d;
  --help-green-dark: #087441;
  --help-green-soft: #e5f8ed;

  --help-blue: #168bc8;
  --help-blue-dark: #0e6493;
  --help-blue-soft: #e5f5fc;

  --help-orange: #ef8b1b;
  --help-orange-soft: #fff0dc;

  --help-purple: #7956d6;
  --help-purple-soft: #f0ebff;

  --help-gold: #d99a12;
  --help-gold-soft: #fff4d8;

  --help-teal: #0c9990;
  --help-teal-soft: #e3f8f5;

  --help-navy: #123f58;
  --help-text: #466875;
  --help-muted: #748b94;

  --help-bg: #f1f8f7;
  --help-card: #ffffff;
  --help-border: #d5e5e8;

  min-height: 100vh;

  color:
    var(--help-text);

  background:
    radial-gradient(
      circle at 4% 3%,
      rgba(24,164,93,.12),
      transparent 24%
    ),
    radial-gradient(
      circle at 96% 5%,
      rgba(22,139,200,.13),
      transparent 27%
    ),
    linear-gradient(
      180deg,
      #edf8f6 0%,
      #f8fcfb 46%,
      #eef7f7 100%
    );
}


/* =========================================================
   GLOBAL CONTAINER
========================================================= */

.help-container {
  width:
    min(
      1240px,
      calc(100% - 32px)
    );

  margin:
    0 auto;

  padding:
    30px 0 85px;
}


/* =========================================================
   HERO
========================================================= */

.help-hero {
  display:
    grid;

  grid-template-columns:
    minmax(0,1.1fr)
    minmax(370px,.65fr);

  gap:
    45px;

  align-items:
    center;

  min-height:
    600px;

  padding:
    45px 0 65px;
}


.help-hero-copy {
  max-width:
    760px;
}


.help-hero-copy .back-link {
  margin-bottom:
    24px;
}


.help-eyebrow-row {
  display:
    flex;

  align-items:
    center;

  flex-wrap:
    wrap;

  gap:
    10px;

  margin-bottom:
    12px;
}


.help-support-pill {
  display:
    inline-flex;

  align-items:
    center;

  gap:
    7px;

  min-height:
    29px;

  padding:
    0 10px;

  border:
    1px solid #bce0c9;

  border-radius:
    999px;

  color:
    #1b7c49;

  background:
    #e8f8ee;

  font-size:
    8px;

  font-weight:
    950;

  letter-spacing:
    .08em;
}


.help-support-pill > span {
  width:
    7px;

  height:
    7px;

  border-radius:
    50%;

  background:
    #19a25d;

  box-shadow:
    0 0 0 4px rgba(25,162,93,.10);
}


.help-hero h1 {
  max-width:
    760px;

  margin:
    10px 0 0;

  color:
    var(--help-navy);

  font-size:
    clamp(
      50px,
      6.3vw,
      84px
    );

  line-height:
    .90;

  letter-spacing:
    -.065em;

  font-weight:
    950;
}


.help-hero h1 span {
  display:
    block;

  margin-top:
    9px;

  color:
    var(--help-green);
}


.help-hero-copy > p {
  max-width:
    700px;

  margin-top:
    22px;

  color:
    #5d7882;

  font-size:
    15px;

  line-height:
    1.82;
}


/* =========================================================
   HERO ACTIONS
========================================================= */

.help-hero-actions {
  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    10px;

  margin-top:
    29px;
}


.help-primary-action,
.help-secondary-action {
  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    9px;

  min-height:
    54px;

  padding:
    0 18px;

  border-radius:
    13px;

  font-size:
    11px;

  font-weight:
    950;

  text-decoration:
    none;

  transition:
    transform .2s ease,
    box-shadow .2s ease;
}


.help-primary-action {
  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #19a35d,
      #087340
    );

  box-shadow:
    0 11px 25px rgba(24,164,93,.20);
}


.help-secondary-action {
  color:
    var(--help-blue-dark);

  border:
    1px solid #bcd9e3;

  background:
    #ffffff;
}


.help-primary-action:hover,
.help-secondary-action:hover {
  transform:
    translateY(-3px);
}


/* =========================================================
   HERO QUICK HELP CARD
========================================================= */

.help-hero-card {
  position:
    relative;

  overflow:
    hidden;

  padding:
    26px;

  border:
    1px solid #d1e4e7;

  border-radius:
    23px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f0f9f8
    );

  box-shadow:
    0 24px 55px rgba(27,72,84,.10);
}


.help-hero-card::before {
  content:
    "";

  position:
    absolute;

  left:
    0;

  right:
    0;

  top:
    0;

  height:
    6px;

  background:
    linear-gradient(
      90deg,
      var(--help-green),
      var(--help-blue),
      var(--help-orange)
    );
}


.help-hero-card-top {
  display:
    flex;

  align-items:
    center;

  gap:
    14px;
}


.help-hero-card-icon {
  display:
    grid;

  place-items:
    center;

  width:
    54px;

  height:
    54px;

  flex:
    0 0 54px;

  border-radius:
    15px;

  color:
    var(--help-blue);

  background:
    var(--help-blue-soft);
}


.help-hero-card-top span {
  display:
    block;

  color:
    var(--help-orange);

  font-size:
    9px;

  font-weight:
    950;

  letter-spacing:
    .14em;
}


.help-hero-card-top strong {
  display:
    block;

  margin-top:
    5px;

  color:
    var(--help-navy);

  font-size:
    23px;

  line-height:
    1.1;
}


.help-hero-check-list {
  display:
    grid;

  gap:
    11px;

  margin-top:
    25px;

  padding-top:
    21px;

  border-top:
    1px solid #e0ebed;
}


.help-check-row {
  display:
    flex;

  align-items:
    flex-start;

  gap:
    9px;

  color:
    #4e6f7b;

  font-size:
    11px;

  line-height:
    1.55;
}


.help-check-row svg {
  flex:
    0 0 auto;

  margin-top:
    1px;

  color:
    var(--help-green);
}


/* =========================================================
   SECTION HEADINGS
========================================================= */

.help-section-heading {
  margin-bottom:
    34px;
}


.help-section-heading .page-eyebrow {
  color:
    var(--help-orange);

  font-size:
    10px;

  font-weight:
    950;

  letter-spacing:
    .15em;
}


.help-section-heading h2 {
  max-width:
    800px;

  margin-top:
    9px;

  color:
    var(--help-navy);

  font-size:
    clamp(
      35px,
      4.7vw,
      55px
    );

  line-height:
    .97;

  letter-spacing:
    -.05em;

  font-weight:
    950;
}


.help-section-heading p {
  max-width:
    740px;

  margin-top:
    12px;

  color:
    var(--help-muted);

  font-size:
    13px;

  line-height:
    1.75;
}


/* =========================================================
   QUICK TOPICS
========================================================= */

.help-quick-section {
  padding:
    55px 0 105px;
}


.help-topic-grid {
  display:
    grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:
    14px;
}


.help-topic-card {
  display:
    grid;

  grid-template-columns:
    auto 1fr auto;

  align-items:
    center;

  gap:
    13px;

  min-height:
    126px;

  padding:
    17px;

  border:
    1px solid var(--help-border);

  border-radius:
    18px;

  color:
    inherit;

  background:
    var(--help-card);

  box-shadow:
    0 7px 21px rgba(27,72,84,.045);

  text-align:
    left;

  cursor:
    pointer;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    border-color .2s ease;
}


.help-topic-card:hover {
  transform:
    translateY(-5px);

  box-shadow:
    0 17px 35px rgba(27,72,84,.085);
}


.help-topic-icon {
  display:
    grid;

  place-items:
    center;

  width:
    48px;

  height:
    48px;

  border-radius:
    13px;
}


.help-topic-card.green .help-topic-icon {
  color:
    var(--help-green);

  background:
    var(--help-green-soft);
}


.help-topic-card.blue .help-topic-icon {
  color:
    var(--help-blue);

  background:
    var(--help-blue-soft);
}


.help-topic-card.orange .help-topic-icon {
  color:
    var(--help-orange);

  background:
    var(--help-orange-soft);
}


.help-topic-card.purple .help-topic-icon {
  color:
    var(--help-purple);

  background:
    var(--help-purple-soft);
}


.help-topic-card.gold .help-topic-icon {
  color:
    var(--help-gold);

  background:
    var(--help-gold-soft);
}


.help-topic-card.teal .help-topic-icon {
  color:
    var(--help-teal);

  background:
    var(--help-teal-soft);
}


.help-topic-card strong {
  display:
    block;

  color:
    var(--help-navy);

  font-size:
    16px;

  font-weight:
    950;
}


.help-topic-card p {
  margin-top:
    5px;

  color:
    var(--help-muted);

  font-size:
    10px;

  line-height:
    1.6;
}


.help-topic-card > svg {
  color:
    #9bb0b7;

  transition:
    transform .2s ease;
}


.help-topic-card:hover > svg {
  transform:
    translateX(4px);

  color:
    var(--help-blue);
}


/* =========================================================
   GUIDES
========================================================= */

.help-guide-section {
  padding:
    100px 0;

  background:
    rgba(255,255,255,.44);
}


.help-guides-grid {
  display:
    grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:
    16px;
}


.help-guide-card {
  position:
    relative;

  min-height:
    390px;

  padding:
    22px;

  overflow:
    hidden;

  border:
    1px solid var(--help-border);

  border-radius:
    20px;

  background:
    var(--help-card);

  box-shadow:
    0 8px 23px rgba(27,72,84,.045);
}


.help-guide-card::before {
  content:
    "";

  position:
    absolute;

  left:
    0;

  right:
    0;

  top:
    0;

  height:
    5px;
}


.help-guide-card.green::before {
  background:
    var(--help-green);
}


.help-guide-card.blue::before {
  background:
    var(--help-blue);
}


.help-guide-card.orange::before {
  background:
    var(--help-orange);
}


.help-guide-card.purple::before {
  background:
    var(--help-purple);
}


.help-guide-card.gold::before {
  background:
    var(--help-gold);
}


.help-guide-card.teal::before {
  background:
    var(--help-teal);
}


.help-guide-top {
  display:
    flex;

  align-items:
    flex-start;

  justify-content:
    space-between;
}


.help-guide-icon {
  display:
    grid;

  place-items:
    center;

  width:
    50px;

  height:
    50px;

  border-radius:
    14px;
}


.help-guide-card.green .help-guide-icon {
  color:
    var(--help-green);

  background:
