    grid-template-columns:
      1fr;

    min-height:
      auto;

  }


  .help-hero-card {

    max-width:
      650px;

  }


  .help-topic-grid,
  .help-guides-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


  .help-checklist-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


  .help-faq-layout {

    grid-template-columns:
      1fr;

  }


  .help-faq-side {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


