/* =========================================================
   CUSTOM KRISHISETU LOGO
========================================================= */

.krishisetu-logo-mark {
  display: block;

  width: var(--logo-size, 40px);
  height: var(--logo-size, 40px);

  flex: 0 0 auto;

  border-radius: 50%;

  object-fit: cover;
  object-position: center;

  overflow: hidden;

  background: transparent;

  /* removes tiny square-edge appearance */
  clip-path: circle(50% at 50% 50%);
}


/* Keep logo + name aligned nicely */

.krishisetu-logo {
  display: inline-flex;

  align-items: center;

  gap: 11px;

  min-width: 0;
}


.krishisetu-logo-with-name {
  align-items: center;
}


.krishisetu-logo-wordmark {
  display: flex;

  flex-direction: column;

  min-width: 0;

  white-space: nowrap;
}


.krishisetu-logo-wordmark strong {
  color: var(--text);

  font-size: 18px;

  line-height: 1;

  font-weight: 950;
}


.krishisetu-logo-wordmark span {
  margin-top: 4px;

  color: var(--muted);

  font-size: 8px;

  line-height: 1;

  font-weight: 800;
}
.krishisetu-logo-mark {
  width: auto !important;
  height: auto !important;

  min-width: 58px;
  min-height: 58px;

  width: 58px !important;
  height: 58px !important;

  border-radius: 50%;
  object-fit: cover;
  object-position: center;

  clip-path: circle(50% at 50% 50%);

  transform: scale(1.08);
  transform-origin: center;
}

.krishisetu-logo-with-name .krishisetu-logo-mark {
  width: 68px !important;
  height: 68px !important;
}

.krishisetu-logo-wordmark strong {
  font-size: 20px;
}

.krishisetu-logo-wordmark span {
  font-size: 9px;
}


/* Larger landing-page logo */

.landing-hero-logo .krishisetu-logo-mark {
  width: 112px !important;
  height: 112px !important;
}

.landing-hero-logo .krishisetu-logo-wordmark strong {
  font-size: 31px;
}

.landing-hero-logo .krishisetu-logo-wordmark span {
  font-size: 11px;
}


/* Footer */

.landing-footer-logo .krishisetu-logo-mark {
  width: 52px !important;
  height: 52px !important;
}


@media (max-width: 650px) {

  .krishisetu-logo-with-name .krishisetu-logo-mark {
    width: 58px !important;
    height: 58px !important;
  }

  .landing-hero-logo .krishisetu-logo-mark {
    width: 92px !important;
    height: 92px !important;
  }

  .landing-hero-logo .krishisetu-logo-wordmark strong {
    font-size: 26px;
  }

}
/* =========================================================
   ADMIN HEADER — LARGE, CLEAR PAGE TITLE
========================================================= */

.admin-header {
  min-height: 115px;

  padding:
    28px 38px 25px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    25px;

  border-bottom:
    1px solid var(--border);

  background:
    var(--surface);

  position:
    relative;

  z-index:
    10;
}


/* LEFT SIDE */

.admin-header-left {
  display:
    flex;

  align-items:
    center;

  gap:
    18px;

  min-width:
    0;
}


.admin-header-title {
  min-width:
    0;
}


.admin-header-title h1 {
  margin:
    0;

  color:
    var(--text);

  font-size:
    clamp(
      30px,
      3vw,
      44px
    );

  line-height:
    1.05;

  letter-spacing:
    -.045em;

  font-weight:
    950;
}


.admin-header-title p {
  max-width:
    720px;

  margin:
    8px 0 0;

  color:
    var(--muted);

  font-size:
    13px;

  line-height:
    1.55;

  font-weight:
    600;
}


/* MOBILE MENU */

.admin-mobile-menu {
  display:
    none;

  width:
    44px;

  height:
    44px;

  flex:
    0 0 44px;

  align-items:
    center;

  justify-content:
    center;

  border:
    1px solid var(--border);

  border-radius:
    11px;

  color:
    var(--text);

  background:
    var(--surface);

  cursor:
    pointer;
}


/* RIGHT SIDE */

.admin-header-actions {
  display:
    flex;

  align-items:
    center;

  gap:
    10px;

  flex:
    0 0 auto;
}


/* LANGUAGE */

.admin-language-selector {
  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  min-height:
    42px;

  padding:
    0 11px;

  border:
    1px solid var(--border);

  border-radius:
    10px;

  color:
    var(--muted);

  background:
    var(--surface);

  box-shadow:
    0 3px 12px rgba(0,0,0,.03);
}


.admin-language-selector svg {
  flex:
    0 0 auto;

  color:
    var(--primary);
}


.admin-language-selector select {
  border:
    0;

  outline:
    none;

  color:
    var(--text);

  background:
    transparent;

  font-size:
    11px;

  font-weight:
    800;

  cursor:
    pointer;
}


/* REFRESH */

.admin-header-refresh {
  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  min-height:
    42px;

  padding:
    0 13px;

  border:
    1px solid var(--border);

  border-radius:
    10px;

  color:
    var(--text);

  background:
    var(--surface);

  font-size:
    11px;

  font-weight:
    850;

  cursor:
    pointer;

  transition:
    transform .18s ease,
    background .18s ease,
    border-color .18s ease;
}


.admin-header-refresh:hover {
  transform:
    translateY(-1px);

  background:
    var(--surface-soft);

  border-color:
    var(--primary);
}


.admin-header-refresh:disabled {
  opacity:
    .65;

  cursor:
    not-allowed;

  transform:
    none;
}


