/* =========================================================
   ADMIN PROCUREMENT — CLEAR PRIMARY ACTIONS
========================================================= */

.admin-procurement-page .add-center-button,
.admin-procurement-page .edit-center-button,
.admin-procurement-page button[class*="add-center"],
.admin-procurement-page button[class*="edit-center"] {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-height: 46px;
  padding: 0 16px;

  border: 1px solid transparent;
  border-radius: 11px;

  font-size: 12px;
  font-weight: 900;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}


/* Add Center = strongest action */

.admin-procurement-page .add-center-button,
.admin-procurement-page button[class*="add-center"] {
  color: #ffffff !important;

  background:
    linear-gradient(
      135deg,
      #18a45d,
      #087441
    ) !important;

  box-shadow:
    0 9px 22px rgba(24,164,93,.20) !important;
}


.admin-procurement-page .add-center-button:hover,
.admin-procurement-page button[class*="add-center"]:hover {
  transform: translateY(-2px);

  box-shadow:
    0 13px 28px rgba(24,164,93,.28) !important;
}


/* Edit Center = clearly visible secondary action */

