.admin-settings-page .admin-settings-success {
  min-height: 58px;

  padding: 12px 16px;

  margin-bottom: 18px;

  border-radius: 13px;

  display: flex;

  align-items: center;

  gap: 11px;
}


.admin-settings-page .admin-settings-error {
  border:
    1px solid #efb9b9;

  background:
    #fff4f4;

  color: #a62d2d;
}


.admin-settings-page .admin-settings-success {
  border:
    1px solid #a9ddbf;

  background:
    #f0fbf5;

  color: #167a4c;
}


.admin-settings-page .admin-settings-error strong,
.admin-settings-page .admin-settings-success span {
  font-size: 13px !important;

  font-weight: 850 !important;
}


.admin-settings-page .admin-settings-error div {
  display: grid;

  gap: 3px;
}


.admin-settings-page .admin-settings-error div span {
  font-size: 11px;

  font-weight: 650;
}


/* =========================================================
   SYSTEM STATUS
========================================================= */

.admin-settings-page .admin-settings-status-card {
  position: relative;

  display: flex;

  align-items: center;

  gap: 16px;

  padding: 19px;

  margin-bottom: 22px;

  border:
    1px solid var(--border);

  border-radius: 18px;

  background: var(--surface);

  box-shadow:
    0 8px 26px rgba(0,0,0,.045);

  overflow: hidden;
}


.admin-settings-page .admin-settings-status-card::before {
  content: "";

  position: absolute;

  inset:
    0 0 auto 0;

  height: 4px;

  background:
    linear-gradient(
      90deg,
      #18a45d,
      #169fe5,
      #7759db
    );
}


.admin-settings-page .admin-settings-status-icon {
  width: 48px;

  height: 48px;

  flex: 0 0 48px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 14px;

  color: #1598c5;

  background:
    #eaf7fc;

  border:
    1px solid #bfe1ed;
}


.admin-settings-page .admin-settings-status-copy {
  min-width: 0;

  flex: 1;
}


.admin-settings-page .admin-settings-status-copy h3 {
  margin: 4px 0 5px;

  font-size: 20px !important;

  line-height: 1.2 !important;

  font-weight: 950 !important;

  color: var(--text);
}


.admin-settings-page .admin-settings-status-copy p {
  margin: 0;

  font-size: 12px !important;

  line-height: 1.55 !important;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-settings-status-badge {
  display: inline-flex;

  align-items: center;

  gap: 7px;

  flex: 0 0 auto;

  min-height: 36px;

  padding:
    0 11px;

  border-radius: 10px;

  font-size: 10px !important;

  font-weight: 950 !important;

  letter-spacing: .06em;
}


.admin-settings-page .admin-settings-status-badge span {
  width: 8px;

  height: 8px;

  border-radius: 50%;
}


.admin-settings-page .admin-settings-status-badge.active {
  color: #168653;

  background: #eaf9f0;

  border:
    1px solid #bde4ca;
}


.admin-settings-page .admin-settings-status-badge.active span {
  background: #18a45d;

  box-shadow:
    0 0 0 4px rgba(24,164,93,.12);
}


.admin-settings-page .admin-settings-status-badge.paused {
  color: #a06c0e;

  background: #fff7e7;

  border:
    1px solid #ecd494;
}


.admin-settings-page .admin-settings-status-badge.paused span {
  background: #d89620;
}


.admin-settings-page .admin-settings-status-badge.warning {
  color: #aa3535;

  background: #fff0f0;

  border:
    1px solid #e9bcbc;
}


.admin-settings-page .admin-settings-status-badge.warning span {
  background: #c64444;
}


/* =========================================================
   MAIN SETTINGS GRID
========================================================= */

.admin-settings-page .admin-settings-grid {
  display: grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  gap: 20px;

  align-items: start;
}


/* =========================================================
   SETTINGS SECTION CARD
========================================================= */

.admin-settings-page .admin-settings-section {
  position: relative;

  border:
    1px solid var(--border);

  border-radius: 18px;

  background: var(--surface);

  box-shadow:
    0 8px 28px rgba(0,0,0,.045);

  overflow: hidden;

  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;
}


.admin-settings-page .admin-settings-section:hover {
  transform:
    translateY(-2px);

  border-color:
    rgba(40,156,196,.25);

  box-shadow:
    0 14px 34px rgba(0,0,0,.07);
}


/* Header */

.admin-settings-page .admin-settings-section-header {
  display: flex;

  align-items: flex-start;

  gap: 13px;

  padding:
    20px 20px 16px;

  border-bottom:
    1px solid var(--border);
}


.admin-settings-page .admin-settings-section-icon {
  width: 43px;

  height: 43px;

  flex: 0 0 43px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;
}


.admin-settings-page .admin-settings-section-icon.blue {
  color: #1598c5;

  background: #eaf7fc;

  border:
    1px solid #c2e4ef;
}


.admin-settings-page .admin-settings-section-icon.green {
  color: #158653;

  background: #edf9f2;

  border:
    1px solid #c5e7d1;
}


.admin-settings-page .admin-settings-section-icon.gold {
  color: #a97111;

  background: #fff8e9;

  border:
    1px solid #efdca3;
}


.admin-settings-page .admin-settings-section-icon.purple {
  color: #7658cf;

  background: #f3efff;

  border:
    1px solid #dcd2fb;
}


.admin-settings-page .admin-settings-section-header > div:last-child {
  min-width: 0;
}


.admin-settings-page .admin-settings-section-header > div:last-child > span {
  font-size: 10px !important;

  line-height: 1.2;

  font-weight: 950 !important;

  letter-spacing: .14em;

  color: var(--muted);
}


.admin-settings-page .admin-settings-section-header h3 {
  margin:
    4px 0 5px;

  font-size: 18px !important;

  line-height: 1.2 !important;

  font-weight: 950 !important;

  color: var(--text);
}


.admin-settings-page .admin-settings-section-header p {
  margin: 0;

  font-size: 12px !important;

  line-height: 1.5 !important;

  font-weight: 650 !important;

  color: var(--muted);
}


/* Body */

.admin-settings-page .admin-settings-section-body {
  padding:
    6px 20px 18px;
}


/* =========================================================
   TOGGLES
========================================================= */

.admin-settings-page .admin-setting-toggle {
  display: grid;

  grid-template-columns:
    auto 1fr;

  grid-template-rows:
    auto auto;

  column-gap: 12px;

  align-items: center;

  padding:
    14px 0;

  cursor: pointer;
}


.admin-settings-page .admin-setting-toggle > input {
  position: absolute;

  opacity: 0;

  pointer-events: none;
}


.admin-settings-page .admin-setting-toggle-track {
  grid-row:
    1 / span 2;

  width: 48px;

  height: 28px;

  display: flex;

  align-items: center;

  padding: 3px;

  border-radius: 999px;

  background:
    #b7c3c8;

  transition:
    background .2s ease,
    box-shadow .2s ease;
}


.admin-settings-page .admin-setting-toggle-track > span {
  width: 22px;

  height: 22px;

  border-radius: 50%;

  background:
    #ffffff;

  box-shadow:
    0 2px 5px rgba(0,0,0,.15);

  transition:
    transform .2s ease;
}


.admin-settings-page .admin-setting-toggle > input:checked
  + .admin-setting-toggle-track {
  background:
    #18a45d;

  box-shadow:
    0 0 0 4px rgba(24,164,93,.10);
}


.admin-settings-page .admin-setting-toggle > input:checked
  + .admin-setting-toggle-track
  > span {
  transform:
    translateX(20px);
}


.admin-settings-page .admin-setting-toggle strong {
  font-size: 14px !important;

  line-height: 1.3 !important;

  font-weight: 900 !important;

  color: var(--text);
}


.admin-settings-page .admin-setting-toggle > div > span {
  display: block;

  margin-top: 4px;

  font-size: 11px !important;

  line-height: 1.5 !important;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-setting-toggle.disabled {
  opacity: .5;

  cursor:
    not-allowed;
}


/* =========================================================
   NUMBER SETTINGS
========================================================= */

.admin-settings-page .admin-setting-number-row {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  padding:
    14px 0;
}


.admin-settings-page .admin-setting-number-row > div:first-child {
  min-width: 0;
}


.admin-settings-page .admin-setting-number-row strong {
  display: block;

  font-size: 14px !important;

  line-height: 1.3;

  font-weight: 900 !important;

  color: var(--text);
}


.admin-settings-page .admin-setting-number-row > div:first-child > span {
  display: block;

  margin-top: 4px;

  max-width: 440px;

  font-size: 11px !important;

  line-height: 1.5;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-setting-number {
  display: flex;

  align-items: center;

  flex: 0 0 auto;

  min-width: 110px;

  border:
    1px solid var(--border);

  border-radius: 10px;

  overflow: hidden;

  background:
    var(--surface);
}


.admin-settings-page .admin-setting-number input {
  width: 72px;

  min-height: 42px;

  padding:
    0 10px;

  border: 0;

  outline: 0;

  color: var(--text);

  background:
    transparent;

  font-size: 13px !important;

  font-weight: 900 !important;
}


.admin-settings-page .admin-setting-number > span {
  padding:
    0 9px 0 0;

  color:
    var(--muted);

  font-size: 10px !important;

  font-weight: 850 !important;

  white-space: nowrap;
}


/* =========================================================
   DIVIDERS
========================================================= */

.admin-settings-page .admin-settings-divider {
  height: 1px;

  margin:
    2px 0;

  background:
    var(--border);
}


/* =========================================================
   INFO CARDS
========================================================= */

.admin-settings-page .admin-settings-info-card {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin:
    10px 0;

  padding:
    13px;

  border:
    1px solid var(--border);

  border-radius: 12px;

  background:
    var(--surface-soft);
}


.admin-settings-page .admin-settings-info-icon {
  width: 33px;

  height: 33px;

  flex: 0 0 33px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color:
    var(--primary);

  background:
    rgba(22,159,229,.09);
}


.admin-settings-page .admin-settings-info-card strong {
  display: block;

  font-size: 13px !important;

  line-height: 1.3;

  font-weight: 900 !important;

  color: var(--text);
}


.admin-settings-page .admin-settings-info-card span {
  display: block;

  margin-top: 4px;

  font-size: 11px !important;

  line-height: 1.5;

  font-weight: 650 !important;

  color: var(--muted);
}


/* =========================================================
   LANGUAGE
========================================================= */

.admin-settings-page .admin-settings-language-row {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  padding:
    14px 0;
}


.admin-settings-page .admin-settings-language-row strong {
  display: block;

  font-size: 14px !important;

  font-weight: 900 !important;

  color: var(--text);
}


.admin-settings-page .admin-settings-language-row span {
  display: block;

  margin-top: 4px;

  font-size: 11px !important;

  line-height: 1.45;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-settings-language-row select {
  min-height: 42px;

  min-width: 125px;

  padding:
    0 11px;

  border:
    1px solid var(--border);

  border-radius: 10px;

  color: var(--text);

  background:
    var(--surface);

  font-size: 12px !important;

  font-weight: 850 !important;

  outline: none;
}


/* =========================================================
   MAINTENANCE WARNING
========================================================= */

.admin-settings-page .admin-settings-warning-card {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 14px;

  padding:
    13px;

  border:
    1px solid #efd3a4;

  border-radius: 12px;

  color:
    #93610e;

  background:
    #fff8eb;
}


.admin-settings-page .admin-settings-warning-card strong {
  display: block;

  font-size: 12px !important;

  font-weight: 900 !important;
}


.admin-settings-page .admin-settings-warning-card span {
  display: block;

  margin-top: 4px;

  font-size: 10px !important;

  line-height: 1.5;

  font-weight: 650 !important;
}


/* =========================================================
   SAVE BAR
========================================================= */

.admin-settings-page .admin-settings-save-bar {
  position: sticky;

  bottom: 12px;

  z-index: 20;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  margin-top: 23px;

  padding:
    14px 16px;

  border:
    1px solid var(--border);

  border-radius: 16px;

  background:
    color-mix(
      in srgb,
      var(--surface) 94%,
      transparent
    );

  backdrop-filter:
    blur(14px);

  box-shadow:
    0 14px 35px rgba(0,0,0,.10);
}


.admin-settings-page .admin-settings-save-bar.has-changes {
  border-color:
    rgba(22,159,229,.35);

  box-shadow:
    0 15px 38px rgba(22,159,229,.12);
}


.admin-settings-page .admin-settings-save-bar > div:first-child {
  display: flex;

  align-items: center;

  gap: 11px;

  min-width: 0;
}


.admin-settings-page .admin-settings-save-icon {
  width: 38px;

  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  color: #1598c5;

  background:
    #eaf7fc;
}


.admin-settings-page .admin-settings-save-bar strong {
  display: block;

  font-size: 13px !important;

  font-weight: 950 !important;

  color: var(--text);
}


.admin-settings-page .admin-settings-save-bar > div:first-child span {
  display: block;

  margin-top: 3px;

  font-size: 10px !important;

  line-height: 1.4;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-settings-save-actions {
  display: flex;

  align-items: center;

  gap: 8px;

  flex: 0 0 auto;
}


.admin-settings-page .admin-settings-save-actions button {
  min-height: 42px;

  padding:
    0 13px;

  border-radius: 10px;

  font-size: 11px !important;

  font-weight: 900 !important;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}


.admin-settings-page .admin-settings-save-actions button:hover {
  transform:
    translateY(-2px);
}


.admin-settings-page .admin-settings-discard {
  border:
    1px solid var(--border);

  color:
    var(--text);

  background:
    var(--surface);
}


.admin-settings-page .admin-settings-save {
  border:
    2px solid #16894f;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #1ca965,
      #087744
    );

  box-shadow:
    0 7px 18px rgba(24,164,93,.18);
}


.admin-settings-page .admin-settings-save:disabled {
  opacity: .45;

  cursor:
    not-allowed;

  transform:
    none;
}


.admin-settings-page .admin-settings-reset {
  border:
    1px solid #d9aaaa;

  color:
    #a43737;

  background:
    #fff5f5;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark .admin-settings-page .admin-settings-hero h2,
body.dark .admin-settings-page .admin-settings-hero h2 {
  background:
    linear-gradient(
      90deg,
      #57daa0,
      #58caee,
      #ae9aff
    );

  -webkit-background-clip: text;

  background-clip: text;

  -webkit-text-fill-color: transparent;
}


html.dark .admin-settings-page .admin-settings-section,
body.dark .admin-settings-page .admin-settings-section,
html.dark .admin-settings-page .admin-settings-status-card,
body.dark .admin-settings-page .admin-settings-status-card {
  background:
    #102730;

  border-color:
    #294650;

  box-shadow:
    0 12px 32px rgba(0,0,0,.22);
}


html.dark .admin-settings-page .admin-settings-status-icon,
body.dark .admin-settings-page .admin-settings-status-icon {
  color:
    #8ddbf4;

  background:
    #153943;

  border-color:
    #315b69;
}


html.dark .admin-settings-page .admin-setting-number,
body.dark .admin-settings-page .admin-setting-number,
html.dark .admin-settings-page .admin-settings-language-row select,
body.dark .admin-settings-page .admin-settings-language-row select {
  background:
    #112a33;

  border-color:
    #35515b;

  color:
    #edf7f9;
}


html.dark .admin-settings-page .admin-settings-info-card,
body.dark .admin-settings-page .admin-settings-info-card {
  background:
    #122d36;

  border-color:
    #31505a;
}


html.dark .admin-settings-page .admin-settings-warning-card,
body.dark .admin-settings-page .admin-settings-warning-card {
  color:
    #f4c875;

  background:
    #352b1a;

  border-color:
    #665329;
}


html.dark .admin-settings-page .admin-settings-save-bar,
body.dark .admin-settings-page .admin-settings-save-bar {
  background:
    rgba(16,39,48,.94);

  border-color:
    #35535e;
}


html.dark .admin-settings-page .admin-settings-discard,
body.dark .admin-settings-page .admin-settings-discard {
  background:
    #112a33;

  border-color:
    #35515b;

  color:
    #edf7f9;
}


html.dark .admin-settings-page .admin-settings-reset,
body.dark .admin-settings-page .admin-settings-reset {
  background:
    #351d20;

  border-color:
    #66363b;

  color:
    #ffaaaa;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 950px) {

  .admin-settings-page .admin-settings-grid {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 700px) {

  .admin-settings-page .admin-settings-hero {
    flex-direction: column;

    align-items: flex-start;
  }


  .admin-settings-page .admin-settings-status-card {
    align-items: flex-start;

    flex-wrap: wrap;
  }


  .admin-settings-page .admin-settings-status-badge {
    margin-left: 64px;
  }


  .admin-settings-page .admin-settings-save-bar {
    flex-direction: column;

    align-items: stretch;
  }


  .admin-settings-page .admin-settings-save-actions {
    flex-wrap: wrap;
  }


  .admin-settings-page .admin-settings-save-actions button {
    flex: 1;
  }

}


@media (max-width: 520px) {

  .admin-settings-page .admin-settings-section-header {
    padding:
      16px 15px 13px;
  }


  .admin-settings-page .admin-settings-section-body {
    padding:
      4px 15px 14px;
  }


  .admin-settings-page .admin-setting-number-row,
  .admin-settings-page .admin-settings-language-row {
    align-items: flex-start;

    flex-direction: column;

    gap: 10px;
  }


  .admin-settings-page .admin-setting-number {
    width: 100%;
  }


  .admin-settings-page .admin-setting-number input {
    width: 100%;
  }


  .admin-settings-page .admin-settings-language-row select {
    width: 100%;
  }


  .admin-settings-page .admin-settings-status-badge {
    margin-left: 0;
  }

}

