    linear-gradient(
      90deg,
      #168b57 0%,
      #1598c5 55%,
      #5969b9 100%
    );

  -webkit-background-clip: text;
  background-clip: text;

  -webkit-text-fill-color: transparent;
}


.admin-dashboard-page .admin-dashboard-hero p {
  max-width: 760px;

  margin-top: 10px;

  font-size: 15px !important;

  line-height: 1.65 !important;

  font-weight: 650 !important;

  color: var(--muted);
}


/* =========================================================
   KPI CARDS
========================================================= */

.admin-dashboard-page .admin-dashboard-kpi {
  min-height: 108px;

  padding: 17px 18px;
}


.admin-dashboard-page .admin-dashboard-kpi strong {
  font-size: 28px !important;

  line-height: 1 !important;

  font-weight: 950 !important;
}


.admin-dashboard-page .admin-dashboard-kpi span {
  display: block;

  margin-top: 7px;

  font-size: 13px !important;

  line-height: 1.3 !important;

  font-weight: 800 !important;

  color: var(--muted);
}


/* Keep KPI colours subtle */
.admin-dashboard-page .admin-dashboard-kpi.blue,
.admin-dashboard-page .admin-dashboard-kpi.purple,
.admin-dashboard-page .admin-dashboard-kpi.gold,
.admin-dashboard-page .admin-dashboard-kpi.green,
.admin-dashboard-page .admin-dashboard-kpi.orange,
.admin-dashboard-page .admin-dashboard-kpi.teal {
  box-shadow:
    0 7px 20px rgba(0,0,0,.035);
}


/* =========================================================
   GENERAL PANEL HEADINGS
========================================================= */

.admin-dashboard-page .admin-dashboard-panel-header h3 {
  margin-top: 4px;

  font-size: 19px !important;

  line-height: 1.25 !important;

  font-weight: 950 !important;

