  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background:
    rgba(74, 145, 86, 0.08);
}

.journey-node span {
  display: block;

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.1em;

  opacity: 0.46;
}

.journey-node strong {
  display: block;

  margin-top: 2px;

  font-size: 14px;
  font-weight: 800;
}


/* =========================================================
   NODE POSITIONS
========================================================= */

.journey-farm {
  left: 20%;
  top: 15%;

  transform: translateX(-50%);
}

.journey-token {
  right: 10%;
  top: 25%;
}

.journey-weighing {
  right: 10%;
  left: auto;
  top: 65%;
}

.journey-center-node {
  left: 50%;
  bottom: 4%;

  transform: translateX(-50%);
}

.journey-payment {
  left: auto;
  right: 59%;
  top: 70%;
}


/* =========================================================
   FLOATING PULSES
========================================================= */

.journey-pulse {
  position: absolute;

  width: 8px;
  height: 8px;

  border-radius: 50%;

  background: currentColor;

  box-shadow:
    0 0 0 7px rgba(75, 145, 87, 0.045);
}

.pulse-one {
  left: 19%;
  top: 29%;

  color: #6da679;

  animation:
    pulseFloat 3s ease-in-out infinite;
}

.pulse-two {
  right: 18%;
  top: 44%;

  color: #c9a657;

  animation:
    pulseFloat 3.8s ease-in-out infinite;
}

.pulse-three {
  left: 25%;
  bottom: 23%;

  color: #648bb7;

  animation:
    pulseFloat 4.2s ease-in-out infinite;
}


/* =========================================================
   CONTENT
   Text is intentionally above the journey.
========================================================= */

.landing-hero-content {
  position: relative;

  z-index: 5;

  width: min(650px, 57%);

  padding:
    72px 0
    72px 5vw;

  margin-left: 0;
}


/* Keep KrishiSetu logo and wordmark together */

.landing-hero-logo {
  position: relative;

  z-index: 7;

  white-space: nowrap;

  margin-bottom: 18px;
}


/* =========================================================
   HERO TEXT
========================================================= */

.landing-hero-content h1 {
  position: relative;
  z-index: 7;

  max-width: 620px;

  margin-bottom: 22px;
}

.landing-hero-description {
  position: relative;
  z-index: 7;

  max-width: 570px;
}


/* =========================================================
   HERO ACTIONS
========================================================= */

.landing-hero-actions {
  position: relative;
  z-index: 8;
}


/* =========================================================
   HERO POINTS
========================================================= */

.landing-hero-points {
  position: relative;
  z-index: 8;
}


/* =========================================================
   ANIMATION
========================================================= */

@keyframes journeyRotate {

  from {
    transform:
      translate(-50%, -50%)
      rotate(0deg);
  }

  to {
    transform:
      translate(-50%, -50%)
      rotate(360deg);
  }

}

@keyframes journeyRotateReverse {

  from {
    transform:
      translate(-50%, -50%)
      rotate(360deg);
  }

  to {
    transform:
      translate(-50%, -50%)
      rotate(0deg);
  }

}

@keyframes pulseFloat {

  0%,
  100% {
    transform: scale(1);
    opacity: 0.4;
  }

  50% {
    transform: scale(1.7);
    opacity: 0.9;
  }

}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1400px) {

  .landing-hero {
    min-height: 800px;
  }

  .landing-hero-content {
    width: 54%;

    padding-left: 6vw;
  }

  .landing-hero-visual {
    left: 57%;
    width: 860px;
    height: 860px;
  }

}


/* =========================================================
   DESKTOP / LAPTOP
========================================================= */

@media (max-width: 1250px) {

  .landing-hero {
    min-height: 740px;
  }

  .landing-hero-content {
    width: 55%;

    padding-left: 4vw;
  }

  .landing-hero-visual {
    left: 59%;

    width: 720px;
    height: 720px;

    opacity: 0.78;
  }

}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1000px) {

  .landing-hero {
    min-height: 820px;
    align-items: flex-start;
  }

  .landing-hero-content {
    width: 72%;

    padding:
      55px
      5vw
      120px;
  }

  .landing-hero-visual {
    left: 64%;
    top: 58%;

    width: 640px;
    height: 640px;

    opacity: 0.42;
  }

  .landing-hero-description {
    max-width: 650px;
  }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 700px) {

  .landing-hero {
    min-height: 920px;

    align-items: flex-start;

    text-align: center;
  }

  .landing-hero-content {
    width: 100%;

    padding:
      40px
      22px
      180px;
  }

  .landing-hero-logo {
    display: flex;
    justify-content: center;
  }

  .landing-hero-actions {
    justify-content: center;
    flex-wrap: wrap;
  }

  .landing-hero-points {
    justify-content: center;
    flex-wrap: wrap;
  }

  .landing-hero-visual {
    left: 50%;
    top: auto;
    bottom: -155px;

    width: 640px;
    height: 640px;

    opacity: 0.28;

    transform: translateX(-50%);
  }

  .journey-node {
    transform: scale(0.82);
  }

  .journey-farm,
  .journey-center-node {
    transform:
      translateX(-50%)
      scale(0.82);
  }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

  .landing-hero {
    min-height: 850px;
  }

  .landing-hero-content {
    padding:
      32px
      16px
      150px;
  }

  .landing-hero-visual {
    width: 560px;
    height: 560px;

    bottom: -130px;
  }

  .journey-node {
    min-width: 138px;

    padding: 9px 10px;
  }

  .journey-node-icon {
    width: 38px;
    height: 38px;

    flex-basis: 38px;
  }

}

/* =========================================================
   KRISHISETU PREMIUM LANDING EFFECTS
   IMPORTANT:
   This block does NOT change the position of the main
   .landing-hero-visual / journey animation.
========================================================= */


/* =========================================================
   GLOBAL SMOOTHNESS
========================================================= */

html {
  scroll-behavior: smooth;
}

.landing-page {
  position: relative;
  overflow-x: hidden;
}

.landing-page a,
.landing-page button {
  -webkit-tap-highlight-color: transparent;
}

.landing-page a,
.landing-page button,
.landing-page input,
.landing-page select {
  transition:
    color 0.25s ease,
    background-color 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.3s ease,
    transform 0.3s cubic-bezier(.2,.8,.2,1),
    opacity 0.25s ease;
}


/* =========================================================
   HEADER
========================================================= */

.landing-header {
  position: relative;
  z-index: 50;

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  background:
    linear-gradient(
      to bottom,
      rgba(255,255,255,0.90),
      rgba(255,255,255,0.76)
    );

  border-bottom:
    1px solid rgba(40,75,48,0.07);
}

.landing-brand {
  transition:
    transform 0.35s cubic-bezier(.2,.8,.2,1),
    filter 0.35s ease;
}

.landing-brand:hover {
  transform: translateY(-2px);
  filter:
    drop-shadow(
      0 8px 16px
      rgba(47,108,57,0.12)
    );
}

.landing-nav a {
  position: relative;
}

.landing-nav a::after {
  content: "";

  position: absolute;

  left: 50%;
  bottom: -7px;

  width: 0;
  height: 2px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #4f9158,
      #9dba69
    );

  transform: translateX(-50%);

  transition:
    width 0.3s ease;
}

.landing-nav a:hover::after {
  width: 70%;
}


/* =========================================================
   HERO
========================================================= */

.landing-hero {
  position: relative;
  isolation: isolate;
}


/* subtle top atmospheric wash */

.landing-hero::before {
  content: "";

  position: absolute;

  inset:
    0 0 auto 0;

  height: 260px;

  z-index: 0;

  pointer-events: none;

  background:
    linear-gradient(
      to bottom,
      rgba(255,255,255,0.76),
      transparent
    );
}


/* =========================================================
   HERO BADGE
========================================================= */

.landing-hero-badge {
  position: relative;

  overflow: hidden;

  border:
    1px solid rgba(78,137,85,0.16);

  background:
    rgba(255,255,255,0.70);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 10px 30px
    rgba(53,99,59,0.055);

  animation:
    heroFadeUp 0.8s cubic-bezier(.2,.8,.2,1) both;
}

.landing-hero-badge::after {
  content: "";

  position: absolute;

  top: 0;
  left: -120%;

  width: 75%;
  height: 100%;

  background:
    linear-gradient(
      105deg,
      transparent,
      rgba(255,255,255,0.58),
      transparent
    );

  transform: skewX(-18deg);

  animation:
    badgeShine 5s ease-in-out 1.5s infinite;
}

.landing-hero-badge:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 36px
    rgba(53,99,59,0.09);
}


/* =========================================================
   HERO LOGO
========================================================= */

.landing-hero-logo {
  animation:
    heroLogoEnter 0.9s cubic-bezier(.2,.8,.2,1) 0.08s both;
}


/* =========================================================
   HERO HEADING
========================================================= */

.landing-hero-content h1 {
  animation:
    heroFadeUp 0.9s cubic-bezier(.2,.8,.2,1) 0.16s both;

  letter-spacing:
    -0.035em;
}

.landing-hero-content h1 span {
  display: inline-block;

  background:
    linear-gradient(
      120deg,
      #376b40 0%,
      #57915b 42%,
      #7eaa61 75%,
      #4c8655 100%
    );

  background-size: 180% auto;

  -webkit-background-clip: text;
  background-clip: text;

  -webkit-text-fill-color: transparent;

  animation:
    gradientText 8s ease-in-out infinite;
}


/* =========================================================
   HERO DESCRIPTION
========================================================= */

.landing-hero-description {
  animation:
    heroFadeUp 0.9s cubic-bezier(.2,.8,.2,1) 0.26s both;
}


/* =========================================================
   BUTTONS
========================================================= */

.landing-primary-button,
.landing-secondary-button {
  position: relative;

  overflow: hidden;

  isolation: isolate;
}

.landing-primary-button::before,
.landing-secondary-button::before {
  content: "";

  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      115deg,
      transparent 20%,
      rgba(255,255,255,0.28) 48%,
      transparent 76%
    );

  transform:
    translateX(-120%);

  transition:
    transform 0.65s cubic-bezier(.2,.8,.2,1);

  z-index: -1;
}

.landing-primary-button:hover::before,
.landing-secondary-button:hover::before {
  transform:
    translateX(120%);
}

.landing-primary-button:hover {
  transform:
    translateY(-4px);

  box-shadow:
    0 15px 32px
    rgba(52,112,60,0.18);
}

.landing-secondary-button:hover {
  transform:
    translateY(-4px);

  box-shadow:
    0 12px 28px
    rgba(45,75,51,0.08);
}

.landing-primary-button:active,
.landing-secondary-button:active {
  transform:
    translateY(-1px)
    scale(0.985);
}


/* =========================================================
   HERO POINTS
========================================================= */

.landing-hero-points > div {
  transition:
    transform 0.3s ease,
    opacity 0.3s ease;
}

.landing-hero-points > div:hover {
  transform:
    translateX(5px);
}


/* =========================================================
   MAIN CIRCLE
   Position is intentionally untouched.
========================================================= */

.landing-hero-visual {
  pointer-events: none;
}


/* atmospheric glow animation only */

.landing-visual-glow {
  animation:
    visualGlow 7s ease-in-out infinite;
}


/* orbit emphasis */

.orbit-main {
  box-shadow:
    0 0 45px
    rgba(72,136,82,0.045);

  animation:
    journeyRotate 30s linear infinite,
    orbitPulse 6s ease-in-out infinite;
}

.orbit-inner {
  animation:
    journeyRotateReverse 20s linear infinite,
    orbitInnerPulse 5s ease-in-out infinite;
}


/* =========================================================
   JOURNEY CENTER
========================================================= */

.journey-center {
  transition:
    box-shadow 0.4s ease,
    transform 0.4s cubic-bezier(.2,.8,.2,1);
}

.journey-center:hover {
  transform:
    translate(-50%, -50%)
    scale(1.035);

  box-shadow:
    0 30px 80px
    rgba(32,72,40,0.13),
    0 0 0 20px
    rgba(75,145,87,0.035);
}

.journey-center-icon {
  animation:
    centerBreath 4s ease-in-out infinite;
}


/* =========================================================
   JOURNEY NODES
========================================================= */

.journey-node {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.journey-node:hover {
  transform:
    translateY(-6px)
    scale(1.025);

  box-shadow:
    0 22px 48px
    rgba(35,69,42,0.12);

  border-color:
    rgba(72,136,82,0.18);
}

.journey-node-icon {
  transition:
    transform 0.35s ease,
    background-color 0.35s ease;
}

.journey-node:hover .journey-node-icon {
  transform:
    rotate(-5deg)
    scale(1.08);

  background:
    rgba(74,145,86,0.13);
}


/* =========================================================
   PULSES
========================================================= */

.journey-pulse {
  animation:
    journeyPulse 3.6s ease-in-out infinite;
}

.pulse-two {
  animation-delay:
    -1.2s;
}

.pulse-three {
  animation-delay:
    -2.35s;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.landing-trust-strip {
  position: relative;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.82),
      rgba(248,251,247,0.92)
    );

  border-top:
    1px solid rgba(53,91,61,0.055);

  border-bottom:
    1px solid rgba(53,91,61,0.055);
}

.landing-trust-strip > div {
  transition:
    transform 0.35s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.35s ease,
    background-color 0.35s ease;
}

.landing-trust-strip > div:hover {
  transform:
    translateY(-4px);

  background:
    rgba(255,255,255,0.78);

  box-shadow:
    0 10px 28px
    rgba(48,84,53,0.055);
}


/* =========================================================
   SECTION HEADINGS
========================================================= */

.landing-section-heading > span,
.landing-portals-intro > span,
.landing-support-card span,
.landing-final-cta-content > span {
  letter-spacing:
    0.16em;

  transition:
    letter-spacing 0.35s ease;
}

.landing-section-heading:hover > span {
  letter-spacing:
    0.21em;
}

.landing-section-heading h2,
.landing-portals-intro h2,
.landing-final-cta-content h2 {
  letter-spacing:
    -0.035em;
}

.landing-section-heading em,
.landing-portals-intro em,
.landing-final-cta-content em {
  background:
    linear-gradient(
      120deg,
      #477e4e,
      #6d9d5f
    );

  -webkit-background-clip: text;
  background-clip: text;

  -webkit-text-fill-color: transparent;

  font-style: normal;
}


/* =========================================================
   PURPOSE CARDS
========================================================= */

.purpose-card {
  position: relative;

  overflow: hidden;

  transition:
    transform 0.45s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.45s ease,
    border-color 0.35s ease;
}

.purpose-card::before {
  content: "";

  position: absolute;

  width: 180px;
  height: 180px;

  right: -85px;
  top: -85px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(255,255,255,0.34),
      transparent 68%
    );

  opacity: 0;

  transition:
    opacity 0.4s ease,
    transform 0.5s ease;
}

.purpose-card:hover {
  transform:
    translateY(-9px);

  box-shadow:
    0 22px 48px
    rgba(39,71,43,0.11);
}

.purpose-card:hover::before {
  opacity: 1;
  transform:
    scale(1.25);
}

.purpose-card-icon {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1);
}

.purpose-card:hover .purpose-card-icon {
  transform:
    translateY(-3px)
    rotate(-5deg)
    scale(1.06);
}

.purpose-card-number {
  transition:
    transform 0.4s ease,
    opacity 0.4s ease;
}

.purpose-card:hover .purpose-card-number {
  transform:
    translateX(4px);
}


/* =========================================================
   PROCESS STEPS
========================================================= */

.landing-process-step {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    opacity 0.4s ease;
}

.landing-process-step:hover {
  transform:
    translateY(-7px);
}

.process-step-icon {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.35s ease;
}

.landing-process-step:hover .process-step-icon {
  transform:
    scale(1.08)
    rotate(-4deg);

  box-shadow:
    0 12px 26px
    rgba(42,73,46,0.09);
}

.landing-process-connector {
  transition:
    transform 0.35s ease,
    opacity 0.35s ease;
}

.landing-process-track:hover .landing-process-connector {
  opacity: 0.7;
}


/* =========================================================
   STATS FLOW
========================================================= */

.landing-stats-strip > div:not(.stats-arrow) {
  transition:
    transform 0.3s ease,
    opacity 0.3s ease;
}

.landing-stats-strip > div:not(.stats-arrow):hover {
  transform:
    translateY(-4px);
}

.stats-arrow {
  animation:
    flowArrow 2.8s ease-in-out infinite;
}

.stats-arrow:nth-of-type(2) {
  animation-delay: 0.2s;
}

.stats-arrow:nth-of-type(4) {
  animation-delay: 0.4s;
}

.stats-arrow:nth-of-type(6) {
  animation-delay: 0.6s;
}


/* =========================================================
   PORTAL CARDS
========================================================= */

.landing-portal-card {
  position: relative;

  overflow: hidden;

  transition:
    transform 0.5s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.5s ease,
    border-color 0.4s ease;
}

.landing-portal-card::before {
  content: "";

  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      125deg,
      transparent 20%,
      rgba(255,255,255,0.18) 48%,
      transparent 73%
    );

  transform:
    translateX(-125%);

  transition:
    transform 0.8s cubic-bezier(.2,.8,.2,1);

  pointer-events: none;
}

.landing-portal-card:hover {
  transform:
    translateY(-10px);

  box-shadow:
    0 28px 60px
    rgba(38,69,42,0.12);
}

.landing-portal-card:hover::before {
  transform:
    translateX(125%);
}

.portal-card-icon {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1);
}

.landing-portal-card:hover .portal-card-icon {
  transform:
    scale(1.08)
    rotate(-5deg);
}

.portal-card-action > div {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1);
}

.landing-portal-card:hover .portal-card-action > div {
  transform:
    translateX(6px);
}


/* =========================================================
   FEATURE CARDS
========================================================= */

.landing-feature-card {
  position: relative;

  overflow: hidden;

  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.4s ease,
    border-color 0.35s ease;
}

.landing-feature-card::after {
  content: "";

  position: absolute;

  width: 150px;
  height: 150px;

  right: -80px;
  bottom: -90px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(92,151,98,0.08),
      transparent 68%
    );

  opacity: 0;

  transition:
    opacity 0.4s ease,
    transform 0.5s ease;
}

.landing-feature-card:hover {
  transform:
    translateY(-7px);

  box-shadow:
    0 18px 42px
    rgba(38,70,42,0.09);
}

.landing-feature-card:hover::after {
  opacity: 1;
  transform:
    scale(1.25);
}

.landing-feature-icon {
  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1);
}

.landing-feature-card:hover .landing-feature-icon {
  transform:
    translateY(-3px)
    scale(1.07)
    rotate(-4deg);
}


/* =========================================================
   SUPPORT CARD
========================================================= */

.landing-support-card {
  position: relative;

  overflow: hidden;

  backdrop-filter:
    blur(14px);

  -webkit-backdrop-filter:
    blur(14px);

  transition:
    transform 0.45s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.45s ease;
}

.landing-support-card::after {
  content: "";

  position: absolute;

  width: 300px;
  height: 300px;

  right: -150px;
  top: -150px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(255,255,255,0.20),
      transparent 68%
    );

  pointer-events: none;
}

.landing-support-card:hover {
  transform:
    translateY(-5px);

  box-shadow:
    0 25px 58px
    rgba(38,70,42,0.10);
}

.landing-support-icon {
  transition:
    transform 0.45s cubic-bezier(.2,.8,.2,1);
}

.landing-support-card:hover .landing-support-icon {
  transform:
    scale(1.08)
    rotate(-5deg);
}


/* =========================================================
   FINAL CTA
========================================================= */

.landing-final-cta {
  position: relative;
  overflow: hidden;
}

.landing-final-cta::before {
  content: "";

  position: absolute;

  width: 500px;
  height: 500px;

  right: -160px;
  top: -180px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(255,255,255,0.08),
      transparent 70%
    );

  animation:
    finalOrb 8s ease-in-out infinite;

  pointer-events: none;
}

.landing-final-cta-actions a {
  position: relative;
  overflow: hidden;
}

.landing-final-cta-actions a::before {
  content: "";

  position: absolute;

  top: 0;
  left: -130%;

  width: 80%;
  height: 100%;

  background:
    linear-gradient(
      110deg,
      transparent,
      rgba(255,255,255,0.23),
      transparent
    );

  transform: skewX(-20deg);

  transition:
    transform 0.8s ease;
}

.landing-final-cta-actions a:hover::before {
  transform:
    translateX(270%)
    skewX(-20deg);
}

.landing-final-cta-actions a:hover {
  transform:
    translateY(-4px);
}


/* =========================================================
   FINAL CTA DECORATION
========================================================= */

.landing-final-cta-decoration > div {
  transition:
    transform 0.45s cubic-bezier(.2,.8,.2,1),
    opacity 0.4s ease;
}

.landing-final-cta-decoration > div:nth-child(1) {
  animation:
    decorationFloat 5s ease-in-out infinite;
}

.landing-final-cta-decoration > div:nth-child(2) {
  animation:
    decorationFloat 5s ease-in-out 1.1s infinite;
}

.landing-final-cta-decoration > div:nth-child(3) {
  animation:
    decorationFloat 5s ease-in-out 2.1s infinite;
}


/* =========================================================
   FOOTER
========================================================= */

.landing-footer-column a {
  position: relative;

  width: fit-content;
}

.landing-footer-column a::after {
  content: "";

  position: absolute;

  left: 0;
  bottom: -3px;

  width: 0;
  height: 1px;

  background:
    currentColor;

  opacity: 0.6;

  transition:
    width 0.3s ease;
}

.landing-footer-column a:hover::after {
  width: 100%;
}


/* =========================================================
   GENERAL KEYFRAMES
========================================================= */

@keyframes heroFadeUp {

  from {
    opacity: 0;
    transform:
      translateY(24px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}

@keyframes heroLogoEnter {

  from {
    opacity: 0;
    transform:
      translateY(18px)
      scale(0.94);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}

@keyframes badgeShine {

  0%,
  58%,
  100% {
    transform:
      translateX(-140%)
      skewX(-18deg);
  }

  72% {
    transform:
      translateX(230%)
      skewX(-18deg);
  }

}

@keyframes gradientText {

  0%,
  100% {
    background-position:
      0% 50%;
  }

  50% {
    background-position:
      100% 50%;
  }

}

@keyframes visualGlow {

  0%,
  100% {
    transform:
      scale(0.96);
    opacity:
      0.72;
  }

  50% {
    transform:
      scale(1.04);
    opacity:
      1;
  }

}

@keyframes orbitPulse {

  0%,
  100% {
    opacity:
      0.70;
  }

  50% {
    opacity:
      1;
  }

}

@keyframes orbitInnerPulse {

  0%,
  100% {
    opacity:
      0.48;
  }

  50% {
    opacity:
      0.82;
  }

}

@keyframes centerBreath {

  0%,
  100% {
    transform:
      scale(1);
  }

  50% {
    transform:
      scale(1.045);
  }

}

@keyframes journeyPulse {

  0%,
  100% {
    opacity:
      0.35;

    transform:
      scale(0.9);
  }

  50% {
    opacity:
      0.95;

    transform:
      scale(1.6);
  }

}

@keyframes flowArrow {

  0%,
  100% {
    opacity:
      0.45;

    transform:
      translateX(0);
  }

  50% {
    opacity:
      0.9;

    transform:
      translateX(4px);
  }

}

@keyframes finalOrb {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-18px, 14px)
      scale(1.08);
  }

}

@keyframes decorationFloat {

  0%,
  100% {
    transform:
      translateY(0)
      rotate(0deg);
  }

  50% {
    transform:
      translateY(-12px)
      rotate(2deg);
  }

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration:
      0.01ms !important;

    animation-iteration-count:
      1 !important;

    transition-duration:
      0.01ms !important;

    scroll-behavior:
      auto !important;
  }

}


