/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes admin-login-enter-left {

  from {
    opacity: 0;
    transform:
      translateX(-28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-login-enter-right {

  from {
    opacity: 0;
    transform:
      translateX(28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-bg-float-one {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(45px, -25px)
      scale(1.08);
  }

}

@keyframes admin-bg-float-two {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-35px, -35px)
      scale(1.06);
  }

}

@keyframes admin-secure-pulse {

  0%,
  100% {
    box-shadow:
      0 0 0 4px
      rgba(99,162,95,0.08);
  }

  50% {
    box-shadow:
      0 0 0 8px
      rgba(99,162,95,0.03);
  }

}

@keyframes admin-error-shake {

  0%,
  100% {
    transform:
      translateX(0);
  }

  25% {
    transform:
      translateX(-4px);
  }

  75% {
    transform:
      translateX(4px);
  }

}

@keyframes admin-login-spin {

  to {
    transform:
      rotate(360deg);
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

