/* =========================================================
   KRISHISETU PAGE TRANSITIONS
========================================================= */

.page-transition {
  animation:
    page-enter
    0.55s
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

.page-transition-exit {
  animation:
    page-exit
    0.28s
    ease
    both;
}


/* Destination page */

@keyframes page-enter {

  from {
    opacity: 0;
    transform:
      translateY(14px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}


/* Leaving page */

@keyframes page-exit {

  from {
    opacity: 1;
    transform:
      translateY(0);
  }

  to {
    opacity: 0;
    transform:
      translateY(-8px);
  }

}


/* Respect reduced-motion preference */

@media (prefers-reduced-motion: reduce) {

  .page-transition,
  .page-transition-exit {
    animation: none;
  }

}
/* =========================================================
   PREMIUM PAGE TRANSITION
========================================================= */

.page-transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(86, 160, 92, 0.18),
      transparent 38%
    ),
    rgba(248, 250, 246, 0.96);

  opacity: 0;
  visibility: hidden;

  transform:
    scale(1.08);

  transition:
    opacity 0.55s cubic-bezier(.76, 0, .24, 1),
    visibility 0.55s,
    transform 0.8s cubic-bezier(.76, 0, .24, 1);
}


.page-transition-overlay.active {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
}


.page-transition-glow {
  position: absolute;

  width: 45vw;
  height: 45vw;

  left: 50%;
  top: 50%;

  transform:
    translate(-50%, -50%);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(95, 170, 98, 0.14),
      rgba(95, 170, 98, 0.04) 40%,
      transparent 70%
    );

  filter:
    blur(20px);

  animation:
    page-transition-pulse
    1.1s
    ease-out
    both;
}


.page-transition-content {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  filter:
    blur(0);

  transition:
    opacity 0.7s cubic-bezier(.22, 1, .36, 1),
    transform 0.8s cubic-bezier(.22, 1, .36, 1),
    filter 0.7s ease;
}


.page-transition-content.active {
  opacity: 0;

  transform:
    translateY(18px)
    scale(0.985);

  filter:
    blur(8px);
}


@keyframes page-transition-pulse {

  0% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(0.72);
  }

  45% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(1.15);
  }

}

.page-transition {
  min-height: 100%;
  width: 100%;
  will-change: transform, opacity, filter;
}

