/* =========================================================
   KPI GRID
========================================================= */

.admin-dashboard-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));

  gap: 14px;

  margin-bottom: 22px;
}


/* =========================================================
   KPI CARD
========================================================= */

.admin-dashboard-kpi {
  position: relative;

  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 0;
  min-height: 104px;

  padding: 18px;

  border: 1px solid #e1e7e2;
  border-radius: 16px;

  background: #ffffff;

  box-shadow:
    0 4px 16px rgba(28, 43, 33, 0.04);

  overflow: hidden;

  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease,
    border-color 0.22s ease;
}

.admin-dashboard-kpi::after {
  content: "";

  position: absolute;

  right: -28px;
  bottom: -35px;

  width: 90px;
  height: 90px;

  border-radius: 50%;

  background: currentColor;

  opacity: 0.035;
}

.admin-dashboard-kpi:hover {
  transform: translateY(-3px);

  box-shadow:
    0 12px 28px rgba(28, 43, 33, 0.08);

  border-color: #d3ddd5;
}

.admin-dashboard-kpi-icon {
  display: grid;
  place-items: center;

  flex-shrink: 0;

  width: 43px;
  height: 43px;

  border-radius: 12px;
}

.admin-dashboard-kpi > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-dashboard-kpi strong {
  display: block;

  font-size: 28px;
  line-height: 1;

  font-weight: 800;
  letter-spacing: -0.025em;

  color: #18251d;
}

.admin-dashboard-kpi strong small {
  font-size: 13px;
  font-weight: 700;
}

.admin-dashboard-kpi span {
  display: block;

  font-size: 12px;
  line-height: 1.35;

  font-weight: 650;

  color: #718077;
}


