    0 9px 20px rgba(43, 69, 52, 0.10);
}


/* =========================================================
   NOTIFICATION
========================================================= */

.farmer-notification-button {
  position: relative;

  width: 52px;

  height: 52px;

  border:
    1px solid
    rgba(196, 149, 42, 0.28);

  border-radius: 15px;

  background:
    linear-gradient(
      145deg,
      #fff8d9,
      #f3df98
    );

  color: #9a7318;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

  box-shadow:
    0 9px 22px rgba(173, 126, 19, 0.15),
    inset 0 1px 0 rgba(255,255,255,.85);

  transition:
    transform .18s ease,
    box-shadow .18s ease;
}


.farmer-notification-button svg {
  width: 24px;

  height: 24px;
}


.farmer-notification-button:hover,
.farmer-notification-button.open {
  transform: translateY(-2px);

  box-shadow:
    0 14px 29px rgba(173, 126, 19, 0.20),
    0 0 0 5px rgba(214, 171, 65, 0.08);
}


.farmer-notification-button.has-unread {
  animation:
    farmer-bell-pulse
    2.8s
    ease-in-out
    infinite;
}


@keyframes farmer-bell-pulse {

  0%,
  100% {
    box-shadow:
      0 9px 22px rgba(173, 126, 19, 0.15),
      0 0 0 0 rgba(214, 171, 65, 0);
  }

  50% {
    box-shadow:
      0 13px 27px rgba(173, 126, 19, 0.19),
      0 0 0 7px rgba(214, 171, 65, 0.08);
  }

}


.farmer-notification-count {
  position: absolute;

  top: -8px;

  right: -8px;

  min-width: 26px;

  height: 26px;

  padding: 0 7px;

  border-radius: 999px;

  background: #d84b43;

  border: 3px solid #fff;

  color: #fff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 12px;

  font-weight: 800;

  box-shadow:
    0 5px 14px rgba(161, 54, 48, 0.22);
}


/* =========================================================
   MAIN BOOKING
========================================================= */

.next-booking-card {
  position: relative;

  overflow: hidden;

  border:
    1px solid
    rgba(40, 89, 54, 0.12);

  border-radius: 28px;

  padding: 31px;

  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f4faf4 100%
    );

  box-shadow:
    0 22px 58px rgba(36, 74, 48, 0.10),
    0 4px 12px rgba(36, 74, 48, 0.04);

  animation:
    farmer-card-rise
    .55s
    cubic-bezier(.2,.8,.2,1);
}


.next-booking-card::before {
  content: "";

  position: absolute;

  width: 330px;

  height: 330px;

  top: -160px;

  right: -120px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(91, 148, 94, 0.16),
      transparent 68%
    );

  pointer-events: none;
}


.next-booking-card::after {
  content: "";

  position: absolute;

  width: 190px;

  height: 190px;

  bottom: -100px;

  left: -70px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(222, 177, 62, 0.09),
      transparent 70%
    );

  pointer-events: none;
}


@keyframes farmer-card-rise {

  from {
    opacity: 0;

    transform:
      translateY(14px);
  }

  to {
    opacity: 1;

    transform:
      translateY(0);
  }

}


.next-booking-card.payment-complete {
  background:
    linear-gradient(
      135deg,
      #f7fcf5,
      #eef7ee
    );

  border-color:
    rgba(65, 130, 77, 0.18);
}


/* booking top */

