/* =========================================================
   NOTIFICATION OVERLAY
   Big and highly visible
========================================================= */

.farmer-notification-overlay {
  position:
    fixed;

  inset:
    0;

  z-index:
    9999;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  padding:
    28px;

  background:
    rgba(
      15,
      25,
      18,
      .48
    );

  backdrop-filter:
    blur(
      7px
    );
}


.farmer-notification-panel {
  width:
    min(
      760px,
      100%
    );

  max-height:
    min(
      780px,
      calc(100vh - 56px)
    );

  display:
    flex;

  flex-direction:
    column;

  overflow:
    hidden;

  border:
    1px solid
    rgba(
      255,
      255,
      255,
      .20
    );

  border-radius:
    25px;

  background:
    #fbfcfa;

  box-shadow:
    0 30px 80px
    rgba(
      0,
      0,
      0,
      .27
    );
}


.farmer-notification-header {
  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    20px;

  padding:
    24px
    26px;

  border-bottom:
    1px solid
    #e6ebe6;

  background:
    linear-gradient(
      135deg,
      #ffffff,
      #f4f8f4
    );
}


.farmer-notification-header .page-eyebrow {
  display:
    block;

  margin-bottom:
    5px;

  color:
    #728178;

  font-size:
    9px;

  font-weight:
    900;

  letter-spacing:
    .14em;
}


.farmer-notification-header strong {
  color:
    #274635;

  font-size:
    21px;

  font-weight:
    820;
}


.farmer-notification-close {
  width:
    42px;

  height:
    42px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  border:
    1px solid
    #dde5de;

  border-radius:
    12px;

  background:
    #ffffff;

  color:
    #67766c;

  cursor:
    pointer;

  transition:
    background .18s ease,
    color .18s ease,
    transform .18s ease;
}


.farmer-notification-close:hover {
  transform:
    rotate(
      4deg
    );

  background:
    #f1f6f1;

  color:
    #315f3f;
}


.farmer-notification-list {
  flex:
    1;

  overflow:
    auto;

  padding:
    10px
    13px
    15px;
}


.farmer-notification-list::-webkit-scrollbar {
  width:
    7px;
}


.farmer-notification-list::-webkit-scrollbar-thumb {
  border-radius:
    999px;

  background:
    #cbd7cc;
}


.farmer-notification-item {
  width:
    100%;

  display:
    flex;

  align-items:
    flex-start;

  gap:
    13px;

  padding:
    16px
    14px;

  border:
    1px solid
    transparent;

  border-radius:
    15px;

  background:
    transparent;

  text-align:
    left;

  cursor:
    pointer;

  transition:
    background .18s ease,
    border-color .18s ease,
    transform .18s ease;
}


.farmer-notification-item:hover {
  transform:
    translateX(2px);

  background:
    #f4f8f4;

  border-color:
    #e1e9e1;
}


.farmer-notification-item.unread {
  background:
    #fff9df;

  border-color:
    #eee0a8;
}


.farmer-notification-item.unread:hover {
  background:
    #fff6ce;
}


.farmer-notification-dot {
  width:
    11px;

  height:
    11px;

  min-width:
    11px;

  margin-top:
    6px;

  border-radius:
    50%;

  background:
    #cfd7d0;
}


.farmer-notification-item.unread
.farmer-notification-dot {
  background:
    #dfb529;

  box-shadow:
    0 0 0 5px
    rgba(
      223,
      181,
      41,
      .12
    );
}


.farmer-notification-content {
  min-width:
    0;

  flex:
    1;
}


.farmer-notification-content strong {
  display:
    block;

  color:
    #364e3d;

  font-size:
    14px;

  line-height:
    1.35;

  font-weight:
    810;
}


.farmer-notification-content span {
  display:
    block;

  margin-top:
    5px;

  color:
    #6f7d73;

  font-size:
    11.5px;

  line-height:
    1.6;
}


.farmer-notification-content small {
  display:
    block;

  margin-top:
    7px;

  color:
    #98a199;

  font-size:
    9px;

  font-weight:
    700;
}


.farmer-notification-empty {
  min-height:
    260px;

  display:
    flex;

  flex-direction:
    column;

  align-items:
    center;

  justify-content:
    center;

  gap:
    10px;

  color:
    #89958d;

  font-size:
    12px;

  text-align:
    center;
}


