/* =========================================================
   FARMER HOME — BRIGHT GOLD NOTIFICATION EFFECT
========================================================= */

.farmer-notification-button,
.farmer-notification-button.has-unread,
.farmer-notification-button.open {
  position: relative;

  color: #7a5a00 !important;

  border: 1px solid #e8c42d !important;

  background:
    linear-gradient(
      145deg,
      #fff3a3 0%,
      #ffd92f 48%,
      #f4c515 100%
    ) !important;

  box-shadow:
    0 8px 20px rgba(232, 187, 26, .22),
    inset 0 1px 0 rgba(255,255,255,.75) !important;

  overflow: visible;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    filter .2s ease !important;
}


.farmer-notification-button::before {
  content: "";

  position: absolute;

  inset: -4px;

  border-radius: 16px;

  background:
    rgba(255, 215, 55, .22);

  filter: blur(7px);

  z-index: -1;

  opacity: .65;

  transition:
    opacity .2s ease,
    transform .2s ease;
}


/* Hover */

.farmer-notification-button:hover,
.farmer-notification-button.has-unread:hover,
.farmer-notification-button.has-unread.open {
  transform:
    translateY(-3px)
    scale(1.04);

  color: #674900 !important;

  border-color:
    #d9ad12 !important;

  background:
    linear-gradient(
      145deg,
      #fff6b5 0%,
      #ffdc32 45%,
      #f0bc0e 100%
    ) !important;

  box-shadow:
    0 12px 28px rgba(220, 171, 16, .30),
    0 0 18px rgba(255, 215, 47, .24),
    inset 0 1px 0 rgba(255,255,255,.85) !important;

  filter:
    saturate(1.08);
}


.farmer-notification-button:hover::before,
.farmer-notification-button.has-unread:hover::before {
  opacity: .95;

  transform:
    scale(1.08);
}


/* =========================================================
   UNREAD — GENTLE ATTENTION PULSE
========================================================= */

.farmer-notification-button.has-unread {
  animation:
    farmerNotificationPulse 2.3s ease-in-out infinite;
}


@keyframes farmerNotificationPulse {

  0%,
  100% {
    box-shadow:
      0 8px 20px rgba(232, 187, 26, .22),
      0 0 0 0 rgba(255, 214, 38, .22),
      inset 0 1px 0 rgba(255,255,255,.75);
  }

  50% {
    box-shadow:
      0 10px 24px rgba(232, 187, 26, .28),
      0 0 0 8px rgba(255, 214, 38, .08),
      inset 0 1px 0 rgba(255,255,255,.82);
  }

}


/* =========================================================
   BADGE
========================================================= */

.farmer-notification-count {
  background:
    #b98500 !important;

  color:
    #ffffff !important;

  border:
    2px solid #fffdf0 !important;

  box-shadow:
    0 4px 12px rgba(158, 112, 0, .28),
    0 0 0 3px rgba(255, 211, 43, .16);

  animation:
    farmerNotificationBadge 1.8s ease-in-out infinite;
}


@keyframes farmerNotificationBadge {

  0%,
  100% {
    transform:
      scale(1);
  }

  50% {
    transform:
      scale(1.1);
  }

}


