/* =========================================================
   GLOBAL DARK THEME — HIGH CONTRAST STATIC / COLOURED BOXES
   Applies to pale cards, feature blocks, illustrations,
   headings, labels, descriptions and icons.
========================================================= */


/* ---------------------------------------------------------
   DARK / FOREST / MIDNIGHT DETECTION
--------------------------------------------------------- */

:is(
  .dark-theme,
  [data-theme="dark"],
  [data-theme="forest"],
  [data-theme="midnight"]
) {

  /* =======================================================
     GLOBAL COLOURED / STATIC CARDS
  ======================================================= */

  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="summary"],
    [class*="workflow"]
  ) {

    /*
     * Keep cards clearly distinct from the page background.
     */
    --global-card-text: #102018;
    --global-card-heading: #07150e;
    --global-card-muted: #315541;
    --global-card-icon: #145d38;
    --global-card-border: #65b77d;

    color: var(--global-card-text);
  }


  /* =======================================================
     GREEN
  ======================================================= */

  :is(
    .green,
    .green *,
    [class*="green"]
  ) {
    --global-card-text: #102218;
    --global-card-heading: #06140c;
    --global-card-muted: #2b5c43;
    --global-card-icon: #126338;
    --global-card-border: #58b976;
  }


  /* =======================================================
     BLUE
  ======================================================= */

  :is(
    .blue,
    .blue *,
    [class*="blue"]
  ) {
    --global-card-text: #101b2c;
    --global-card-heading: #07111f;
    --global-card-muted: #304c70;
    --global-card-icon: #174f8c;
    --global-card-border: #639bd2;
  }


  /* =======================================================
     GOLD / YELLOW
  ======================================================= */

  :is(
    .gold,
    .gold *,
    [class*="gold"],
    [class*="yellow"]
  ) {
    --global-card-text: #241c08;
    --global-card-heading: #171000;
    --global-card-muted: #63501f;
    --global-card-icon: #8a6500;
    --global-card-border: #d5ad45;
  }


  /* =======================================================
     ORANGE
  ======================================================= */

  :is(
    .orange,
    .orange *,
    [class*="orange"]
  ) {
    --global-card-text: #261509;
    --global-card-heading: #170900;
    --global-card-muted: #70421f;
    --global-card-icon: #a84f11;
    --global-card-border: #db8a45;
  }


  /* =======================================================
     PURPLE
  ======================================================= */

  :is(
    .purple,
    .purple *,
    [class*="purple"]
  ) {
    --global-card-text: #21152c;
    --global-card-heading: #13081d;
    --global-card-muted: #5d4170;
    --global-card-icon: #7042a0;
    --global-card-border: #b889d7;
  }


  /* =======================================================
     TEAL
  ======================================================= */

  :is(
    .teal,
    .teal *,
    [class*="teal"]
  ) {
    --global-card-text: #082522;
    --global-card-heading: #031411;
    --global-card-muted: #28635d;
    --global-card-icon: #14756d;
    --global-card-border: #68bbb3;
  }


  /* =======================================================
     FORCE TEXT CONTRAST INSIDE STATIC BOXES
  ======================================================= */

  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="summary"],
    [class*="workflow"]
  ) :is(
    h1,
    h2,
    h3,
    h4,
    strong,
    b
  ) {
    color: var(--global-card-heading) !important;
  }


  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="summary"],
    [class*="workflow"]
  ) :is(
    p,
    span,
    small,
    label
  ) {
    color: var(--global-card-muted) !important;
  }


  /* =======================================================
     SVG / ICONS
  ======================================================= */

  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="summary"],
    [class*="workflow"]
  ) svg {
    color: var(--global-card-icon) !important;
    stroke: var(--global-card-icon) !important;
  }


  /* =======================================================
     ICON CONTAINERS
  ======================================================= */

  :is(
    [class*="icon"],
    [class*="badge"],
    [class*="visual"]
  ) {
    color: var(--global-card-icon) !important;
  }


  :is(
    [class*="icon"],
    [class*="badge"],
    [class*="visual"]
  ) svg {
    color: inherit !important;
    stroke: currentColor !important;
  }


  /* =======================================================
     BUTTONS INSIDE STATIC COLOURED BOXES
  ======================================================= */

  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"]
  ) button {

    color: var(--global-card-heading) !important;
  }


  /* =======================================================
     FORM ELEMENTS INSIDE CARDS
  ======================================================= */

  :is(
    [class*="card"],
    [class*="box"],
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"]
  ) :is(
    input,
    select,
    textarea
  ) {
    color: #101820 !important;
    background: #ffffff !important;
    border-color: #6d8791 !important;
  }


  /* =======================================================
     PALE STATIC SURFACES
     The important part: stop them becoming near-white.
  ======================================================= */

  :is(
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="workflow"]
  ) {

    border-color: var(--global-card-border) !important;
  }


  /* -------------------------------------------------------
     Prevent hover from turning cards white
  ------------------------------------------------------- */

  :is(
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="workflow"]
  ):hover {

    color: var(--global-card-text) !important;
  }


  :is(
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="workflow"]
  ):hover :is(
    h1,
    h2,
    h3,
    h4,
    strong,
    b,
    p,
    span,
    small,
    label
  ) {
    color: var(--global-card-heading) !important;
  }


  /* -------------------------------------------------------
     Hover icons remain readable
  ------------------------------------------------------- */

  :is(
    [class*="feature"],
    [class*="topic"],
    [class*="guide"],
    [class*="checklist"],
    [class*="support"],
    [class*="contact"],
    [class*="security"],
    [class*="info"],
    [class*="notice"],
    [class*="tip"],
    [class*="workflow"]
  ):hover svg {
    color: var(--global-card-icon) !important;
    stroke: var(--global-card-icon) !important;
  }

}


/* =========================================================
   FOREST — STRONGER GREEN IDENTITY
========================================================= */

[data-theme="forest"] {

  background-color: #06140d;

  color: #e8fff0;

}

[data-theme="forest"] :is(
  [class*="card"],
